    pub fn record_recursive_attempt_start(
        &self,
        graph_id: RecursiveTaskGraphId,
        task_id: RecursiveTaskId,
        phase: RecursiveAttemptPhase,
        attempt_id: RecursiveAttemptId,
    ) -> Result<RecursiveTaskAttempt> {
        self.record_recursive_attempt_start_with_executor_kind(
            graph_id,
            task_id,
            phase,
            attempt_id,
            RecursiveExecutionMode::Fake,
        )
    }

    pub fn record_recursive_attempt_start_with_executor_kind(
        &self,
        graph_id: RecursiveTaskGraphId,
        task_id: RecursiveTaskId,
        phase: RecursiveAttemptPhase,
        attempt_id: RecursiveAttemptId,
        executor_kind: RecursiveExecutionMode,
    ) -> Result<RecursiveTaskAttempt> {
        let tx = self.conn.unchecked_transaction()?;
        ensure_recursive_graph_mutable_tx(&tx, graph_id)?;
        let detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        if detail.graph.execution_mode != executor_kind {
            return recursive_store_error(format!(
                "recursive attempt executor kind {} does not match graph {} execution mode {}",
                execution_mode_to_str(executor_kind),
                graph_id,
                execution_mode_to_str(detail.graph.execution_mode)
            ));
        }
        if !detail.nodes.iter().any(|node| node.id == task_id) {
            return recursive_store_error(format!("recursive task not found: {task_id}"));
        }
        if detail
            .attempts
            .iter()
            .any(|attempt| attempt.id == attempt_id)
        {
            return recursive_store_error(format!("duplicate recursive attempt id: {attempt_id}"));
        }

        let attempt_no = detail
            .attempts
            .iter()
            .filter(|attempt| attempt.task_id == task_id && attempt.phase == phase)
            .count()
            .saturating_add(1);
        let retry_count = detail
            .attempts
            .iter()
            .filter(|attempt| {
                attempt.task_id == task_id
                    && attempt.phase == phase
                    && matches!(
                        attempt.status,
                        RecursiveAttemptStatus::Failed | RecursiveAttemptStatus::Interrupted
                    )
            })
            .count();
        let dependency_snapshot = dependency_snapshot_for(&detail, task_id);
        let snapshot_json =
            serde_json::to_string(&dependency_snapshot).map_err(DaemonError::Json)?;
        let started_at = timestamp_now();
        tx.execute(
            "INSERT INTO recursive_task_attempts (
                id, graph_id, task_id, phase, attempt_no, retry_count, status,
                started_at, dependency_snapshot_json, executor_kind
             ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, 'running', ?7, ?8, ?9)",
            params![
                attempt_id.to_string(),
                graph_id.to_string(),
                task_id.to_string(),
                attempt_phase_to_str(phase),
                usize_to_i64("attempt_no", attempt_no)?,
                usize_to_i64("retry_count", retry_count)?,
                started_at,
                snapshot_json,
                execution_mode_to_str(executor_kind),
            ],
        )?;

        let detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        validate_detail(&detail).map_err(recursive_validation_error)?;
        let attempt = detail
            .attempts
            .into_iter()
            .find(|attempt| attempt.id == attempt_id)
            .ok_or_else(|| {
                DaemonError::Store(format!(
                    "recursive attempt missing after insert: {attempt_id}"
                ))
            })?;
        tx.commit()?;
        Ok(attempt)
    }

    pub fn record_recursive_attempt_finish(
        &self,
        graph_id: RecursiveTaskGraphId,
        attempt_id: RecursiveAttemptId,
        status: RecursiveAttemptStatus,
        failure_reason: Option<String>,
        block_reason: Option<String>,
        task_transition: Option<RecursiveTaskLifecycleState>,
        lifecycle_reason: Option<String>,
    ) -> Result<RecursiveTaskAttempt> {
        if status == RecursiveAttemptStatus::Running {
            return recursive_store_error("cannot finish an attempt with running status");
        }
        validate_attempt_finish_status(
            attempt_id,
            status,
            failure_reason.as_deref(),
            block_reason.as_deref(),
        )?;

        let tx = self.conn.unchecked_transaction()?;
        ensure_recursive_graph_mutable_tx(&tx, graph_id)?;
        let attempt =
            load_recursive_attempt_by_id(&tx, graph_id, attempt_id)?.ok_or_else(|| {
                DaemonError::Store(format!("recursive attempt not found: {attempt_id}"))
            })?;
        if attempt.status != RecursiveAttemptStatus::Running {
            return recursive_store_error(format!("recursive attempt {attempt_id} is not running"));
        }

        let finished_at = timestamp_now();
        tx.execute(
            "UPDATE recursive_task_attempts
             SET status = ?1, finished_at = ?2, failure_reason = ?3, block_reason = ?4
             WHERE graph_id = ?5 AND id = ?6",
            params![
                attempt_status_to_str(status),
                finished_at,
                failure_reason,
                block_reason,
                graph_id.to_string(),
                attempt_id.to_string(),
            ],
        )?;

        if let Some(to_status) = task_transition {
            transition_recursive_task_state_tx(
                &tx,
                graph_id,
                attempt.task_id,
                to_status,
                lifecycle_reason,
                &finished_at,
            )?;
        }
        sync_recursive_graph_status_tx(&tx, graph_id, &finished_at)?;

        let detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        validate_detail(&detail).map_err(recursive_validation_error)?;
        let attempt = detail
            .attempts
            .into_iter()
            .find(|attempt| attempt.id == attempt_id)
            .ok_or_else(|| {
                DaemonError::Store(format!(
                    "recursive attempt missing after finish: {attempt_id}"
                ))
            })?;
        tx.commit()?;
        Ok(attempt)
    }

    pub fn record_recursive_execution_artifacts(
        &self,
        graph_id: RecursiveTaskGraphId,
        artifacts: Vec<RecursiveExecutionArtifactCreate>,
    ) -> Result<Vec<RecursiveExecutionArtifact>> {
        if artifacts.is_empty() {
            return Ok(Vec::new());
        }

        let tx = self.conn.unchecked_transaction()?;
        ensure_recursive_graph_mutable_tx(&tx, graph_id)?;
        let detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        validate_artifact_creates(&detail, &artifacts)?;

        let created_at = timestamp_now();
        let mut inserted_ids = BTreeSet::new();
        for artifact in artifacts {
            let metadata_json =
                serde_json::to_string(&artifact.metadata).map_err(DaemonError::Json)?;
            tx.execute(
                "INSERT INTO recursive_execution_artifacts (
                    graph_id, task_id, attempt_id, kind, label, content, uri,
                    metadata_json, created_at
                 ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
                params![
                    graph_id.to_string(),
                    artifact.task_id.to_string(),
                    artifact.attempt_id.map(|id| id.to_string()),
                    artifact_kind_to_str(artifact.kind),
                    artifact.label,
                    artifact.content,
                    artifact.uri,
                    metadata_json,
                    created_at,
                ],
            )?;
            inserted_ids.insert(tx.last_insert_rowid());
        }

        let detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        validate_detail(&detail).map_err(recursive_validation_error)?;
        let inserted = detail
            .artifacts
            .into_iter()
            .filter(|artifact| inserted_ids.contains(&artifact.id))
            .collect();
        tx.commit()?;
        Ok(inserted)
    }

