    pub fn create_recursive_live_attempt_placeholder(
        &self,
        create: RecursiveLiveAttemptCreate,
    ) -> Result<RecursiveLiveAttemptDetail> {
        validate_live_attempt_create(&create)?;
        let tx = self.conn.unchecked_transaction()?;
        let context = validate_live_attempt_create_context_tx(&tx, &create, false)?;
        let live = insert_recursive_live_attempt_create_tx(&tx, &create, &context)?;
        if live.summary.task_id != context.task.id {
            return recursive_store_error("recursive live attempt task mismatch after insert");
        }
        tx.commit()?;
        Ok(live)
    }

    pub fn create_or_load_recursive_live_attempt(
        &self,
        create: RecursiveLiveAttemptCreate,
    ) -> Result<RecursiveLiveAttemptCreateOrLoadResult> {
        validate_live_attempt_create(&create)?;
        let tx = unchecked_immediate_transaction(&self.conn)?;
        if let Some(existing) =
            load_recursive_live_attempt_by_attempt_id_tx(&tx, create.graph_id, create.attempt_id)?
        {
            validate_existing_live_attempt_create_correlation_tx(&tx, &existing, &create)?;
            tx.commit()?;
            return Ok(RecursiveLiveAttemptCreateOrLoadResult {
                live_attempt: existing,
                inserted: false,
            });
        }

        let context = validate_live_attempt_create_context_tx(&tx, &create, true)?;
        let live = insert_recursive_live_attempt_create_tx(&tx, &create, &context)?;
        tx.commit()?;
        Ok(RecursiveLiveAttemptCreateOrLoadResult {
            live_attempt: live,
            inserted: true,
        })
    }

