    pub fn mark_recursive_live_interrupt_sent(
        &self,
        id: RecursiveLiveInterruptId,
    ) -> Result<RecursiveLiveInterruptSummary> {
        let tx = self.conn.unchecked_transaction()?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive live interrupt not found: {id}"))
        })?;
        if interrupt.status != RecursiveLiveInterruptStatus::Requested {
            tx.commit()?;
            return Ok(interrupt);
        }
        let sent_at = timestamp_now();
        tx.execute(
            "UPDATE recursive_live_interrupts
             SET status = 'sent', sent_at = COALESCE(sent_at, ?1)
             WHERE id = ?2 AND status = 'requested'",
            params![sent_at, id.to_string()],
        )?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive live interrupt missing after sent update: {id}"
            ))
        })?;
        tx.commit()?;
        Ok(interrupt)
    }

    pub fn mark_recursive_live_interrupt_interrupted(
        &self,
        id: RecursiveLiveInterruptId,
    ) -> Result<RecursiveLiveInterruptSummary> {
        let tx = self.conn.unchecked_transaction()?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive live interrupt not found: {id}"))
        })?;
        if interrupt.status == RecursiveLiveInterruptStatus::Interrupted {
            tx.commit()?;
            return Ok(interrupt);
        }
        if matches!(
            interrupt.status,
            RecursiveLiveInterruptStatus::Failed
                | RecursiveLiveInterruptStatus::Rejected
                | RecursiveLiveInterruptStatus::Ignored
        ) {
            return recursive_store_error(format!(
                "cannot mark terminal recursive live interrupt {id} as interrupted from status {}",
                live_interrupt_status_to_str(interrupt.status)
            ));
        }
        let live =
            load_recursive_live_attempt_tx(&tx, interrupt.live_attempt_id)?.ok_or_else(|| {
                DaemonError::Store(format!(
                    "recursive live attempt not found: {}",
                    interrupt.live_attempt_id
                ))
            })?;
        if live.summary.session_id.is_none() {
            return recursive_store_error(format!(
                "cannot mark recursive live attempt {} interrupted without an attached session id",
                live.summary.id
            ));
        }
        if !matches!(
            live.summary.status,
            RecursiveLiveAttemptStatus::Running | RecursiveLiveAttemptStatus::WaitingApproval
        ) {
            return recursive_store_error(format!(
                "cannot mark recursive live attempt {} interrupted from status {}",
                live.summary.id,
                live_attempt_status_to_str(live.summary.status)
            ));
        }

        let completed_at = timestamp_now();
        tx.execute(
            "UPDATE recursive_live_interrupts
             SET status = 'interrupted',
                 sent_at = COALESCE(sent_at, ?1),
                 completed_at = COALESCE(completed_at, ?1)
             WHERE id = ?2 AND status IN ('requested', 'sent')",
            params![completed_at, id.to_string()],
        )?;
        tx.execute(
            "UPDATE recursive_live_attempts
             SET status = 'interrupted',
                 completed_at = COALESCE(completed_at, ?1),
                 interruption_reason = COALESCE(interruption_reason, ?2),
                 cancellation_request_id = COALESCE(cancellation_request_id, ?3),
                 lease_owner = NULL,
                 lease_token = NULL,
                 heartbeat_at = NULL,
                 lease_expires_at = NULL,
                 updated_at = ?1
             WHERE id = ?4 AND status IN ('running', 'waiting_approval')",
            params![
                completed_at,
                interrupt.reason,
                interrupt
                    .cancellation_request_id
                    .map(|request_id| request_id.to_string()),
                interrupt.live_attempt_id.to_string(),
            ],
        )?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive live interrupt missing after interrupted update: {id}"
            ))
        })?;
        tx.commit()?;
        Ok(interrupt)
    }

    pub fn mark_recursive_live_interrupt_failed(
        &self,
        id: RecursiveLiveInterruptId,
        failure_reason: String,
    ) -> Result<RecursiveLiveInterruptSummary> {
        validate_nonempty("recursive live interrupt failure_reason", &failure_reason)?;
        let tx = self.conn.unchecked_transaction()?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive live interrupt not found: {id}"))
        })?;
        if matches!(
            interrupt.status,
            RecursiveLiveInterruptStatus::Interrupted | RecursiveLiveInterruptStatus::Failed
        ) {
            tx.commit()?;
            return Ok(interrupt);
        }
        if matches!(
            interrupt.status,
            RecursiveLiveInterruptStatus::Rejected | RecursiveLiveInterruptStatus::Ignored
        ) {
            return recursive_store_error(format!(
                "cannot mark recursive live interrupt {id} failed from status {}",
                live_interrupt_status_to_str(interrupt.status)
            ));
        }
        let completed_at = timestamp_now();
        tx.execute(
            "UPDATE recursive_live_interrupts
             SET status = 'failed',
                 failure_reason = ?1,
                 sent_at = CASE WHEN status = 'sent' THEN COALESCE(sent_at, ?2) ELSE sent_at END,
                 completed_at = COALESCE(completed_at, ?2)
             WHERE id = ?3 AND status IN ('requested', 'sent', 'failed')",
            params![failure_reason, completed_at, id.to_string()],
        )?;
        tx.execute(
            "UPDATE recursive_live_attempts
             SET interruption_reason = COALESCE(interruption_reason, ?1),
                 error = ?1,
                 updated_at = ?2
             WHERE id = ?3 AND status IN ('running', 'waiting_approval')",
            params![
                failure_reason,
                completed_at,
                interrupt.live_attempt_id.to_string()
            ],
        )?;
        let interrupt = load_recursive_live_interrupt_tx(&tx, id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive live interrupt missing after failed update: {id}"
            ))
        })?;
        tx.commit()?;
        Ok(interrupt)
    }

