    pub fn heartbeat_recursive_scheduler_run_lease(
        &self,
        run_id: RecursiveSchedulerRunId,
        lease_token: &str,
        lease_ttl_seconds: i64,
    ) -> Result<RecursiveSchedulerRunSummary> {
        validate_nonempty("recursive scheduler lease token", lease_token)?;
        if lease_ttl_seconds <= 0 {
            return recursive_store_error("recursive scheduler lease ttl must be positive");
        }

        let tx = unchecked_immediate_transaction(&self.conn)?;
        let heartbeat_at = Utc::now();
        let heartbeat_at_str = timestamp_to_string(heartbeat_at);

        let run = load_recursive_scheduler_run_tx(&tx, run_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive scheduler run not found: {run_id}"))
        })?;
        if !matches!(
            run.status,
            RecursiveSchedulerRunStatus::Running | RecursiveSchedulerRunStatus::Cancelling
        ) {
            return recursive_store_error(format!(
                "recursive scheduler run {run_id} is not active"
            ));
        }
        if run.lease_token.as_deref() != Some(lease_token) {
            return recursive_store_error(format!(
                "recursive scheduler run {run_id} lease token mismatch"
            ));
        }
        if scheduler_run_lease_expired(&run, heartbeat_at) {
            mark_recursive_scheduler_run_lease_expired_tx(
                &tx,
                run.id,
                run.graph_id,
                &heartbeat_at_str,
            )?;
            tx.commit()?;
            return recursive_store_error(format!(
                "recursive scheduler run {run_id} lease expired"
            ));
        }

        let lease_expires_at =
            timestamp_to_string(heartbeat_at + Duration::seconds(lease_ttl_seconds));
        let changed = tx.execute(
            "UPDATE recursive_scheduler_runs
             SET lease_heartbeat_at = ?1, lease_expires_at = ?2
             WHERE id = ?3 AND status IN ('running', 'cancelling') AND lease_token = ?4",
            params![
                heartbeat_at_str,
                lease_expires_at,
                run_id.to_string(),
                lease_token,
            ],
        )?;
        if changed == 0 {
            return recursive_store_error(format!(
                "recursive scheduler run {run_id} lease heartbeat lost active run"
            ));
        }
        let run = load_recursive_scheduler_run_tx(&tx, run_id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive scheduler run missing after lease heartbeat: {run_id}"
            ))
        })?;
        tx.commit()?;
        Ok(run)
    }

