    pub fn request_recursive_task_cancellation(
        &self,
        graph_id: RecursiveTaskGraphId,
        task_id: RecursiveTaskId,
        create: RecursiveCancellationRequestCreate,
    ) -> Result<RecursiveCancellationRequestSummary> {
        validate_cancellation_request_create(&create)?;
        let tx = self.conn.unchecked_transaction()?;
        load_recursive_graph_summary(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
        })?;
        let task_exists: bool = tx
            .query_row(
                "SELECT 1 FROM recursive_task_nodes WHERE graph_id = ?1 AND id = ?2",
                params![graph_id.to_string(), task_id.to_string()],
                |_| Ok(true),
            )
            .optional()?
            .unwrap_or(false);
        if !task_exists {
            return recursive_store_error(format!("recursive task not found: {task_id}"));
        }
        let request_id = RecursiveCancellationRequestId::new();
        let requested_at = timestamp_now();
        insert_recursive_cancellation_request_tx(
            &tx,
            request_id,
            RecursiveCancellationScope::Task,
            graph_id,
            None,
            Some(task_id),
            create,
            None,
            RecursiveCancellationRequestStatus::Requested,
            None,
            None,
            None,
            &requested_at,
        )?;
        let request =
            load_recursive_cancellation_request_tx(&tx, request_id)?.ok_or_else(|| {
                DaemonError::Store(format!(
                    "recursive cancellation request missing after insert: {request_id}"
                ))
            })?;
        tx.commit()?;
        Ok(request)
    }

