    pub fn load_recursive_recovery_graph_status(
        &self,
        graph_id: RecursiveTaskGraphId,
    ) -> Result<Option<RecursiveGraphRecoveryStatus>> {
        if let Some(status) =
            load_recursive_recovery_graph_status_tx(&self.conn, &graph_id.to_string())?
        {
            return Ok(Some(status));
        }
        let Some(graph) = load_recursive_graph_summary(&self.conn, graph_id)? else {
            return Ok(None);
        };
        let state = if is_recursive_graph_quarantined(&graph) {
            RecursiveGraphRecoveryState::Quarantined
        } else if graph.status == RecursiveGraphStatus::Active {
            RecursiveGraphRecoveryState::PendingRecovery
        } else {
            RecursiveGraphRecoveryState::Recovered
        };
        Ok(Some(RecursiveGraphRecoveryStatus {
            graph_id: Some(graph_id),
            raw_graph_id: graph_id.to_string(),
            state,
            pass_id: None,
            last_attempted_at: graph.recovery_checked_at,
            completed_at: graph.recovered_at,
            deferred_at: None,
            reason: graph.quarantine_reason.or(graph.malformed_reason),
            last_error: None,
            updated_at: graph.updated_at,
        }))
    }

    fn run_recursive_recovery_pass(
        &self,
        budget: RecursiveRecoveryBudget,
    ) -> Result<RecursiveRecoveryPassSummary> {
        validate_recovery_budget(&budget)?;

        let pass_id = RecursiveRecoveryPassId::new();
        let started_at = timestamp_now();
        insert_recursive_recovery_pass(&self.conn, pass_id, &budget, &started_at, None)?;

        let mut stats = RecursiveRecoveryPassStats::default();
        let mut last_raw_graph_id = None;
        if let Err(error) = self.execute_recursive_recovery_pass(
            &budget,
            pass_id,
            &started_at,
            &mut stats,
            &mut last_raw_graph_id,
        ) {
            stats.errors = stats.errors.saturating_add(1);
            let completed_at = timestamp_now();
            let error_message = error.to_string();
            if let Err(finish_error) = finish_recursive_recovery_pass(
                &self.conn,
                pass_id,
                RecursiveRecoveryPassStatus::Failed,
                &stats,
                last_raw_graph_id.as_deref(),
                Some(RecursiveRecoveryStopReason::StoreError),
                Some(&error_message),
                &completed_at,
            ) {
                return Err(DaemonError::Store(format!(
                    "recursive recovery failed: {error}; additionally failed to persist recovery pass failure: {finish_error}"
                )));
            }
            return Err(error);
        }

        load_recursive_recovery_pass_tx(&self.conn, pass_id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive recovery pass missing after completion: {pass_id}"
            ))
        })
    }

    fn execute_recursive_recovery_pass(
        &self,
        budget: &RecursiveRecoveryBudget,
        pass_id: RecursiveRecoveryPassId,
        started_at: &str,
        stats: &mut RecursiveRecoveryPassStats,
        last_raw_graph_id: &mut Option<String>,
    ) -> Result<()> {
        let candidates = load_recursive_recovery_candidates(&self.conn, started_at)?;
        self.execute_recursive_recovery_pass_for_candidates(
            budget,
            pass_id,
            candidates,
            stats,
            last_raw_graph_id,
        )
    }

    fn execute_recursive_recovery_pass_for_candidates(
        &self,
        budget: &RecursiveRecoveryBudget,
        pass_id: RecursiveRecoveryPassId,
        candidates: Vec<RecursiveRecoveryCandidate>,
        stats: &mut RecursiveRecoveryPassStats,
        last_raw_graph_id: &mut Option<String>,
    ) -> Result<()> {
        let started = Instant::now();
        let time_budget = budget.time_budget_ms.map(StdDuration::from_millis);
        let mut stop_reason = None;
        let mut next_index = 0usize;

        while next_index < candidates.len() {
            if stats.checked >= u64::from(budget.max_graphs) {
                stop_reason = Some(RecursiveRecoveryStopReason::MaxGraphs);
                break;
            }
            if let Some(time_budget) = time_budget
                && started.elapsed() >= time_budget
            {
                stop_reason = Some(RecursiveRecoveryStopReason::TimeBudget);
                break;
            }

            let candidate = &candidates[next_index];
            next_index = next_index.saturating_add(1);
            let attempted_at = timestamp_now();
            *last_raw_graph_id = Some(candidate.raw_graph_id.clone());
            stats.checked = stats.checked.saturating_add(1);

            match candidate.graph_id {
                Some(graph_id) => match self.recover_recursive_task_graph(graph_id) {
                    Ok(result) => {
                        if result.quarantined {
                            stats.quarantined = stats.quarantined.saturating_add(1);
                            upsert_recursive_recovery_graph_state(
                                &self.conn,
                                &candidate.raw_graph_id,
                                RecursiveGraphRecoveryState::Quarantined,
                                pass_id,
                                Some(&attempted_at),
                                Some(&attempted_at),
                                None,
                                result.reason.as_deref(),
                                None,
                                &attempted_at,
                            )?;
                            clear_deferred_recursive_recovery_graph(
                                &self.conn,
                                &candidate.raw_graph_id,
                            )?;
                        } else {
                            if result.recovered {
                                stats.recovered = stats.recovered.saturating_add(1);
                            } else {
                                stats.skipped = stats.skipped.saturating_add(1);
                            }
                            upsert_recursive_recovery_graph_state(
                                &self.conn,
                                &candidate.raw_graph_id,
                                RecursiveGraphRecoveryState::Recovered,
                                pass_id,
                                Some(&attempted_at),
                                Some(&attempted_at),
                                None,
                                result.reason.as_deref(),
                                None,
                                &attempted_at,
                            )?;
                            clear_deferred_recursive_recovery_graph(
                                &self.conn,
                                &candidate.raw_graph_id,
                            )?;
                        }
                    }
                    Err(error) => {
                        let last_error = error.to_string();
                        stats.errors = stats.errors.saturating_add(1);
                        stats.deferred = stats.deferred.saturating_add(1);
                        defer_recursive_recovery_graph(
                            &self.conn,
                            &candidate.raw_graph_id,
                            pass_id,
                            &attempted_at,
                            "recovery_error",
                            Some(&attempted_at),
                            Some(&last_error),
                        )?;
                    }
                },
                None => {
                    let reason = format!(
                        "invalid recursive graph id during recovery: {}",
                        candidate.raw_graph_id
                    );
                    if quarantine_recursive_task_graph_raw(
                        &self.conn,
                        &candidate.raw_graph_id,
                        &reason,
                    )? {
                        stats.quarantined = stats.quarantined.saturating_add(1);
                    }
                    upsert_recursive_recovery_graph_state(
                        &self.conn,
                        &candidate.raw_graph_id,
                        RecursiveGraphRecoveryState::Quarantined,
                        pass_id,
                        Some(&attempted_at),
                        Some(&attempted_at),
                        None,
                        Some(&reason),
                        None,
                        &attempted_at,
                    )?;
                    clear_deferred_recursive_recovery_graph(&self.conn, &candidate.raw_graph_id)?;
                }
            }

            if let Some(time_budget) = time_budget
                && next_index < candidates.len()
                && started.elapsed() >= time_budget
            {
                stop_reason = Some(RecursiveRecoveryStopReason::TimeBudget);
                break;
            }
        }

        if let Some(stop_reason) = stop_reason {
            let deferred_at = timestamp_now();
            let reason = recovery_stop_reason_to_str(stop_reason);
            for candidate in &candidates[next_index..] {
                stats.deferred = stats.deferred.saturating_add(1);
                defer_recursive_recovery_graph(
                    &self.conn,
                    &candidate.raw_graph_id,
                    pass_id,
                    &deferred_at,
                    reason,
                    None,
                    None,
                )?;
            }
        }

        let completed_at = timestamp_now();
        let status = if stop_reason.is_some() || stats.deferred > 0 {
            RecursiveRecoveryPassStatus::Deferred
        } else {
            RecursiveRecoveryPassStatus::Completed
        };
        finish_recursive_recovery_pass(
            &self.conn,
            pass_id,
            status,
            stats,
            last_raw_graph_id.as_deref(),
            stop_reason
                .or_else(|| (stats.errors > 0).then_some(RecursiveRecoveryStopReason::StoreError))
                .or(Some(RecursiveRecoveryStopReason::Completed)),
            None,
            &completed_at,
        )?;
        Ok(())
    }

    pub fn recover_recursive_task_graph(
        &self,
        graph_id: RecursiveTaskGraphId,
    ) -> Result<RecursiveGraphRecoveryResult> {
        let tx = self.conn.unchecked_transaction()?;
        let at = timestamp_now();
        let detail = match load_recursive_graph_detail(&tx, graph_id) {
            Ok(Some(detail)) => detail,
            Ok(None) => {
                return Err(DaemonError::Store(format!(
                    "recursive DAG graph not found: {graph_id}"
                )));
            }
            Err(error) => {
                let reason = format!("recursive DAG recovery load failed: {error}");
                quarantine_recursive_task_graph_tx(&tx, graph_id, &reason, &at)?;
                tx.commit()?;
                return Ok(RecursiveGraphRecoveryResult {
                    graph_id,
                    recovered: false,
                    quarantined: true,
                    reason: Some(reason),
                });
            }
        };

        if is_recursive_graph_quarantined(&detail.graph) {
            tx.commit()?;
            return Ok(RecursiveGraphRecoveryResult {
                graph_id,
                recovered: false,
                quarantined: true,
                reason: detail
                    .graph
                    .quarantine_reason
                    .or(detail.graph.malformed_reason),
            });
        }

        if let Err(error) = validate_detail_for_recovery(&detail) {
            let reason = format!("recursive DAG integrity validation failed: {error}");
            quarantine_recursive_task_graph_tx(&tx, graph_id, &reason, &at)?;
            tx.commit()?;
            return Ok(RecursiveGraphRecoveryResult {
                graph_id,
                recovered: false,
                quarantined: true,
                reason: Some(reason),
            });
        }

        let mut recovered = recover_recursive_task_graph_tx(&tx, &detail, &at)?;
        let recovered_detail = load_recursive_graph_detail(&tx, graph_id)?.ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive DAG graph not found after recovery: {graph_id}"
            ))
        })?;
        if let Err(error) = validate_detail(&recovered_detail) {
            let reason = format!("recursive DAG post-recovery validation failed: {error}");
            quarantine_recursive_task_graph_tx(&tx, graph_id, &reason, &at)?;
            recovered = false;
            tx.commit()?;
            return Ok(RecursiveGraphRecoveryResult {
                graph_id,
                recovered,
                quarantined: true,
                reason: Some(reason),
            });
        }

        tx.commit()?;
        Ok(RecursiveGraphRecoveryResult {
            graph_id,
            recovered,
            quarantined: false,
            reason: recovered.then(|| "daemon restart recovery".to_string()),
        })
    }

    pub fn quarantine_recursive_task_graph(
        &self,
        graph_id: RecursiveTaskGraphId,
        reason: String,
    ) -> Result<()> {
        validate_nonempty("quarantine reason", &reason)?;
        let tx = self.conn.unchecked_transaction()?;
        let at = timestamp_now();
        quarantine_recursive_task_graph_tx(&tx, graph_id, &reason, &at)?;
        tx.commit()?;
        Ok(())
    }

    pub fn list_quarantined_recursive_task_graphs(&self) -> Result<Vec<RecursiveTaskGraphSummary>> {
        let mut stmt = self.conn.prepare(
            "SELECT id FROM recursive_task_graphs
             WHERE status = 'malformed' OR quarantined_at IS NOT NULL
             ORDER BY quarantined_at DESC, updated_at DESC, id ASC",
        )?;
        let graph_ids = stmt
            .query_map([], |row| row.get::<_, String>(0))?
            .collect::<std::result::Result<Vec<_>, _>>()?;
        drop(stmt);
        graph_ids
            .into_iter()
            .map(|id| {
                let graph_id = RecursiveTaskGraphId(parse_uuid("recursive graph id", &id)?);
                load_recursive_graph_summary(&self.conn, graph_id)?.ok_or_else(|| {
                    DaemonError::Store(format!("recursive DAG graph not found: {graph_id}"))
                })
            })
            .collect()
    }

