    pub fn list_recursive_task_graphs(
        &self,
        filter: RecursiveTaskGraphListFilter,
    ) -> Result<Vec<RecursiveTaskGraphSummary>> {
        let mut stmt = self.conn.prepare(
            "SELECT id FROM recursive_task_graphs ORDER BY updated_at DESC, created_at DESC, id ASC",
        )?;
        let graph_ids = stmt
            .query_map([], |row| row.get::<_, String>(0))?
            .collect::<std::result::Result<Vec<_>, _>>()?;
        drop(stmt);

        let mut summaries = Vec::new();
        for id in graph_ids {
            let graph_id = RecursiveTaskGraphId(parse_uuid("recursive graph id", &id)?);
            let Some(summary) = load_recursive_graph_summary(&self.conn, graph_id)? else {
                continue;
            };
            if !filter.include_quarantined && is_recursive_graph_quarantined(&summary) {
                continue;
            }
            if filter.project_id.is_some() && summary.project_id != filter.project_id {
                continue;
            }
            if filter.workflow_id.is_some() && summary.workflow_id != filter.workflow_id {
                continue;
            }
            if filter.topology_id.is_some() && summary.topology_id != filter.topology_id {
                continue;
            }
            if filter.parent_session_id.is_some()
                && summary.parent_session_id != filter.parent_session_id
            {
                continue;
            }
            if let Some(status) = filter.status
                && summary.status != status
            {
                continue;
            }
            summaries.push(summary);
        }
        Ok(summaries)
    }

