fn sort_topology_recursive_graph_statuses(statuses: &mut [TopologyRecursiveGraphStatus]) {
    statuses.sort_by(|left, right| {
        left.source_topology_iteration
            .cmp(&right.source_topology_iteration)
            .then_with(|| {
                left.source_topology_node_id
                    .cmp(&right.source_topology_node_id)
            })
            .then_with(|| left.created_at.cmp(&right.created_at))
            .then_with(|| left.graph_id.cmp(&right.graph_id))
    });
}

fn sort_topology_recursive_node_statuses(statuses: &mut [TopologyRecursiveNodeStatus]) {
    statuses.sort_by(|left, right| {
        left.topology_iteration
            .cmp(&right.topology_iteration)
            .then_with(|| left.topology_node_id.cmp(&right.topology_node_id))
            .then_with(|| left.graph_id.cmp(&right.graph_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
}

fn parse_json_value(label: &str, value: &str) -> Result<serde_json::Value> {
    serde_json::from_str(value).map_err(|error| DaemonError::Store(format!("{label}: {error}")))
}

fn load_recursive_graph_detail(
    conn: &Connection,
    graph_id: RecursiveTaskGraphId,
) -> Result<Option<RecursiveTaskGraphDetail>> {
    let Some(graph) = load_recursive_graph_summary(conn, graph_id)? else {
        return Ok(None);
    };

    Ok(Some(RecursiveTaskGraphDetail {
        nodes: load_recursive_nodes(conn, graph_id)?,
        edges: load_recursive_edges(conn, graph_id)?,
        attempts: load_recursive_attempts(conn, graph_id)?,
        injection_batches: load_recursive_injection_batches(conn, graph_id)?,
        lifecycle_events: load_recursive_lifecycle_events(conn, graph_id)?,
        artifacts: load_recursive_artifacts(conn, graph_id)?,
        graph,
    }))
}

fn load_recursive_graph_summary(
    conn: &Connection,
    graph_id: RecursiveTaskGraphId,
) -> Result<Option<RecursiveTaskGraphSummary>> {
    let mut stmt = conn.prepare(
        "SELECT id, root_task_id, title, objective, status, project_id, workflow_id,
                topology_id, parent_session_id, source_execution_id, source_eval_id,
                execution_mode, max_depth, max_fanout, max_descendants, step_limit,
                last_stop_reason, malformed_reason, created_at, updated_at, recovered_at,
                quarantined_at, quarantine_reason, recovery_checked_at
         FROM recursive_task_graphs
         WHERE id = ?1",
    )?;
    let mut rows = stmt.query_map(params![graph_id.to_string()], map_graph_row)?;

    match rows.next() {
        Some(Ok(row)) => Ok(Some(row.into_model()?)),
        Some(Err(error)) => Err(DaemonError::Database(error)),
        None => Ok(None),
    }
}

