fn load_recursive_artifact_readback_by_id(
    conn: &Connection,
    graph_id: RecursiveTaskGraphId,
    artifact_id: i64,
) -> Result<RecursiveExecutionArtifactLookup> {
    let Some(row) = load_recursive_artifact_row_by_id(conn, artifact_id)? else {
        return Ok(RecursiveExecutionArtifactLookup::NotFound);
    };
    if row.graph_id != graph_id.to_string() {
        return Ok(RecursiveExecutionArtifactLookup::GraphMismatch {
            actual_graph_id: row.graph_id,
        });
    }

    let (artifact, metadata_state, mut warnings) = row.into_model_tolerant()?;
    let role = artifact_role_from_metadata(&artifact.metadata, artifact.id, &mut warnings);
    if role.is_none() && metadata_state != RecursiveArtifactMetadataState::Malformed {
        push_artifact_warning(
            &mut warnings,
            "RECURSIVE_ARTIFACT_ROLE_UNAVAILABLE",
            "artifact has no trusted role metadata",
            artifact.id,
        );
    }
    let owners = artifact_owners_from_metadata(&artifact, &mut warnings);
    let provenance = artifact_provenance(role);
    let preview = artifact_preview_availability(
        artifact.kind,
        artifact.content.is_some(),
        artifact.uri.as_deref(),
    );

    Ok(RecursiveExecutionArtifactLookup::Found(
        RecursiveExecutionArtifactReadback {
            artifact,
            role,
            provenance,
            owners,
            preview,
            metadata_state,
            warnings,
        },
    ))
}

fn preview_recursive_artifact_by_id(
    conn: &Connection,
    graph_id: RecursiveTaskGraphId,
    artifact_id: i64,
    options: RecursiveExecutionArtifactPreviewOptions,
) -> Result<RecursiveExecutionArtifactPreviewLookup> {
    let Some(row) = load_recursive_artifact_row_by_id(conn, artifact_id)? else {
        return Ok(RecursiveExecutionArtifactPreviewLookup::NotFound);
    };
    if row.graph_id != graph_id.to_string() {
        return Ok(RecursiveExecutionArtifactPreviewLookup::GraphMismatch {
            actual_graph_id: row.graph_id,
        });
    }

    let (artifact, _metadata_state, warnings) = row.into_model_tolerant()?;
    Ok(RecursiveExecutionArtifactPreviewLookup::Found(
        preview_recursive_artifact(artifact, warnings, options)?,
    ))
}

fn list_recursive_artifact_summaries(
    conn: &Connection,
    filter: RecursiveExecutionArtifactSummaryListFilter,
    options: RecursiveExecutionArtifactSummaryPageOptions,
) -> Result<RecursiveReadPage<RecursiveExecutionArtifactSummary>> {
    if options.limit == 0 {
        return Err(DaemonError::InvalidParam(
            "recursive artifact summary page limit must be positive".to_string(),
        ));
    }
    let limit = options.limit.min(MAX_RECURSIVE_READ_PAGE_LIMIT);
    let (where_clause, values) = recursive_artifact_summary_where(&filter, options.after);
    let fetch_limit = limit.saturating_add(1);
    let sql = format!(
        "SELECT id, graph_id, task_id, attempt_id, kind, label, uri,
                metadata_json, created_at,
                CASE WHEN content IS NULL THEN 0 ELSE 1 END,
                length(CAST(content AS BLOB))
         FROM recursive_execution_artifacts
         WHERE {where_clause}
         ORDER BY created_at DESC, id DESC
         LIMIT {fetch_limit}"
    );
    let mut stmt = conn.prepare(&sql)?;
    let params = rusqlite::params_from_iter(values.iter().map(String::as_str));
    let rows = stmt
        .query_map(params, map_artifact_summary_row)?
        .collect::<std::result::Result<Vec<_>, _>>()?;

    let has_more = rows.len() > limit as usize;
    let mut warnings = Vec::new();
    let mut items = Vec::new();
    for row in rows.into_iter().take(limit as usize) {
        let (summary, row_warnings) = row.into_summary()?;
        items.push(summary);
        for warning in row_warnings {
            push_warning_capped(&mut warnings, warning);
        }
    }
    let total_count = if options.include_total {
        Some(count_recursive_artifact_summaries(conn, &filter)?)
    } else {
        None
    };

    Ok(RecursiveReadPage {
        items,
        limit,
        next_cursor: None,
        has_more,
        total_count,
        warnings,
    })
}

fn count_recursive_artifact_summaries(
    conn: &Connection,
    filter: &RecursiveExecutionArtifactSummaryListFilter,
) -> Result<u64> {
    let (where_clause, values) = recursive_artifact_summary_where(filter, None);
    let sql = format!(
        "SELECT COUNT(*)
         FROM recursive_execution_artifacts
         WHERE {where_clause}"
    );
    let count: i64 = conn.query_row(
        &sql,
        rusqlite::params_from_iter(values.iter().map(String::as_str)),
        |row| row.get(0),
    )?;
    i64_to_u64("recursive artifact summary total_count", count)
}

fn recursive_artifact_summary_where(
    filter: &RecursiveExecutionArtifactSummaryListFilter,
    after: Option<RecursiveExecutionArtifactSummaryPageCursor>,
) -> (String, Vec<String>) {
    let mut sql = "graph_id = ?1".to_string();
    let mut values = vec![filter.graph_id.to_string()];
    if let Some(task_id) = filter.task_id {
        let index = values.len() + 1;
        sql.push_str(&format!(" AND task_id = ?{index}"));
        values.push(task_id.to_string());
    }
    if let Some(attempt_id) = filter.attempt_id {
        let index = values.len() + 1;
        sql.push_str(&format!(" AND attempt_id = ?{index}"));
        values.push(attempt_id.to_string());
    }
    if let Some(kind) = filter.kind {
        let index = values.len() + 1;
        sql.push_str(&format!(" AND kind = ?{index}"));
        values.push(artifact_kind_to_str(kind).to_string());
    }
    if let Some(after) = after {
        let created_index = values.len() + 1;
        let created_tie_index = values.len() + 2;
        let id_index = values.len() + 3;
        sql.push_str(&format!(
            " AND (created_at < ?{created_index} OR (created_at = ?{created_tie_index} AND id < ?{id_index}))"
        ));
        let created_at = timestamp_to_string(after.created_at);
        values.push(created_at.clone());
        values.push(created_at);
        values.push(after.artifact_id.to_string());
    }
    (sql, values)
}

