fn load_recursive_scheduler_run_live_metadata_tx(
    conn: &Connection,
    run_id: RecursiveSchedulerRunId,
) -> Result<Option<RecursiveSchedulerRunLiveMetadata>> {
    conn.query_row(
        "SELECT id, idempotency_key, request_fingerprint, policy_snapshot_json
         FROM recursive_scheduler_runs
         WHERE id = ?1",
        params![run_id.to_string()],
        |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, Option<String>>(1)?,
                row.get::<_, Option<String>>(2)?,
                row.get::<_, String>(3)?,
            ))
        },
    )
    .optional()?
    .map(
        |(raw_run_id, idempotency_key, request_fingerprint, policy_snapshot_json)| {
            Ok(RecursiveSchedulerRunLiveMetadata {
                run_id: RecursiveSchedulerRunId(parse_uuid(
                    "recursive scheduler run metadata id",
                    &raw_run_id,
                )?),
                idempotency_key,
                request_fingerprint,
                policy_snapshot: serde_json::from_str(&policy_snapshot_json).map_err(|error| {
                    DaemonError::Store(format!(
                        "invalid recursive scheduler run policy_snapshot_json: {error}"
                    ))
                })?,
            })
        },
    )
    .transpose()
}

