fn load_recursive_live_attempts_filtered_tx(
    conn: &Connection,
    filter: RecursiveLiveAttemptListFilter,
) -> Result<Vec<RecursiveLiveAttemptDetail>> {
    let mut attempts = if let Some(graph_id) = filter.graph_id {
        if let Some(task_id) = filter.task_id {
            load_recursive_live_attempts_for_task_tx(conn, graph_id, task_id)?
        } else {
            load_recursive_live_attempts_for_graph_tx(conn, graph_id)?
        }
    } else if let Some(run_id) = filter.scheduler_run_id {
        load_recursive_live_attempts_for_scheduler_run_tx(conn, run_id)?
    } else if let Some(session_id) = filter.session_id {
        load_recursive_live_attempt_by_session_id_tx(conn, session_id)?
            .into_iter()
            .collect()
    } else {
        Vec::new()
    };
    attempts.retain(|attempt| {
        filter
            .status
            .is_none_or(|status| attempt.summary.status == status)
            && filter
                .recovery_status
                .is_none_or(|status| attempt.summary.recovery_status == status)
            && (filter.include_terminal || !attempt.summary.status.is_terminal())
    });
    if let Some(limit) = filter.limit {
        attempts.truncate(limit as usize);
    }
    Ok(attempts)
}

