fn recover_recursive_live_attempt_tx(
    tx: &Transaction<'_>,
    live: &RecursiveLiveAttemptDetail,
    recovered_at: DateTime<Utc>,
    recovered_at_str: &str,
) -> Result<RecursiveLiveAttemptRecoveryResult> {
    let before_status = live.summary.status;
    if before_status.is_terminal() {
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::Unchanged,
            before_status,
            None,
            None,
        ));
    }

    let session_status = match live.summary.session_id {
        Some(session_id) => load_session_status_tx(tx, session_id)?,
        None => None,
    };

    let attempt = load_recursive_attempt_by_id(tx, live.summary.graph_id, live.summary.attempt_id)?;
    let Some(attempt) = attempt else {
        let reason = format!(
            "recursive live attempt {} references missing recursive attempt {}",
            live.summary.id, live.summary.attempt_id
        );
        let after = update_live_attempt_for_recovery_tx(
            tx,
            live,
            RecursiveLiveAttemptStatus::Failed,
            RecursiveLiveRecoveryStatus::Quarantined,
            &reason,
            recovered_at_str,
        )?;
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::MalformedInconsistent,
            after.summary.status,
            session_status,
            Some(reason),
        ));
    };

    if attempt.task_id != live.summary.task_id
        || attempt.phase != live.summary.phase
        || attempt.attempt_no != live.summary.attempt_no
    {
        let reason = format!(
            "recursive live attempt {} does not match recursive attempt {}",
            live.summary.id, live.summary.attempt_id
        );
        let after = update_live_attempt_for_recovery_tx(
            tx,
            live,
            RecursiveLiveAttemptStatus::Failed,
            RecursiveLiveRecoveryStatus::Quarantined,
            &reason,
            recovered_at_str,
        )?;
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::MalformedInconsistent,
            after.summary.status,
            session_status,
            Some(reason),
        ));
    }

    if attempt.status != RecursiveAttemptStatus::Running {
        let reason = format!(
            "recursive live attempt {} references non-running recursive attempt {} with status {}",
            live.summary.id,
            attempt.id,
            attempt_status_to_str(attempt.status)
        );
        let after = update_live_attempt_for_recovery_tx(
            tx,
            live,
            RecursiveLiveAttemptStatus::Failed,
            RecursiveLiveRecoveryStatus::Quarantined,
            &reason,
            recovered_at_str,
        )?;
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::MalformedInconsistent,
            after.summary.status,
            session_status,
            Some(reason),
        ));
    }

    if live.summary.status == RecursiveLiveAttemptStatus::RecoveryPending
        && session_status == Some(SessionStatus::Completed)
    {
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::Unchanged,
            before_status,
            session_status,
            Some("completed live session is already pending output validation".to_string()),
        ));
    }

    match (live.summary.session_id, session_status) {
        (Some(_), Some(SessionStatus::Completed)) => {
            let reason = format!(
                "recursive live recovery observed completed session {} pending output validation",
                live.summary.session_id.expect("checked session id")
            );
            let after = update_live_attempt_for_recovery_tx(
                tx,
                live,
                RecursiveLiveAttemptStatus::RecoveryPending,
                RecursiveLiveRecoveryStatus::Pending,
                &reason,
                recovered_at_str,
            )?;
            finish_active_live_interrupt_for_recovery_tx(
                tx,
                live.summary.id,
                RecursiveLiveInterruptStatus::Ignored,
                &reason,
                recovered_at_str,
            )?;
            return Ok(live_recovery_result(
                live,
                RecursiveLiveAttemptRecoveryStatus::TerminalSessionObserved,
                after.summary.status,
                session_status,
                Some(reason),
            ));
        }
        (Some(_), Some(SessionStatus::Failed)) => {
            let reason = format!(
                "recursive live recovery observed failed session {}",
                live.summary.session_id.expect("checked session id")
            );
            finish_recursive_attempt_for_live_recovery_tx(
                tx,
                live,
                &attempt,
                RecursiveAttemptStatus::Failed,
                &reason,
                recovered_at_str,
            )?;
            let after = update_live_attempt_for_recovery_tx(
                tx,
                live,
                RecursiveLiveAttemptStatus::Failed,
                RecursiveLiveRecoveryStatus::Recovered,
                &reason,
                recovered_at_str,
            )?;
            finish_active_live_interrupt_for_recovery_tx(
                tx,
                live.summary.id,
                RecursiveLiveInterruptStatus::Failed,
                &reason,
                recovered_at_str,
            )?;
            validate_live_recovery_graph_tx(tx, live.summary.graph_id)?;
            return Ok(live_recovery_result(
                live,
                RecursiveLiveAttemptRecoveryStatus::Failed,
                after.summary.status,
                session_status,
                Some(reason),
            ));
        }
        (Some(_), Some(SessionStatus::Interrupted)) => {
            let reason = format!(
                "recursive live recovery observed interrupted session {}",
                live.summary.session_id.expect("checked session id")
            );
            finish_recursive_attempt_for_live_recovery_tx(
                tx,
                live,
                &attempt,
                RecursiveAttemptStatus::Interrupted,
                &reason,
                recovered_at_str,
            )?;
            let after = update_live_attempt_for_recovery_tx(
                tx,
                live,
                RecursiveLiveAttemptStatus::Interrupted,
                RecursiveLiveRecoveryStatus::Recovered,
                &reason,
                recovered_at_str,
            )?;
            finish_active_live_interrupt_for_recovery_tx(
                tx,
                live.summary.id,
                RecursiveLiveInterruptStatus::Interrupted,
                &reason,
                recovered_at_str,
            )?;
            validate_live_recovery_graph_tx(tx, live.summary.graph_id)?;
            return Ok(live_recovery_result(
                live,
                RecursiveLiveAttemptRecoveryStatus::Interrupted,
                after.summary.status,
                session_status,
                Some(reason),
            ));
        }
        (Some(session_id), Some(SessionStatus::Archived | SessionStatus::Deleted)) => {
            let reason = format!(
                "recursive live recovery cannot prove outcome from archived/deleted session {session_id}"
            );
            return mark_live_attempt_lost_for_recovery_tx(
                tx,
                live,
                &attempt,
                session_status,
                &reason,
                recovered_at_str,
            );
        }
        (Some(session_id), None) => {
            let reason =
                format!("recursive live recovery could not find attached session {session_id}");
            return mark_live_attempt_lost_for_recovery_tx(
                tx,
                live,
                &attempt,
                session_status,
                &reason,
                recovered_at_str,
            );
        }
        (None, _) => {
            let reason = format!(
                "recursive live recovery found no attached session for live attempt {} in status {}",
                live.summary.id,
                live_attempt_status_to_str(live.summary.status)
            );
            return mark_live_attempt_lost_for_recovery_tx(
                tx,
                live,
                &attempt,
                session_status,
                &reason,
                recovered_at_str,
            );
        }
        (
            Some(_),
            Some(SessionStatus::Starting | SessionStatus::Running | SessionStatus::WaitingApproval),
        ) => {}
        (Some(session_id), Some(other)) => {
            let reason = format!(
                "recursive live recovery does not support linked session {session_id} status {:?}",
                other
            );
            return mark_live_attempt_lost_for_recovery_tx(
                tx,
                live,
                &attempt,
                session_status,
                &reason,
                recovered_at_str,
            );
        }
    }

    if load_active_recursive_live_interrupt_for_attempt_tx(tx, live.summary.id)?.is_some() {
        let reason = format!(
            "recursive live recovery observed pending interrupt for live attempt {}",
            live.summary.id
        );
        finish_recursive_attempt_for_live_recovery_tx(
            tx,
            live,
            &attempt,
            RecursiveAttemptStatus::Interrupted,
            &reason,
            recovered_at_str,
        )?;
        let after = update_live_attempt_for_recovery_tx(
            tx,
            live,
            RecursiveLiveAttemptStatus::Interrupted,
            RecursiveLiveRecoveryStatus::Recovered,
            &reason,
            recovered_at_str,
        )?;
        finish_active_live_interrupt_for_recovery_tx(
            tx,
            live.summary.id,
            RecursiveLiveInterruptStatus::Interrupted,
            &reason,
            recovered_at_str,
        )?;
        validate_live_recovery_graph_tx(tx, live.summary.graph_id)?;
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::Interrupted,
            after.summary.status,
            session_status,
            Some(reason),
        ));
    }

    let heartbeat_state = live.heartbeat_state_at(recovered_at);
    if matches!(
        heartbeat_state.heartbeat_status,
        RecursiveLiveAttemptHeartbeatStatus::Missing | RecursiveLiveAttemptHeartbeatStatus::Stale
    ) {
        let reason = format!(
            "recursive live recovery observed {} heartbeat for live attempt {}",
            live_heartbeat_status_label(heartbeat_state.heartbeat_status),
            live.summary.id
        );
        return mark_live_attempt_lost_for_recovery_tx(
            tx,
            live,
            &attempt,
            session_status,
            &reason,
            recovered_at_str,
        );
    }

    let target_status = match session_status {
        Some(SessionStatus::WaitingApproval) => RecursiveLiveAttemptStatus::WaitingApproval,
        Some(SessionStatus::Starting | SessionStatus::Running) => {
            RecursiveLiveAttemptStatus::Running
        }
        _ => live.summary.status,
    };
    if target_status != live.summary.status {
        let reason = format!(
            "recursive live recovery aligned live attempt {} to linked session status {:?}",
            live.summary.id, session_status
        );
        let after = update_live_attempt_for_recovery_tx(
            tx,
            live,
            target_status,
            RecursiveLiveRecoveryStatus::Recovered,
            &reason,
            recovered_at_str,
        )?;
        return Ok(live_recovery_result(
            live,
            RecursiveLiveAttemptRecoveryStatus::Recovered,
            after.summary.status,
            session_status,
            Some(reason),
        ));
    }

    Ok(live_recovery_result(
        live,
        RecursiveLiveAttemptRecoveryStatus::Skipped,
        live.summary.status,
        session_status,
        Some("recursive live attempt has fresh heartbeat and nonterminal session".to_string()),
    ))
}

