fn load_recursive_live_interrupts_filtered_tx(
    conn: &Connection,
    filter: RecursiveLiveInterruptListFilter,
) -> Result<Vec<RecursiveLiveInterruptSummary>> {
    let mut sql = String::from(
        "SELECT id, live_attempt_id, graph_id, task_id, scheduler_run_id,
                attempt_id, session_id, cancellation_request_id, status, reason,
                failure_reason, requested_at, sent_at, completed_at
         FROM recursive_live_interrupts
         WHERE ",
    );
    let mut values = Vec::new();
    if let Some(live_attempt_id) = filter.live_attempt_id {
        sql.push_str("live_attempt_id = ?1");
        values.push(live_attempt_id.to_string());
    } else if let Some(cancellation_request_id) = filter.cancellation_request_id {
        sql.push_str("cancellation_request_id = ?1");
        values.push(cancellation_request_id.to_string());
    } else if let Some(session_id) = filter.session_id {
        sql.push_str("session_id = ?1");
        values.push(session_id.to_string());
    } else {
        return Ok(Vec::new());
    }
    if let Some(status) = filter.status {
        let index = values.len() + 1;
        sql.push_str(&format!(" AND status = ?{index}"));
        values.push(live_interrupt_status_to_str(status).to_string());
    }
    sql.push_str(" ORDER BY requested_at DESC, id ASC");

    let mut stmt = conn.prepare(&sql)?;
    let params = rusqlite::params_from_iter(values.iter().map(String::as_str));
    let rows = stmt
        .query_map(params, map_live_interrupt_row)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let mut interrupts = rows
        .into_iter()
        .map(LiveInterruptRow::into_model)
        .collect::<Result<Vec<_>>>()?;
    if let Some(limit) = filter.limit {
        interrupts.truncate(limit as usize);
    }
    Ok(interrupts)
}

