fn load_recursive_cancellation_requests_tx(
    conn: &Connection,
    filter: &RecursiveCancellationRequestFilter,
) -> Result<Vec<RecursiveCancellationRequestSummary>> {
    let graph_id = filter.graph_id.map(|id| id.to_string());
    let run_id = filter.run_id.map(|id| id.to_string());
    let status = filter.status.map(cancellation_status_to_str);
    let limit = filter.limit.map(i64::from).unwrap_or(i64::MAX);
    let mut stmt = conn.prepare(
        "SELECT id, graph_id, run_id, task_id, scope, status, source, reason,
                requested_by, requested_at, observed_at, applied_at, rejection_reason,
                idempotency_key, request_fingerprint, source_context_json
         FROM recursive_cancellation_requests
         WHERE (?1 IS NULL OR graph_id = ?1)
           AND (?2 IS NULL OR run_id = ?2)
           AND (?3 IS NULL OR status = ?3)
         ORDER BY requested_at DESC, id ASC
         LIMIT ?4",
    )?;
    let rows = stmt
        .query_map(
            params![graph_id, run_id, status, limit],
            map_cancellation_request_row,
        )?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    rows.into_iter()
        .map(CancellationRequestRow::into_model)
        .collect()
}

