fn request_recursive_graph_cancellation_tx(
    tx: &Transaction<'_>,
    graph_id: RecursiveTaskGraphId,
    create: RecursiveCancellationRequestCreate,
    idempotency: Option<&RecursiveCancellationIdempotency>,
) -> Result<RecursiveCancellationRequestSummary> {
    validate_cancellation_request_create(&create)?;
    let graph = load_recursive_graph_summary(tx, graph_id)?
        .ok_or_else(|| DaemonError::Store(format!("recursive DAG graph not found: {graph_id}")))?;
    let request_id = RecursiveCancellationRequestId::new();
    let requested_at = timestamp_now();
    let (status, applied_at, rejection_reason) = match graph.status {
        RecursiveGraphStatus::Active => (RecursiveCancellationRequestStatus::Requested, None, None),
        RecursiveGraphStatus::Cancelled => (
            RecursiveCancellationRequestStatus::Applied,
            Some(requested_at.clone()),
            None,
        ),
        other => (
            RecursiveCancellationRequestStatus::Rejected,
            None,
            Some(format!(
                "recursive DAG graph {graph_id} is already terminal: {other:?}"
            )),
        ),
    };
    insert_recursive_cancellation_request_tx(
        tx,
        request_id,
        RecursiveCancellationScope::Graph,
        graph_id,
        None,
        None,
        create,
        idempotency,
        status,
        None,
        applied_at.as_deref(),
        rejection_reason.as_deref(),
        &requested_at,
    )?;
    load_recursive_cancellation_request_tx(tx, request_id)?.ok_or_else(|| {
        DaemonError::Store(format!(
            "recursive cancellation request missing after insert: {request_id}"
        ))
    })
}

fn request_recursive_scheduler_run_cancellation_tx(
    tx: &Transaction<'_>,
    run_id: RecursiveSchedulerRunId,
    create: RecursiveCancellationRequestCreate,
    idempotency: Option<&RecursiveCancellationIdempotency>,
) -> Result<RecursiveCancellationRequestSummary> {
    validate_cancellation_request_create(&create)?;
    let run = load_recursive_scheduler_run_tx(tx, run_id)?.ok_or_else(|| {
        DaemonError::Store(format!("recursive scheduler run not found: {run_id}"))
    })?;
    let request_id = RecursiveCancellationRequestId::new();
    let requested_at = timestamp_now();
    let is_active = matches!(
        run.status,
        RecursiveSchedulerRunStatus::Running | RecursiveSchedulerRunStatus::Cancelling
    );
    let status = if is_active {
        RecursiveCancellationRequestStatus::Requested
    } else {
        RecursiveCancellationRequestStatus::Rejected
    };
    let rejection_reason = (!is_active).then(|| {
        format!(
            "recursive scheduler run {run_id} is already terminal: {:?}",
            run.status
        )
    });
    insert_recursive_cancellation_request_tx(
        tx,
        request_id,
        RecursiveCancellationScope::Run,
        run.graph_id,
        Some(run_id),
        None,
        create,
        idempotency,
        status,
        None,
        None,
        rejection_reason.as_deref(),
        &requested_at,
    )?;
    if is_active {
        tx.execute(
            "UPDATE recursive_scheduler_runs
             SET status = 'cancelling', cancellation_request_id = ?1,
                 cancellation_reason = (
                     SELECT reason FROM recursive_cancellation_requests WHERE id = ?1
                 )
             WHERE id = ?2 AND status = 'running'",
            params![request_id.to_string(), run_id.to_string()],
        )?;
        insert_scheduler_run_event_tx(
            tx,
            run_id,
            run.graph_id,
            "cancellation_requested",
            Some("recursive DAG scheduler run cancellation requested"),
            serde_json::json!({
                "cancellation_request_id": request_id.to_string(),
                "scope": "run",
            }),
            &requested_at,
        )?;
    }
    load_recursive_cancellation_request_tx(tx, request_id)?.ok_or_else(|| {
        DaemonError::Store(format!(
            "recursive cancellation request missing after insert: {request_id}"
        ))
    })
}

