struct SessionLiveSnapshot {
    provider: SessionProvider,
    model: Option<String>,
    sandbox_kind: Option<SandboxKind>,
    sandbox_root: Option<PathBuf>,
    sandbox_branch: Option<String>,
}

fn load_session_live_snapshot_tx(
    conn: &Connection,
    session_id: Uuid,
) -> Result<Option<SessionLiveSnapshot>> {
    conn.query_row(
        "SELECT provider, model, sandbox_kind, sandbox_root, sandbox_branch
         FROM sessions
         WHERE id = ?1",
        params![session_id.to_string()],
        |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, Option<String>>(1)?,
                row.get::<_, Option<String>>(2)?,
                row.get::<_, Option<String>>(3)?,
                row.get::<_, Option<String>>(4)?,
            ))
        },
    )
    .optional()?
    .map(
        |(provider, model, sandbox_kind, sandbox_root, sandbox_branch)| {
            Ok(SessionLiveSnapshot {
                provider: str_to_session_provider(&provider)?,
                model,
                sandbox_kind: sandbox_kind
                    .as_deref()
                    .map(str_to_sandbox_kind)
                    .transpose()?,
                sandbox_root: sandbox_root.map(PathBuf::from),
                sandbox_branch,
            })
        },
    )
    .transpose()
}

fn load_session_status_tx(conn: &Connection, session_id: Uuid) -> Result<Option<SessionStatus>> {
    conn.query_row(
        "SELECT status FROM sessions WHERE id = ?1",
        params![session_id.to_string()],
        |row| row.get::<_, String>(0),
    )
    .optional()?
    .map(|status| str_to_session_status(&status))
    .transpose()
}

fn load_recursive_live_linked_session_summary_tx(
    conn: &Connection,
    session_id: Uuid,
) -> Result<Option<RecursiveLiveLinkedSessionSummary>> {
    conn.query_row(
        "SELECT id, status, session_kind, provider, model, working_dir, title,
                created_at, updated_at
         FROM sessions
         WHERE id = ?1",
        params![session_id.to_string()],
        |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
                row.get::<_, Option<String>>(4)?,
                row.get::<_, String>(5)?,
                row.get::<_, Option<String>>(6)?,
                row.get::<_, String>(7)?,
                row.get::<_, String>(8)?,
            ))
        },
    )
    .optional()?
    .map(
        |(
            id,
            status,
            session_kind,
            provider,
            model,
            working_dir,
            title,
            created_at,
            updated_at,
        )| {
            Ok(RecursiveLiveLinkedSessionSummary {
                session_id: parse_uuid("linked session id", &id)?,
                status: str_to_session_status(&status)?,
                session_kind: str_to_session_kind(&session_kind)?,
                provider: str_to_session_provider(&provider)?,
                model,
                working_dir: PathBuf::from(working_dir),
                title,
                created_at: parse_model_timestamp("linked session created_at", &created_at)?,
                updated_at: parse_model_timestamp("linked session updated_at", &updated_at)?,
            })
        },
    )
    .transpose()
}

