impl LiveOutputValidationRow {
    fn summary(&self) -> Result<RecursiveLiveOutputValidationSummary> {
        Ok(RecursiveLiveOutputValidationSummary {
            validation_id: Some(RecursiveLiveOutputValidationId(parse_uuid(
                "recursive live output validation id",
                &self.id,
            )?)),
            live_attempt_id: RecursiveLiveAttemptId(parse_uuid(
                "recursive live output validation live_attempt_id",
                &self.live_attempt_id,
            )?),
            graph_id: RecursiveTaskGraphId(parse_uuid(
                "recursive live output validation graph_id",
                &self.graph_id,
            )?),
            task_id: RecursiveTaskId(parse_uuid(
                "recursive live output validation task_id",
                &self.task_id,
            )?),
            scheduler_run_id: RecursiveSchedulerRunId(parse_uuid(
                "recursive live output validation scheduler_run_id",
                &self.scheduler_run_id,
            )?),
            attempt_id: RecursiveAttemptId(parse_uuid(
                "recursive live output validation attempt_id",
                &self.attempt_id,
            )?),
            session_id: parse_optional_uuid(
                "recursive live output validation session_id",
                self.session_id.clone(),
            )?,
            status: parse_live_output_validation_status(&self.status)?,
            output_kind: self
                .output_kind
                .as_deref()
                .map(parse_live_output_kind)
                .transpose()?,
            mapping_decision: self
                .mapping_decision
                .as_deref()
                .map(parse_live_output_mapping_decision)
                .transpose()?,
            retry_decision: self
                .retry_decision_json
                .as_deref()
                .map(parse_json_str::<rsi_common::RecursiveLiveOutputRetryDecision>)
                .transpose()?,
            raw_output_artifact_id: self.raw_output_artifact_id,
            normalized_output_artifact_id: self.normalized_output_artifact_id,
            validation_artifact_id: self.validation_artifact_id,
            normalized_digest: self.normalized_digest.clone(),
            issue_count: i64_to_u32(
                "recursive live output validation issue_count",
                self.issue_count,
            )?,
            error_count: i64_to_u32(
                "recursive live output validation error_count",
                self.error_count,
            )?,
            warning_count: i64_to_u32(
                "recursive live output validation warning_count",
                self.warning_count,
            )?,
            info_count: i64_to_u32(
                "recursive live output validation info_count",
                self.info_count,
            )?,
            created_at: Some(parse_model_timestamp(
                "recursive live output validation created_at",
                &self.created_at,
            )?),
        })
    }

    fn artifact_links(&self) -> Result<RecursiveLiveOutputValidationArtifactLinks> {
        Ok(RecursiveLiveOutputValidationArtifactLinks {
            raw_output_artifact_id: self.raw_output_artifact_id,
            normalized_output_artifact_id: self.normalized_output_artifact_id,
            validation_artifact_id: self.validation_artifact_id,
            produced_artifact_ids: parse_i64_json_array(
                "recursive live output validation produced_artifact_ids_json",
                &self.produced_artifact_ids_json,
            )?,
            test_artifact_ids: parse_i64_json_array(
                "recursive live output validation test_artifact_ids_json",
                &self.test_artifact_ids_json,
            )?,
            diff_artifact_ids: parse_i64_json_array(
                "recursive live output validation diff_artifact_ids_json",
                &self.diff_artifact_ids_json,
            )?,
        })
    }

    fn issues(&self) -> Result<Vec<RecursiveLiveOutputValidationIssue>> {
        serde_json::from_str(&self.issue_summary_json).map_err(|e| {
            DaemonError::Store(format!(
                "invalid recursive live output validation issue_summary_json: {e}"
            ))
        })
    }

    fn into_result(
        self,
        conn: &Connection,
        options: RecursiveLiveOutputValidationReadOptions,
    ) -> Result<RecursiveLiveOutputValidationResult> {
        let summary = self.summary()?;
        let artifact_links = self.artifact_links()?;
        let normalized_output = if options.include_normalized_output {
            artifact_links
                .normalized_output_artifact_id
                .map(|artifact_id| {
                    load_recursive_artifact_by_id_tx(conn, summary.graph_id, artifact_id)?
                        .and_then(|artifact| artifact.content)
                        .map(|content| parse_json_str(&content))
                        .transpose()
                })
                .transpose()?
                .flatten()
        } else {
            None
        };
        Ok(RecursiveLiveOutputValidationResult {
            summary,
            artifact_links,
            parser_source: self
                .parser_source_json
                .as_deref()
                .map(parse_json_str::<RecursiveLiveOutputParserSource>)
                .transpose()?,
            issues: if options.include_issues {
                self.issues()?
            } else {
                Vec::new()
            },
            normalized_output,
            validation_report: if options.include_validation_report {
                self.validation_report_json
                    .as_deref()
                    .map(parse_json_str::<serde_json::Value>)
                    .transpose()?
            } else {
                None
            },
            metadata: parse_json_str(&self.metadata_json)?,
        })
    }
}

fn load_recursive_live_output_validation_result_tx(
    conn: &Connection,
    validation_id: RecursiveLiveOutputValidationId,
    options: RecursiveLiveOutputValidationReadOptions,
) -> Result<Option<RecursiveLiveOutputValidationResult>> {
    let sql = format!(
        "SELECT {LIVE_OUTPUT_VALIDATION_COLUMNS}
         FROM recursive_live_output_validations
         WHERE id = ?1"
    );
    conn.query_row(
        &sql,
        params![validation_id.to_string()],
        map_live_output_validation_row,
    )
    .optional()?
    .map(|row| row.into_result(conn, options))
    .transpose()
}

fn load_latest_recursive_live_output_validation_result_for_live_attempt_tx(
    conn: &Connection,
    live_attempt_id: RecursiveLiveAttemptId,
    options: RecursiveLiveOutputValidationReadOptions,
) -> Result<Option<RecursiveLiveOutputValidationResult>> {
    let sql = format!(
        "SELECT {LIVE_OUTPUT_VALIDATION_COLUMNS}
         FROM recursive_live_output_validations
         WHERE live_attempt_id = ?1
         ORDER BY created_at DESC, id ASC
         LIMIT 1"
    );
    conn.query_row(
        &sql,
        params![live_attempt_id.to_string()],
        map_live_output_validation_row,
    )
    .optional()?
    .map(|row| row.into_result(conn, options))
    .transpose()
}

fn query_live_output_validation_rows(
    conn: &Connection,
    where_clause: &str,
    values: Vec<String>,
) -> Result<Vec<LiveOutputValidationRow>> {
    let sql = format!(
        "SELECT {LIVE_OUTPUT_VALIDATION_COLUMNS}
         FROM recursive_live_output_validations
         WHERE {where_clause}
         ORDER BY created_at DESC, id ASC"
    );
    let mut stmt = conn.prepare(&sql)?;
    let params = rusqlite::params_from_iter(values.iter().map(String::as_str));
    stmt.query_map(params, map_live_output_validation_row)?
        .collect::<std::result::Result<Vec<_>, _>>()
        .map_err(DaemonError::Database)
}

fn load_recursive_live_output_validation_results_filtered_tx(
    conn: &Connection,
    filter: RecursiveLiveOutputValidationListFilter,
) -> Result<Vec<RecursiveLiveOutputValidationResult>> {
    let (mut where_clause, mut values) = if let Some(live_attempt_id) = filter.live_attempt_id {
        (
            "live_attempt_id = ?1".to_string(),
            vec![live_attempt_id.to_string()],
        )
    } else if let Some(attempt_id) = filter.attempt_id {
        ("attempt_id = ?1".to_string(), vec![attempt_id.to_string()])
    } else if let Some(session_id) = filter.session_id {
        ("session_id = ?1".to_string(), vec![session_id.to_string()])
    } else if let Some(scheduler_run_id) = filter.scheduler_run_id {
        (
            "scheduler_run_id = ?1".to_string(),
            vec![scheduler_run_id.to_string()],
        )
    } else if let Some(graph_id) = filter.graph_id {
        if let Some(task_id) = filter.task_id {
            (
                "graph_id = ?1 AND task_id = ?2".to_string(),
                vec![graph_id.to_string(), task_id.to_string()],
            )
        } else {
            ("graph_id = ?1".to_string(), vec![graph_id.to_string()])
        }
    } else {
        return Ok(Vec::new());
    };

    if let Some(status) = filter.status {
        let index = values.len() + 1;
        where_clause.push_str(&format!(" AND status = ?{index}"));
        values.push(live_output_validation_status_to_str(status).to_string());
    }
    if let Some(output_kind) = filter.output_kind {
        let index = values.len() + 1;
        where_clause.push_str(&format!(" AND output_kind = ?{index}"));
        values.push(live_output_kind_to_str(output_kind).to_string());
    }

    let rows = query_live_output_validation_rows(conn, &where_clause, values)?;
    let mut results = Vec::new();
    let options = RecursiveLiveOutputValidationReadOptions {
        include_issues: filter.include_issues,
        include_normalized_output: false,
        include_validation_report: false,
    };
    for row in rows {
        results.push(row.into_result(conn, options)?);
        if filter
            .limit
            .is_some_and(|limit| results.len() >= limit as usize)
        {
            break;
        }
    }
    Ok(results)
}

fn load_recursive_live_validation_issues_filtered_tx(
    conn: &Connection,
    filter: RecursiveLiveValidationIssueFilter,
) -> Result<Vec<RecursiveLiveOutputValidationIssue>> {
    let result = if let Some(validation_id) = filter.validation_id {
        load_recursive_live_output_validation_result_tx(
            conn,
            validation_id,
            RecursiveLiveOutputValidationReadOptions {
                include_issues: true,
                include_normalized_output: false,
                include_validation_report: false,
            },
        )?
    } else if let Some(live_attempt_id) = filter.live_attempt_id {
        load_latest_recursive_live_output_validation_result_for_live_attempt_tx(
            conn,
            live_attempt_id,
            RecursiveLiveOutputValidationReadOptions {
                include_issues: true,
                include_normalized_output: false,
                include_validation_report: false,
            },
        )?
    } else {
        None
    };
    let mut issues = result.map(|result| result.issues).unwrap_or_default();
    issues.retain(|issue| {
        filter
            .severity
            .is_none_or(|severity| issue.severity == severity)
            && filter.class.is_none_or(|class| issue.class == class)
            && filter.code.is_none_or(|code| issue.code == code)
    });
    if let Some(limit) = filter.limit {
        issues.truncate(limit as usize);
    }
    Ok(issues)
}

fn load_recursive_artifact_by_id_tx(
    conn: &Connection,
    graph_id: RecursiveTaskGraphId,
    artifact_id: i64,
) -> Result<Option<RecursiveExecutionArtifact>> {
    conn.query_row(
        "SELECT id, graph_id, task_id, attempt_id, kind, label, content, uri,
                metadata_json, created_at
         FROM recursive_execution_artifacts
         WHERE graph_id = ?1 AND id = ?2",
        params![graph_id.to_string(), artifact_id],
        map_artifact_row,
    )
    .optional()?
    .map(ArtifactRow::into_model)
    .transpose()
}

fn load_recursive_live_attempt_artifacts_tx(
    conn: &Connection,
    live_attempt_id: RecursiveLiveAttemptId,
    options: RecursiveLiveAttemptArtifactReadOptions,
) -> Result<Option<RecursiveLiveAttemptArtifactReadback>> {
    let Some(live) = load_recursive_live_attempt_tx(conn, live_attempt_id)? else {
        return Ok(None);
    };
    let validations = load_recursive_live_output_validation_results_filtered_tx(
        conn,
        RecursiveLiveOutputValidationListFilter {
            live_attempt_id: Some(live_attempt_id),
            include_issues: false,
            ..RecursiveLiveOutputValidationListFilter::default()
        },
    )?;
    let mut raw_ids = BTreeSet::new();
    let mut normalized_ids = BTreeSet::new();
    let mut preferred_normalized_id = live.output_artifact_id;
    let mut validation_ids = BTreeSet::new();
    let mut produced_ids = BTreeSet::new();
    let mut test_ids = BTreeSet::new();
    let mut diff_ids = BTreeSet::new();

    if let Some(id) = live.output_artifact_id {
        normalized_ids.insert(id);
    }
    if let Some(id) = live.test_artifact_id {
        test_ids.insert(id);
    }
    if let Some(id) = live.diff_artifact_id {
        diff_ids.insert(id);
    }
    for validation in validations {
        if let Some(id) = validation.artifact_links.raw_output_artifact_id {
            raw_ids.insert(id);
        }
        if let Some(id) = validation.artifact_links.normalized_output_artifact_id {
            preferred_normalized_id.get_or_insert(id);
            normalized_ids.insert(id);
        }
        if let Some(id) = validation.artifact_links.validation_artifact_id {
            validation_ids.insert(id);
        }
        produced_ids.extend(validation.artifact_links.produced_artifact_ids);
        test_ids.extend(validation.artifact_links.test_artifact_ids);
        diff_ids.extend(validation.artifact_links.diff_artifact_ids);
    }

    let mut artifacts_by_id = BTreeMap::new();
    for artifact in load_recursive_artifacts(conn, live.summary.graph_id)? {
        artifacts_by_id.insert(artifact.id, artifact);
    }
    let collect = |ids: BTreeSet<i64>| -> Vec<RecursiveExecutionArtifact> {
        ids.into_iter()
            .filter_map(|id| artifacts_by_id.get(&id).cloned())
            .collect()
    };

    Ok(Some(RecursiveLiveAttemptArtifactReadback {
        prompt_artifact: if options.include_prompt {
            live.prompt_artifact_id
                .and_then(|id| artifacts_by_id.get(&id).cloned())
        } else {
            None
        },
        raw_output_artifacts: if options.include_raw_output {
            collect(raw_ids)
        } else {
            Vec::new()
        },
        normalized_output_artifact: if options.include_normalized_output {
            preferred_normalized_id
                .and_then(|id| artifacts_by_id.get(&id).cloned())
                .or_else(|| {
                    normalized_ids
                        .into_iter()
                        .find_map(|id| artifacts_by_id.get(&id).cloned())
                })
        } else {
            None
        },
        validation_artifacts: if options.include_validation_report {
            collect(validation_ids)
        } else {
            Vec::new()
        },
        diff_artifacts: if options.include_diff {
            collect(diff_ids)
        } else {
            Vec::new()
        },
        test_artifacts: if options.include_tests {
            collect(test_ids)
        } else {
            Vec::new()
        },
        produced_artifacts: if options.include_produced_artifacts {
            collect(produced_ids)
        } else {
            Vec::new()
        },
    }))
}

fn live_recovery_result(
    live: &RecursiveLiveAttemptDetail,
    status: RecursiveLiveAttemptRecoveryStatus,
    after_status: RecursiveLiveAttemptStatus,
    session_status: Option<SessionStatus>,
    reason: Option<String>,
) -> RecursiveLiveAttemptRecoveryResult {
    RecursiveLiveAttemptRecoveryResult {
        live_attempt_id: live.summary.id,
        status,
        before_status: live.summary.status,
        after_status,
        session_id: live.summary.session_id,
        session_status,
        reason,
    }
}

fn mark_live_attempt_lost_for_recovery_tx(
    tx: &Transaction<'_>,
    live: &RecursiveLiveAttemptDetail,
    attempt: &RecursiveTaskAttempt,
    session_status: Option<SessionStatus>,
    reason: &str,
    recovered_at: &str,
) -> Result<RecursiveLiveAttemptRecoveryResult> {
    let attempt_status = if live_recovery_retry_remains(tx, live, attempt)? {
        RecursiveAttemptStatus::Interrupted
    } else {
        RecursiveAttemptStatus::Failed
    };
    finish_recursive_attempt_for_live_recovery_tx(
        tx,
        live,
        attempt,
        attempt_status,
        reason,
        recovered_at,
    )?;
    let after = update_live_attempt_for_recovery_tx(
        tx,
        live,
        RecursiveLiveAttemptStatus::Lost,
        RecursiveLiveRecoveryStatus::Lost,
        reason,
        recovered_at,
    )?;
    finish_active_live_interrupt_for_recovery_tx(
        tx,
        live.summary.id,
        RecursiveLiveInterruptStatus::Failed,
        reason,
        recovered_at,
    )?;
    validate_live_recovery_graph_tx(tx, live.summary.graph_id)?;
    Ok(live_recovery_result(
        live,
        RecursiveLiveAttemptRecoveryStatus::Lost,
        after.summary.status,
        session_status,
        Some(reason.to_string()),
    ))
}

fn update_live_attempt_for_recovery_tx(
    tx: &Transaction<'_>,
    live: &RecursiveLiveAttemptDetail,
    status: RecursiveLiveAttemptStatus,
    recovery_status: RecursiveLiveRecoveryStatus,
    reason: &str,
    recovered_at: &str,
) -> Result<RecursiveLiveAttemptDetail> {
    validate_live_attempt_status_transition(live.summary.status, status)?;
    validate_nonempty("recursive live recovery reason", reason)?;
    let terminal = i64::from(status.is_terminal());
    let failure_reason = matches!(
        status,
        RecursiveLiveAttemptStatus::Failed | RecursiveLiveAttemptStatus::Lost
    )
    .then_some(reason);
    let interruption_reason = (status == RecursiveLiveAttemptStatus::Interrupted).then_some(reason);
    tx.execute(
        "UPDATE recursive_live_attempts
         SET status = ?1,
             completed_at = CASE WHEN ?2 != 0 THEN COALESCE(completed_at, ?3) ELSE completed_at END,
             recovery_status = ?4,
             recovery_checked_at = COALESCE(recovery_checked_at, ?3),
             recovered_at = COALESCE(recovered_at, ?3),
             failure_reason = CASE
                 WHEN ?5 IS NULL THEN failure_reason
                 ELSE COALESCE(failure_reason, ?5)
             END,
             interruption_reason = CASE
                 WHEN ?6 IS NULL THEN interruption_reason
                 ELSE COALESCE(interruption_reason, ?6)
             END,
             recovery_reason = COALESCE(recovery_reason, ?7),
             error = CASE
                 WHEN ?8 IS NULL THEN error
                 ELSE COALESCE(error, ?8)
             END,
             lease_owner = CASE WHEN ?2 != 0 THEN NULL ELSE lease_owner END,
             lease_token = CASE WHEN ?2 != 0 THEN NULL ELSE lease_token END,
             heartbeat_at = CASE WHEN ?2 != 0 THEN NULL ELSE heartbeat_at END,
             lease_expires_at = CASE WHEN ?2 != 0 THEN NULL ELSE lease_expires_at END,
             updated_at = ?3
         WHERE id = ?9",
        params![
            live_attempt_status_to_str(status),
            terminal,
            recovered_at,
            live_recovery_status_to_str(recovery_status),
            failure_reason,
            interruption_reason,
            reason,
            status.is_terminal().then_some(reason),
            live.summary.id.to_string(),
        ],
    )?;
    load_recursive_live_attempt_tx(tx, live.summary.id)?.ok_or_else(|| {
        DaemonError::Store(format!(
            "recursive live attempt missing after recovery update: {}",
            live.summary.id
        ))
    })
}

fn finish_recursive_attempt_for_live_recovery_tx(
    tx: &Transaction<'_>,
    live: &RecursiveLiveAttemptDetail,
    attempt: &RecursiveTaskAttempt,
    status: RecursiveAttemptStatus,
    reason: &str,
    recovered_at: &str,
) -> Result<()> {
    let attempt_failure_reason = matches!(
        status,
        RecursiveAttemptStatus::Failed
            | RecursiveAttemptStatus::Cancelled
            | RecursiveAttemptStatus::Interrupted
    )
    .then_some(reason);
    validate_attempt_finish_status(attempt.id, status, attempt_failure_reason, None)?;
    if attempt.status != RecursiveAttemptStatus::Running {
        return recursive_store_error(format!("recursive attempt {} is not running", attempt.id));
    }
    let task = load_recursive_node_by_id(tx, live.summary.graph_id, live.summary.task_id)?
        .ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive task not found: {}",
                live.summary.task_id
            ))
        })?;
    let task_transition = match status {
        RecursiveAttemptStatus::Succeeded => RecursiveTaskLifecycleState::Succeeded,
        RecursiveAttemptStatus::Failed | RecursiveAttemptStatus::Interrupted => {
            if live_recovery_retry_remains_for_task(attempt, &task) {
                live_recovery_retry_state_for_phase(live.summary.phase)
            } else {
                RecursiveTaskLifecycleState::Failed
            }
        }
        RecursiveAttemptStatus::Blocked => RecursiveTaskLifecycleState::Blocked,
        RecursiveAttemptStatus::Cancelled => RecursiveTaskLifecycleState::Cancelled,
        RecursiveAttemptStatus::Decomposed => RecursiveTaskLifecycleState::Decomposed,
        RecursiveAttemptStatus::Running => {
            return recursive_store_error("cannot recover live attempt to running attempt status");
        }
    };
    tx.execute(
        "UPDATE recursive_task_attempts
         SET status = ?1, finished_at = ?2, failure_reason = ?3
         WHERE graph_id = ?4 AND id = ?5 AND status = 'running'",
        params![
            attempt_status_to_str(status),
            recovered_at,
            attempt_failure_reason,
            live.summary.graph_id.to_string(),
            attempt.id.to_string(),
        ],
    )?;
    if tx.changes() == 0 {
        return recursive_store_error(format!(
            "recursive attempt {} was not recovered because it is no longer running",
            attempt.id
        ));
    }
    transition_recursive_task_state_tx(
        tx,
        live.summary.graph_id,
        live.summary.task_id,
        task_transition,
        Some(reason.to_string()),
        recovered_at,
    )?;
    sync_recursive_graph_status_tx(tx, live.summary.graph_id, recovered_at)?;
    tx.execute(
        "UPDATE recursive_task_graphs
         SET recovered_at = COALESCE(recovered_at, ?1),
             recovery_checked_at = COALESCE(recovery_checked_at, ?1),
             last_stop_reason = COALESCE(last_stop_reason, 'recovered_after_restart'),
             updated_at = ?1
         WHERE id = ?2",
        params![recovered_at, live.summary.graph_id.to_string()],
    )?;
    Ok(())
}

fn live_recovery_retry_remains(
    tx: &Transaction<'_>,
    live: &RecursiveLiveAttemptDetail,
    attempt: &RecursiveTaskAttempt,
) -> Result<bool> {
    let task = load_recursive_node_by_id(tx, live.summary.graph_id, live.summary.task_id)?
        .ok_or_else(|| {
            DaemonError::Store(format!(
                "recursive task not found: {}",
                live.summary.task_id
            ))
        })?;
    Ok(live_recovery_retry_remains_for_task(attempt, &task))
}

fn live_recovery_retry_remains_for_task(
    attempt: &RecursiveTaskAttempt,
    task: &RecursiveTaskNode,
) -> bool {
    attempt.retry_count < task.max_retries
}

fn live_recovery_retry_state_for_phase(
    phase: RecursiveAttemptPhase,
) -> RecursiveTaskLifecycleState {
    match phase {
        RecursiveAttemptPhase::Execute => RecursiveTaskLifecycleState::Ready,
        RecursiveAttemptPhase::Integrate => RecursiveTaskLifecycleState::BlockedOnChildren,
    }
}

fn finish_active_live_interrupt_for_recovery_tx(
    tx: &Transaction<'_>,
    live_attempt_id: RecursiveLiveAttemptId,
    status: RecursiveLiveInterruptStatus,
    reason: &str,
    recovered_at: &str,
) -> Result<()> {
    if !status.is_terminal() {
        return recursive_store_error("live interrupt recovery status must be terminal");
    }
    let failure_reason = matches!(
        status,
        RecursiveLiveInterruptStatus::Failed
            | RecursiveLiveInterruptStatus::Rejected
            | RecursiveLiveInterruptStatus::Ignored
    )
    .then_some(reason);
    tx.execute(
        "UPDATE recursive_live_interrupts
         SET status = ?1,
             failure_reason = CASE
                 WHEN ?2 IS NULL THEN failure_reason
                 ELSE COALESCE(failure_reason, ?2)
             END,
             sent_at = CASE
                 WHEN ?1 = 'interrupted' THEN COALESCE(sent_at, ?3)
                 ELSE sent_at
             END,
             completed_at = COALESCE(completed_at, ?3)
         WHERE live_attempt_id = ?4 AND status IN ('requested', 'sent')",
        params![
            live_interrupt_status_to_str(status),
            failure_reason,
            recovered_at,
            live_attempt_id.to_string(),
        ],
    )?;
    Ok(())
}

fn validate_live_recovery_graph_tx(
    tx: &Transaction<'_>,
    graph_id: RecursiveTaskGraphId,
) -> Result<()> {
    let detail = load_recursive_graph_detail(tx, graph_id)?
        .ok_or_else(|| DaemonError::Store(format!("recursive DAG graph not found: {graph_id}")))?;
    validate_detail(&detail).map_err(recursive_validation_error)
}

fn live_heartbeat_status_label(status: RecursiveLiveAttemptHeartbeatStatus) -> &'static str {
    match status {
        RecursiveLiveAttemptHeartbeatStatus::Missing => "missing",
        RecursiveLiveAttemptHeartbeatStatus::Active => "active",
        RecursiveLiveAttemptHeartbeatStatus::Stale => "stale",
        RecursiveLiveAttemptHeartbeatStatus::Released => "released",
    }
}

