fn artifact_role_from_metadata(
    metadata: &serde_json::Value,
    artifact_id: i64,
    warnings: &mut Vec<RecursiveReadbackWarning>,
) -> Option<RecursiveArtifactRole> {
    if metadata.get("artifact").and_then(serde_json::Value::as_str)
        == Some("recursive_dag_scheduler_report")
    {
        return Some(RecursiveArtifactRole::SchedulerReport);
    }

    let role = metadata
        .get("live_output_artifact_role")
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            metadata
                .get("artifact_role")
                .and_then(serde_json::Value::as_str)
        });
    let Some(role) = role else {
        return None;
    };
    match role {
        "raw_output" => Some(RecursiveArtifactRole::RawOutput),
        "normalized_output" => Some(RecursiveArtifactRole::NormalizedOutput),
        "validation_report" => Some(RecursiveArtifactRole::ValidationReport),
        "produced_artifact" => Some(RecursiveArtifactRole::ProducedArtifact),
        "test_summary" => Some(RecursiveArtifactRole::TestSummary),
        "diff_summary" => Some(RecursiveArtifactRole::DiffSummary),
        "scheduler_report" => Some(RecursiveArtifactRole::SchedulerReport),
        "topology_recursive_graph_creation" => {
            Some(RecursiveArtifactRole::TopologyRecursiveGraphCreation)
        }
        other => {
            push_artifact_warning(
                warnings,
                "RECURSIVE_ARTIFACT_ROLE_UNRECOGNIZED",
                format!("artifact role metadata is not recognized: {other}"),
                artifact_id,
            );
            None
        }
    }
}

fn artifact_provenance(role: Option<RecursiveArtifactRole>) -> RecursiveArtifactProvenance {
    match role {
        Some(
            RecursiveArtifactRole::RawOutput
            | RecursiveArtifactRole::NormalizedOutput
            | RecursiveArtifactRole::ValidationReport
            | RecursiveArtifactRole::ProducedArtifact
            | RecursiveArtifactRole::TestSummary
            | RecursiveArtifactRole::DiffSummary,
        ) => RecursiveArtifactProvenance::LiveOutputValidation,
        Some(RecursiveArtifactRole::SchedulerReport) => {
            RecursiveArtifactProvenance::SchedulerReport
        }
        Some(RecursiveArtifactRole::TopologyRecursiveGraphCreation) => {
            RecursiveArtifactProvenance::TopologyCreation
        }
        None => RecursiveArtifactProvenance::Legacy,
    }
}

fn artifact_owners_from_metadata(
    artifact: &RecursiveExecutionArtifact,
    warnings: &mut Vec<RecursiveReadbackWarning>,
) -> RecursiveArtifactOwners {
    let live_output = artifact.metadata.get("live_output");
    let live_attempt_id = metadata_uuid_field(
        live_output,
        "live_attempt_id",
        artifact.id,
        warnings,
        RecursiveLiveAttemptId,
    );
    let scheduler_run_id = metadata_uuid_field(
        live_output,
        "scheduler_run_id",
        artifact.id,
        warnings,
        RecursiveSchedulerRunId,
    )
    .or_else(|| {
        metadata_uuid_field(
            Some(&artifact.metadata),
            "run_id",
            artifact.id,
            warnings,
            RecursiveSchedulerRunId,
        )
    });
    let validation_id = metadata_uuid_field(
        Some(&artifact.metadata),
        "live_output_validation_id",
        artifact.id,
        warnings,
        RecursiveLiveOutputValidationId,
    )
    .or_else(|| {
        metadata_uuid_field(
            live_output,
            "validation_id",
            artifact.id,
            warnings,
            RecursiveLiveOutputValidationId,
        )
    });

    RecursiveArtifactOwners {
        graph_id: artifact.graph_id,
        task_id: artifact.task_id,
        attempt_id: artifact.attempt_id,
        live_attempt_id,
        scheduler_run_id,
        validation_id,
    }
}

fn metadata_uuid_field<T>(
    metadata: Option<&serde_json::Value>,
    key: &str,
    artifact_id: i64,
    warnings: &mut Vec<RecursiveReadbackWarning>,
    wrap: impl Fn(Uuid) -> T,
) -> Option<T> {
    let value = metadata?.get(key)?;
    let Some(raw) = value.as_str() else {
        if !value.is_null() {
            push_artifact_warning(
                warnings,
                "RECURSIVE_METADATA_MALFORMED",
                format!("artifact metadata field {key} is not a string UUID"),
                artifact_id,
            );
        }
        return None;
    };
    match Uuid::parse_str(raw) {
        Ok(uuid) => Some(wrap(uuid)),
        Err(error) => {
            push_artifact_warning(
                warnings,
                "RECURSIVE_METADATA_MALFORMED",
                format!("artifact metadata field {key} is not a valid UUID: {error}"),
                artifact_id,
            );
            None
        }
    }
}

fn preview_recursive_artifact(
    artifact: RecursiveExecutionArtifact,
    mut warnings: Vec<RecursiveReadbackWarning>,
    options: RecursiveExecutionArtifactPreviewOptions,
) -> Result<RecursiveExecutionArtifactPreview> {
    let applied_max_bytes = bounded_recursive_artifact_preview_bytes(options.max_bytes)?;
    let applied_max_lines = bounded_recursive_artifact_preview_lines(options.max_lines)?;
    let availability = artifact_preview_availability(
        artifact.kind,
        artifact.content.is_some(),
        artifact.uri.as_deref(),
    );
    if matches!(availability.state, RecursiveArtifactPreviewState::Available)
        && let Some(content) = artifact.content.as_deref()
    {
        return Ok(preview_recursive_inline_artifact(
            &artifact,
            content,
            warnings,
            options,
            applied_max_bytes,
            applied_max_lines,
        ));
    }

    match availability.state {
        RecursiveArtifactPreviewState::UriBlocked => {
            push_artifact_warning(
                &mut warnings,
                "RECURSIVE_ARTIFACT_URI_PREVIEW_BLOCKED",
                "artifact preview will not read URI or filesystem-backed content",
                artifact.id,
            );
        }
        RecursiveArtifactPreviewState::UnsupportedKind => {
            push_artifact_warning(
                &mut warnings,
                "RECURSIVE_ARTIFACT_PREVIEW_UNSUPPORTED_KIND",
                "artifact kind has no inline/database-owned content to preview",
                artifact.id,
            );
        }
        RecursiveArtifactPreviewState::Unavailable => {
            push_artifact_warning(
                &mut warnings,
                "RECURSIVE_ARTIFACT_PREVIEW_UNAVAILABLE",
                "artifact has no inline/database-owned content to preview",
                artifact.id,
            );
        }
        _ => {}
    }

    Ok(RecursiveExecutionArtifactPreview {
        artifact_id: artifact.id,
        graph_id: artifact.graph_id,
        kind: artifact.kind,
        label: artifact.label,
        content_state: availability.state,
        content_type: None,
        charset: None,
        digest: None,
        digest_algorithm: None,
        total_bytes: None,
        total_lines: None,
        byte_range: None,
        line_range: None,
        shown_bytes: 0,
        shown_lines: 0,
        text: None,
        binary_unavailable_reason: availability.reason,
        truncated: false,
        truncated_by_bytes: false,
        truncated_by_lines: false,
        omitted_bytes: None,
        omitted_lines: None,
        applied_max_bytes,
        applied_max_lines,
        warnings,
    })
}

fn preview_recursive_inline_artifact(
    artifact: &RecursiveExecutionArtifact,
    content: &str,
    warnings: Vec<RecursiveReadbackWarning>,
    options: RecursiveExecutionArtifactPreviewOptions,
    applied_max_bytes: u32,
    applied_max_lines: u32,
) -> RecursiveExecutionArtifactPreview {
    let total_bytes = content.len() as u64;
    let total_lines = recursive_preview_line_count(content);
    let requested_start = options.byte_offset.unwrap_or(0).min(total_bytes) as usize;
    let start_after_byte_offset = next_char_boundary(content, requested_start);
    let requested_line_offset = options.line_offset.unwrap_or(0);
    let line_skip_bytes =
        byte_index_after_skipping_lines(&content[start_after_byte_offset..], requested_line_offset);
    let range_start = start_after_byte_offset + line_skip_bytes;

    let max_byte_end = previous_char_boundary(
        content,
        range_start
            .saturating_add(applied_max_bytes as usize)
            .min(content.len()),
        range_start,
    );
    let line_limited_len = byte_len_for_line_limit(&content[range_start..], applied_max_lines);
    let max_line_end = range_start + line_limited_len;
    let range_end = max_byte_end.min(max_line_end);
    let text = content[range_start..range_end].to_string();
    let shown_bytes = text.len() as u64;
    let shown_lines = recursive_preview_line_count(&text);
    let start_line = newline_count_before(content, range_start) as u64;
    let end_line = start_line + shown_lines;
    let truncated_by_bytes = max_byte_end < content.len() && max_byte_end <= max_line_end;
    let truncated_by_lines = max_line_end < content.len() && max_line_end <= max_byte_end;
    let truncated = truncated_by_bytes || truncated_by_lines;
    let omitted_bytes = (range_end < content.len()).then_some((content.len() - range_end) as u64);
    let omitted_lines = (end_line < total_lines).then_some(total_lines - end_line);

    RecursiveExecutionArtifactPreview {
        artifact_id: artifact.id,
        graph_id: artifact.graph_id,
        kind: artifact.kind,
        label: artifact.label.clone(),
        content_state: if truncated {
            RecursiveArtifactPreviewState::Truncated
        } else {
            RecursiveArtifactPreviewState::Available
        },
        content_type: Some("text/plain".to_string()),
        charset: Some("utf-8".to_string()),
        digest: Some(sha256_digest(content.as_bytes())),
        digest_algorithm: Some("sha256".to_string()),
        total_bytes: Some(total_bytes),
        total_lines: Some(total_lines),
        byte_range: Some(RecursiveByteRange {
            start: range_start as u64,
            end: range_end as u64,
        }),
        line_range: Some(RecursiveLineRange {
            start: start_line,
            end: end_line,
        }),
        shown_bytes,
        shown_lines,
        text: Some(text),
        binary_unavailable_reason: None,
        truncated,
        truncated_by_bytes,
        truncated_by_lines,
        omitted_bytes,
        omitted_lines,
        applied_max_bytes,
        applied_max_lines,
        warnings,
    }
}

fn bounded_recursive_artifact_preview_bytes(max_bytes: Option<u32>) -> Result<u32> {
    match max_bytes {
        Some(0) => Err(DaemonError::InvalidParam(
            "recursive artifact preview max_bytes must be positive".to_string(),
        )),
        Some(value) => Ok(value.min(MAX_RECURSIVE_ARTIFACT_PREVIEW_MAX_BYTES)),
        None => Ok(DEFAULT_RECURSIVE_ARTIFACT_PREVIEW_MAX_BYTES),
    }
}

fn bounded_recursive_artifact_preview_lines(max_lines: Option<u32>) -> Result<u32> {
    match max_lines {
        Some(0) => Err(DaemonError::InvalidParam(
            "recursive artifact preview max_lines must be positive".to_string(),
        )),
        Some(value) => Ok(value.min(MAX_RECURSIVE_ARTIFACT_PREVIEW_MAX_LINES)),
        None => Ok(DEFAULT_RECURSIVE_ARTIFACT_PREVIEW_MAX_LINES),
    }
}

fn sha256_digest(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("sha256:{}", hex::encode(hasher.finalize()))
}

fn next_char_boundary(content: &str, mut index: usize) -> usize {
    while index < content.len() && !content.is_char_boundary(index) {
        index += 1;
    }
    index
}

fn previous_char_boundary(content: &str, mut index: usize, floor: usize) -> usize {
    while index > floor && !content.is_char_boundary(index) {
        index -= 1;
    }
    index
}

fn byte_index_after_skipping_lines(content: &str, line_offset: u64) -> usize {
    if line_offset == 0 {
        return 0;
    }

    let mut skipped = 0_u64;
    for (index, byte) in content.bytes().enumerate() {
        if byte == b'\n' {
            skipped += 1;
            if skipped >= line_offset {
                return index + 1;
            }
        }
    }
    content.len()
}

fn byte_len_for_line_limit(content: &str, max_lines: u32) -> usize {
    let mut lines = 0_u32;
    for (index, byte) in content.bytes().enumerate() {
        if byte == b'\n' {
            lines += 1;
            if lines >= max_lines {
                return index + 1;
            }
        }
    }
    content.len()
}

fn recursive_preview_line_count(content: &str) -> u64 {
    if content.is_empty() {
        return 0;
    }

    let newline_count = content.bytes().filter(|byte| *byte == b'\n').count() as u64;
    if content.ends_with('\n') {
        newline_count
    } else {
        newline_count + 1
    }
}

fn newline_count_before(content: &str, index: usize) -> usize {
    content[..index]
        .bytes()
        .filter(|byte| *byte == b'\n')
        .count()
}

fn artifact_preview_availability(
    kind: RecursiveExecutionArtifactKind,
    has_content: bool,
    uri: Option<&str>,
) -> RecursiveArtifactPreviewAvailability {
    let state = artifact_preview_state(kind, has_content, uri);
    let reason = match state {
        RecursiveArtifactPreviewState::UriBlocked => {
            Some("artifact URI preview is blocked by daemon policy".to_string())
        }
        RecursiveArtifactPreviewState::UnsupportedKind => {
            Some("artifact kind has no daemon preview support".to_string())
        }
        RecursiveArtifactPreviewState::Unavailable => {
            Some("artifact has no inline content or trusted storage handle".to_string())
        }
        _ => None,
    };
    RecursiveArtifactPreviewAvailability { state, reason }
}

fn artifact_preview_state(
    kind: RecursiveExecutionArtifactKind,
    has_content: bool,
    uri: Option<&str>,
) -> RecursiveArtifactPreviewState {
    if uri.is_some() {
        return RecursiveArtifactPreviewState::UriBlocked;
    }
    if has_content {
        return RecursiveArtifactPreviewState::Available;
    }
    match kind {
        RecursiveExecutionArtifactKind::Inline => RecursiveArtifactPreviewState::Unavailable,
        RecursiveExecutionArtifactKind::File
        | RecursiveExecutionArtifactKind::SessionEvent
        | RecursiveExecutionArtifactKind::WorkflowExecution => {
            RecursiveArtifactPreviewState::UnsupportedKind
        }
    }
}

fn artifact_warning(
    code: impl Into<String>,
    message: impl Into<String>,
    artifact_id: i64,
) -> RecursiveReadbackWarning {
    RecursiveReadbackWarning {
        code: code.into(),
        message: message.into(),
        resource_type: Some("recursive_execution_artifact".to_string()),
        resource_id: Some(artifact_id.to_string()),
    }
}

fn push_artifact_warning(
    warnings: &mut Vec<RecursiveReadbackWarning>,
    code: impl Into<String>,
    message: impl Into<String>,
    artifact_id: i64,
) {
    push_warning_capped(warnings, artifact_warning(code, message, artifact_id));
}

fn push_warning_capped(
    warnings: &mut Vec<RecursiveReadbackWarning>,
    warning: RecursiveReadbackWarning,
) {
    if warnings.len() < MAX_RECURSIVE_READBACK_WARNINGS {
        warnings.push(warning);
    } else if warnings.len() == MAX_RECURSIVE_READBACK_WARNINGS {
        warnings.push(RecursiveReadbackWarning {
            code: "RECURSIVE_READBACK_WARNINGS_OMITTED".to_string(),
            message: "additional recursive readback warnings were omitted".to_string(),
            resource_type: None,
            resource_id: None,
        });
    }
}

