    /// Returns the `TempDir` guard alongside the store so the temporary
    /// directory is removed when the test ends. Do not drop the guard early
    /// (and never `mem::forget` it): the store's SQLite files live inside it,
    /// and leaking the guard orphans the directory in `/tmp` for the life of
    /// the machine.
    fn test_store() -> (tempfile::TempDir, Store) {
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("test.db");
        let store = Store::open(&db_path).expect("open store");
        (dir, store)
    }

    fn topology_node(
        id: &str,
        kind: rsi_common::types::SessionKind,
        prereqs: Vec<&str>,
        on_failure: Option<FailurePolicy>,
    ) -> TopologyNode {
        let mut params = std::collections::HashMap::new();
        params.insert(
            "instructions".to_string(),
            serde_json::json!(format!("complete {id}")),
        );
        TopologyNode {
            id: id.to_string(),
            kind,
            label: format!("{id} label"),
            prereqs: prereqs.into_iter().map(str::to_string).collect(),
            max_iterations: Some(32),
            on_failure,
            params,
        }
    }

