    fn mark_topology_graph_node_running(
        store: &Store,
        response: &RecursiveTopologyGraphCreateResponse,
        topology_node_id: &str,
    ) {
        let task_id = response
            .task_links
            .iter()
            .find(|link| link.topology_node_id == topology_node_id)
            .expect("topology node task link")
            .task_id;
        let attempt_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                response.graph.id,
                task_id,
                RecursiveAttemptPhase::Execute,
                attempt_id,
            )
            .expect("start topology graph attempt");
        store
            .transition_recursive_task_state(
                response.graph.id,
                task_id,
                RecursiveTaskLifecycleState::Running,
                Some("running before topology recovery".to_string()),
            )
            .expect("mark topology graph running");
    }

