    fn set_graph_status_direct(
        store: &Store,
        graph_id: RecursiveTaskGraphId,
        status: RecursiveGraphStatus,
    ) {
        store
            .conn
            .execute(
                "UPDATE recursive_task_graphs SET status = ?1, updated_at = ?2 WHERE id = ?3",
                params![graph_status_to_str(status), now(), graph_id.to_string()],
            )
            .expect("set graph status");
    }

    fn now() -> String {
        Utc::now().to_rfc3339()
    }

    fn insert_graph(store: &Store, graph_id: Uuid, root_id: Uuid) {
        let ts = now();
        store.conn.execute(
            "INSERT INTO recursive_task_graphs (
                id, root_task_id, title, objective, status, execution_mode,
                max_depth, max_fanout, max_descendants, step_limit, created_at, updated_at
             ) VALUES (?1, ?2, 'Root graph', 'Do the thing', 'active', 'fake', 4, 4, 16, 100, ?3, ?3)",
            params![graph_id.to_string(), root_id.to_string(), ts],
        ).expect("insert graph");
    }

    fn insert_node(
        store: &Store,
        graph_id: Uuid,
        task_id: Uuid,
        parent_id: Option<Uuid>,
        depth: u32,
        scope_units: u32,
        status: &str,
    ) {
        let ts = now();
        store.conn.execute(
            "INSERT INTO recursive_task_nodes (
                id, graph_id, parent_task_id, title, objective, scope,
                acceptance_criteria_json, depth, scope_units, max_retries, status,
                decomposed_once, created_at, updated_at
             ) VALUES (?1, ?2, ?3, 'Task', 'Objective', 'Scope', '[\"done\"]', ?4, ?5, 2, ?6, 0, ?7, ?7)",
            params![
                task_id.to_string(),
                graph_id.to_string(),
                parent_id.map(|id| id.to_string()),
                depth,
                scope_units,
                status,
                ts,
            ],
        ).expect("insert node");
    }

    fn insert_parent_edge(store: &Store, graph_id: Uuid, parent_id: Uuid, child_id: Uuid) {
        store
            .conn
            .execute(
                "INSERT INTO recursive_task_edges (
                graph_id, from_task_id, to_task_id, kind, created_at
             ) VALUES (?1, ?2, ?3, 'parent_child', ?4)",
                params![
                    graph_id.to_string(),
                    parent_id.to_string(),
                    child_id.to_string(),
                    now(),
                ],
            )
            .expect("insert parent edge");
    }

    fn setup_basic_graph() -> (Store, Uuid, Uuid, Uuid) {
        let (_dir, store) = test_store();
        let graph_id = Uuid::new_v4();
        let root_id = Uuid::new_v4();
        let child_id = Uuid::new_v4();
        insert_graph(&store, graph_id, root_id);
        insert_node(&store, graph_id, root_id, None, 0, 10, "pending");
        insert_node(&store, graph_id, child_id, Some(root_id), 1, 5, "pending");
        insert_parent_edge(&store, graph_id, root_id, child_id);
        (store, graph_id, root_id, child_id)
    }

    fn assert_integrity_error(store: &Store, graph_id: Uuid, needle: &str) {
        let error = store
            .validate_recursive_task_graph_integrity(RecursiveTaskGraphId(graph_id))
            .expect_err("expected integrity error")
            .to_string();
        assert!(
            error.contains(needle),
            "expected error to contain {needle:?}, got {error:?}"
        );
    }

    fn assert_error_contains(error: DaemonError, needle: &str) {
        let error = error.to_string();
        assert!(
            error.contains(needle),
            "expected error to contain {needle:?}, got {error:?}"
        );
    }

