    #[test]
    fn recursive_dag_typed_materialization_schema_exists_at_latest() {
        let (_dir, store) = test_store();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("schema version");
        assert_eq!(version, LATEST_SCHEMA_VERSION);
        for table in [
            "recursive_typed_artifact_roles",
            "recursive_test_results",
            "recursive_diff_summaries",
            "recursive_diff_files",
            "recursive_scheduler_reports",
            "recursive_scheduler_report_steps",
        ] {
            assert_eq!(
                table_count(&store, table),
                0,
                "typed materialization table {table} exists and starts empty"
            );
        }
    }

    #[test]
    fn recursive_dag_typed_artifact_role_provenance_round_trips() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 8);
        let artifact = store
            .record_recursive_execution_artifacts(
                RecursiveTaskGraphId(graph_id),
                vec![RecursiveExecutionArtifactCreate {
                    task_id: RecursiveTaskId(root_id),
                    attempt_id: None,
                    kind: RecursiveExecutionArtifactKind::Inline,
                    label: "typed role artifact".to_string(),
                    content: Some("typed".to_string()),
                    uri: None,
                    metadata: serde_json::json!({ "source": "test" }),
                }],
            )
            .expect("record artifact")
            .remove(0);

        let row = store
            .insert_recursive_typed_artifact_role(RecursiveTypedArtifactRoleCreate {
                graph_id: RecursiveTaskGraphId(graph_id),
                task_id: Some(RecursiveTaskId(root_id)),
                attempt_id: None,
                live_attempt_id: None,
                scheduler_run_id: None,
                validation_id: None,
                artifact_id: artifact.id,
                role: RecursiveArtifactRole::ProducedArtifact,
                provenance: RecursiveArtifactProvenance::DaemonRecorded,
                source: RecursiveTypedSource::DaemonCollected,
                trust_level: RecursiveTrustLevel::Verified,
                metadata_state: RecursiveArtifactMetadataState::Valid,
                source_artifact_id: Some(artifact.id),
                source_digest: Some("sha256:test".to_string()),
                schema_version: Some(1),
                metadata: serde_json::json!({ "role_test": true }),
            })
            .expect("insert typed role");

        assert_eq!(row.graph_id, RecursiveTaskGraphId(graph_id));
        assert_eq!(row.role, RecursiveArtifactRole::ProducedArtifact);
        assert_eq!(row.provenance, RecursiveArtifactProvenance::DaemonRecorded);
        assert_eq!(row.source, RecursiveTypedSource::DaemonCollected);
        assert_eq!(row.trust_level, RecursiveTrustLevel::Verified);
        assert_eq!(row.source_artifact_id, Some(artifact.id));
        assert_eq!(row.source_digest.as_deref(), Some("sha256:test"));
        assert_eq!(row.schema_version, Some(1));
        assert!(row.warnings.is_empty());

        let rows = store
            .load_recursive_typed_artifact_roles_for_artifact(
                RecursiveTaskGraphId(graph_id),
                artifact.id,
            )
            .expect("load typed role");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0], row);
    }

    #[test]
    fn recursive_dag_typed_test_rows_round_trip_with_and_without_name() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 8);
        let first_id = RecursiveTestResultId::new();
        let second_id = RecursiveTestResultId::new();

        for (test_id, name, command, display_label, index) in [
            (
                first_id,
                Some("unit::passes".to_string()),
                Some("cargo test unit::passes".to_string()),
                "unit::passes".to_string(),
                0,
            ),
            (
                second_id,
                None,
                Some("cargo test integration".to_string()),
                "cargo test integration".to_string(),
                1,
            ),
        ] {
            store
                .insert_recursive_typed_test_result(RecursiveTypedTestResultCreate {
                    test_id,
                    graph_id: RecursiveTaskGraphId(graph_id),
                    task_id: Some(RecursiveTaskId(root_id)),
                    attempt_id: None,
                    live_attempt_id: None,
                    scheduler_run_id: None,
                    validation_id: None,
                    artifact_id: None,
                    test_index: index,
                    source: RecursiveTypedSource::DaemonCollected,
                    trust_level: RecursiveTrustLevel::Verified,
                    status: RecursiveTypedTestStatus::Passed,
                    required: true,
                    name,
                    command,
                    display_label,
                    duration_ms: Some(123),
                    exit_code: Some(0),
                    failure_summary: None,
                    artifact_links: RecursiveTypedTestArtifactLinks::default(),
                    related_validation_issue_ids: Vec::new(),
                    suggested_next_action: None,
                    metadata_state: RecursiveArtifactMetadataState::Valid,
                    source_artifact_id: None,
                    source_digest: None,
                    schema_version: Some(1),
                    metadata: serde_json::json!({ "test": index }),
                })
                .expect("insert typed test result");
        }

        let with_name = store
            .load_recursive_typed_test_summary(first_id)
            .expect("load typed test")
            .expect("named typed test");
        assert_eq!(with_name.name.as_deref(), Some("unit::passes"));
        assert_eq!(
            with_name.command.as_deref(),
            Some("cargo test unit::passes")
        );
        assert_eq!(with_name.display_label, "unit::passes");
        assert_eq!(
            with_name.metadata_state,
            RecursiveArtifactMetadataState::Valid
        );

        let without_name = store
            .load_recursive_typed_test_summary(second_id)
            .expect("load typed test")
            .expect("unnamed typed test");
        assert!(without_name.name.is_none());
        assert_eq!(
            without_name.command.as_deref(),
            Some("cargo test integration")
        );
        assert_eq!(without_name.display_label, "cargo test integration");
    }

    #[test]
    fn recursive_dag_typed_diff_rows_round_trip_with_hunks_unavailable() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 8);
        let diff_id = RecursiveDiffId::new();
        let file_id = RecursiveDiffFileId::new();

        store
            .insert_recursive_typed_diff(RecursiveTypedDiffCreate {
                diff_id,
                graph_id: RecursiveTaskGraphId(graph_id),
                task_id: Some(RecursiveTaskId(root_id)),
                attempt_id: None,
                live_attempt_id: None,
                scheduler_run_id: None,
                validation_id: None,
                artifact_id: None,
                diff_index: 0,
                source: RecursiveTypedSource::DaemonCollected,
                trust_level: RecursiveTrustLevel::Verified,
                file_count: 1,
                binary_file_count: 0,
                truncated_file_count: 0,
                additions: Some(7),
                deletions: Some(3),
                hunk_count: None,
                metadata_state: RecursiveArtifactMetadataState::Valid,
                source_artifact_id: None,
                source_digest: Some("sha256:diff".to_string()),
                schema_version: Some(1),
                metadata: serde_json::json!({ "diff": true }),
                files: vec![RecursiveTypedDiffFileCreate {
                    file_id,
                    file_index: 0,
                    display_path: PathBuf::from("crates/rsid/src/store/recursive_dag.rs"),
                    previous_display_path: None,
                    status: RecursiveTypedDiffFileStatus::Modified,
                    additions: Some(7),
                    deletions: Some(3),
                    hunk_count: None,
                    binary: false,
                    inside_allowed_root: Some(true),
                    validation_issue_count: 0,
                    metadata_state: RecursiveArtifactMetadataState::Valid,
                    metadata: serde_json::json!({ "file": true }),
                }],
            })
            .expect("insert typed diff");

        let summary = store
            .load_recursive_typed_diff_summary(diff_id)
            .expect("load diff")
            .expect("diff summary");
        assert_eq!(summary.diff_id, diff_id);
        assert_eq!(summary.file_count, 1);
        assert_eq!(summary.additions, Some(7));
        assert_eq!(summary.hunk_count, None);

        let files = store
            .load_recursive_typed_diff_files(diff_id)
            .expect("load diff files");
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].file_id, file_id);
        assert_eq!(files[0].status, RecursiveTypedDiffFileStatus::Modified);
        assert_eq!(files[0].inside_allowed_root, Some(true));

        let hunks = store
            .load_recursive_typed_diff_hunks_unavailable(
                RecursiveTaskGraphId(graph_id),
                diff_id,
                file_id,
                50,
            )
            .expect("load hunk state")
            .expect("hunk readback");
        assert_eq!(hunks.state, RecursiveTypedDiffHunkState::Unavailable);
        assert!(!hunks.has_more);
        assert!(hunks.next_cursor.is_none());
        assert!(
            hunks
                .reason
                .as_deref()
                .unwrap()
                .contains("not materialized")
        );
    }

    #[test]
    fn recursive_dag_scheduler_report_materialization_uses_uuid_report_id() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 8);
        let run = start_test_run(&store, graph_id, 8);

        store
            .finish_recursive_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish scheduler run");

        let summary = store
            .load_recursive_scheduler_report_summary_by_run(run.id)
            .expect("load scheduler report")
            .expect("scheduler report summary");
        assert_eq!(summary.run_id, run.id);
        assert_eq!(summary.graph_id, RecursiveTaskGraphId(graph_id));
        assert_eq!(summary.source, RecursiveTypedSource::SchedulerReport);
        assert_eq!(summary.trust_level, RecursiveTrustLevel::SchedulerOwned);
        assert_eq!(summary.report_id, deterministic_scheduler_report_id(run.id));
        assert!(!summary.report_id.0.is_nil());
        assert_eq!(summary.step_count, 0);
        assert_eq!(summary.max_steps, 8);

        let by_id = store
            .load_recursive_scheduler_report_summary(summary.report_id)
            .expect("load scheduler report by id")
            .expect("scheduler report by id");
        assert_eq!(by_id, summary);
    }

    #[test]
    fn recursive_dag_scheduler_report_materialization_covers_failed_and_expired_runs() {
        let (_dir, store) = test_store();
        let (failed_graph_id, _) = create_graph(&store, 8);
        let failed_run = start_test_run(&store, failed_graph_id, 8);
        let failed = store
            .fail_recursive_scheduler_run(failed_run.id, 0, "executor failed".to_string())
            .expect("fail scheduler run");

        let failed_summary = store
            .load_recursive_scheduler_report_summary_by_run(failed.id)
            .expect("load failed scheduler report")
            .expect("failed scheduler report summary");
        assert_eq!(
            failed_summary.report_id,
            deterministic_scheduler_report_id(failed.id)
        );
        assert_eq!(
            failed_summary.run_status,
            RecursiveSchedulerRunStatus::Failed
        );
        assert_eq!(
            failed_summary.stop_reason,
            Some(RecursiveSchedulerStopReason::ExecutorError)
        );
        assert_eq!(
            failed_summary.failure_reason.as_deref(),
            Some("executor failed")
        );
        assert_eq!(failed_summary.report_artifact_id, None);

        let (expired_graph_id, _) = create_graph(&store, 8);
        let expired_run = start_test_run(&store, expired_graph_id, 8);
        expire_scheduler_run_lease_direct(&store, expired_run.id);
        let reclaimed = store
            .reclaim_expired_recursive_scheduler_runs()
            .expect("reclaim expired scheduler run");
        assert_eq!(reclaimed.len(), 1);
        assert_eq!(reclaimed[0].id, expired_run.id);

        let expired_summary = store
            .load_recursive_scheduler_report_summary_by_run(expired_run.id)
            .expect("load expired scheduler report")
            .expect("expired scheduler report summary");
        assert_eq!(
            expired_summary.report_id,
            deterministic_scheduler_report_id(expired_run.id)
        );
        assert_eq!(
            expired_summary.run_status,
            RecursiveSchedulerRunStatus::LeaseExpired
        );
        assert_eq!(
            expired_summary.stop_reason,
            Some(RecursiveSchedulerStopReason::LeaseExpired)
        );
        assert_eq!(expired_summary.report_artifact_id, None);
    }

    #[test]
    fn recursive_dag_typed_materialization_tolerates_malformed_metadata() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 8);
        let test_id = RecursiveTestResultId::new();
        store
            .insert_recursive_typed_test_result(RecursiveTypedTestResultCreate {
                test_id,
                graph_id: RecursiveTaskGraphId(graph_id),
                task_id: Some(RecursiveTaskId(root_id)),
                attempt_id: None,
                live_attempt_id: None,
                scheduler_run_id: None,
                validation_id: None,
                artifact_id: None,
                test_index: 0,
                source: RecursiveTypedSource::DaemonCollected,
                trust_level: RecursiveTrustLevel::Verified,
                status: RecursiveTypedTestStatus::Failed,
                required: true,
                name: Some("bad metadata test".to_string()),
                command: None,
                display_label: "bad metadata test".to_string(),
                duration_ms: None,
                exit_code: Some(1),
                failure_summary: Some("failed".to_string()),
                artifact_links: RecursiveTypedTestArtifactLinks::default(),
                related_validation_issue_ids: Vec::new(),
                suggested_next_action: None,
                metadata_state: RecursiveArtifactMetadataState::Valid,
                source_artifact_id: None,
                source_digest: None,
                schema_version: Some(1),
                metadata: serde_json::json!({ "ok": true }),
            })
            .expect("insert typed test");

        store
            .conn
            .execute_batch("PRAGMA ignore_check_constraints = ON;")
            .expect("disable constraints");
        store
            .conn
            .execute(
                "UPDATE recursive_test_results
                 SET metadata_json = '{not-json'
                 WHERE test_id = ?1",
                params![test_id.to_string()],
            )
            .expect("corrupt typed test metadata");
        store
            .conn
            .execute_batch("PRAGMA ignore_check_constraints = OFF;")
            .expect("restore constraints");

        let summary = store
            .load_recursive_typed_test_summary(test_id)
            .expect("load typed test")
            .expect("typed test");
        assert_eq!(
            summary.metadata_state,
            RecursiveArtifactMetadataState::Malformed
        );
        assert_eq!(summary.name.as_deref(), Some("bad metadata test"));
        assert_eq!(summary.status, RecursiveTypedTestStatus::Failed);
    }

    #[test]
    fn recursive_dag_live_validation_commit_materializes_typed_rows() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let mut output = live_success_output(&live);
        output.diffs = vec![RecursiveLiveDiffSummary {
            worktree_root: None,
            sandbox_root: None,
            files: vec![RecursiveLiveDiffFileSummary {
                path: PathBuf::from("src/lib.rs"),
                status: RecursiveLiveDiffFileStatus::Modified,
                previous_path: None,
                insertions: Some(2),
                deletions: Some(1),
                inside_allowed_root: Some(true),
                metadata: serde_json::json!({ "file": "src/lib.rs" }),
            }],
            diff_artifact: None,
            clean_worktree: Some(false),
            metadata: serde_json::json!({ "diff": "summary" }),
        }];
        let validation = validate_live_output_for_store(&store, &live, &output);
        let result = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect("commit live validation");
        let validation_id = result
            .validation_result
            .summary
            .validation_id
            .expect("validation id");

        let test = store
            .load_recursive_typed_test_summary(deterministic_test_id(validation_id, 0))
            .expect("load typed test")
            .expect("typed test materialized");
        assert_eq!(test.validation_id, Some(validation_id));
        assert_eq!(test.live_attempt_id, Some(live.summary.id));
        assert_eq!(test.source, RecursiveTypedSource::LiveValidation);
        assert_eq!(test.trust_level, RecursiveTrustLevel::Normalized);
        assert!(test.name.is_none());

        let diff_id = deterministic_diff_id(validation_id, 0);
        let diff = store
            .load_recursive_typed_diff_summary(diff_id)
            .expect("load typed diff")
            .expect("typed diff materialized");
        assert_eq!(diff.validation_id, Some(validation_id));
        assert_eq!(diff.file_count, 1);
        assert_eq!(diff.additions, Some(2));
        assert_eq!(diff.deletions, Some(1));

        let files = store
            .load_recursive_typed_diff_files(diff_id)
            .expect("load typed diff files");
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].display_path, PathBuf::from("src/lib.rs"));

        let role_rows = store
            .load_recursive_typed_artifact_roles_for_artifact(
                live.summary.graph_id,
                result.validation_artifact.id,
            )
            .expect("load typed artifact roles");
        assert_eq!(role_rows.len(), 1);
        assert_eq!(role_rows[0].role, RecursiveArtifactRole::ValidationReport);
        assert_eq!(role_rows[0].source, RecursiveTypedSource::LiveValidation);
        assert_eq!(role_rows[0].trust_level, RecursiveTrustLevel::Normalized);
    }

