    fn validate_live_output_for_store(
        store: &Store,
        live: &RecursiveLiveAttemptDetail,
        output: &RecursiveLiveOutputEnvelope,
    ) -> RecursiveLiveOutputValidationResult {
        let detail = store
            .get_recursive_task_graph(live.summary.graph_id)
            .expect("load graph")
            .expect("graph");
        let task = detail
            .nodes
            .iter()
            .find(|task| task.id == live.summary.task_id)
            .expect("task");
        let attempt = detail
            .attempts
            .iter()
            .find(|attempt| attempt.id == live.summary.attempt_id)
            .expect("attempt");
        let context = RecursiveLiveOutputValidationContext::new(
            task,
            attempt,
            live.summary.id,
            live.summary.scheduler_run_id,
            live.summary.session_id,
        )
        .with_graph(&detail);
        validate_recursive_live_output(output, &context)
    }

    fn validate_live_output_json_for_store(
        store: &Store,
        live: &RecursiveLiveAttemptDetail,
        raw_output: &str,
        repair_attempts: u32,
    ) -> RecursiveLiveOutputValidationResult {
        let detail = store
            .get_recursive_task_graph(live.summary.graph_id)
            .expect("load graph")
            .expect("graph");
        let task = detail
            .nodes
            .iter()
            .find(|task| task.id == live.summary.task_id)
            .expect("task");
        let attempt = detail
            .attempts
            .iter()
            .find(|attempt| attempt.id == live.summary.attempt_id)
            .expect("attempt");
        let mut context = RecursiveLiveOutputValidationContext::new(
            task,
            attempt,
            live.summary.id,
            live.summary.scheduler_run_id,
            live.summary.session_id,
        )
        .with_graph(&detail);
        context.retry_policy = RecursiveLiveOutputRepairRetryPolicy {
            remaining_output_repair_attempts: repair_attempts,
            remaining_task_retries: Some(1),
        };
        validate_recursive_live_output_json(raw_output, &context)
    }

    fn validate_cancelled_live_output_for_store(
        store: &Store,
        live: &RecursiveLiveAttemptDetail,
        output: &RecursiveLiveOutputEnvelope,
        request_id: RecursiveCancellationRequestId,
    ) -> RecursiveLiveOutputValidationResult {
        let detail = store
            .get_recursive_task_graph(live.summary.graph_id)
            .expect("load graph")
            .expect("graph");
        let task = detail
            .nodes
            .iter()
            .find(|task| task.id == live.summary.task_id)
            .expect("task");
        let attempt = detail
            .attempts
            .iter()
            .find(|attempt| attempt.id == live.summary.attempt_id)
            .expect("attempt");
        let mut context = RecursiveLiveOutputValidationContext::new(
            task,
            attempt,
            live.summary.id,
            live.summary.scheduler_run_id,
            live.summary.session_id,
        )
        .with_graph(&detail);
        context.cancellation_context = RecursiveLiveCancellationValidationContext {
            open_or_observed_request_ids: vec![request_id],
            interrupted_session: false,
            live_interrupt_recorded: false,
        };
        validate_recursive_live_output(output, &context)
    }

