    #[test]
    fn recursive_dag_topology_snapshot_json_round_trips_from_store() {
        let (_dir, store) = test_store();
        let topology = insert_research_implement_verify_topology(&store);
        let response = store
            .create_recursive_graph_from_topology_node(topology_graph_request(topology.id))
            .expect("create graph");
        let loaded_link = store
            .load_recursive_topology_graph_link(response.graph.id)
            .expect("load graph link")
            .expect("graph link");

        let (
            topology_snapshot_json,
            selected_slice_json,
            policy_snapshot_json,
            workflow_execution_linkage_json,
        ): (String, String, String, String) = store
            .conn
            .query_row(
                "SELECT topology_snapshot_json, selected_slice_json,
                        policy_snapshot_json, workflow_execution_linkage_json
                 FROM recursive_topology_graph_links
                 WHERE graph_id = ?1",
                params![response.graph.id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .expect("raw graph snapshots");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&topology_snapshot_json)
                .expect("topology snapshot json"),
            loaded_link.topology_snapshot
        );
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&selected_slice_json)
                .expect("selected slice json"),
            loaded_link.selected_slice
        );
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&policy_snapshot_json)
                .expect("policy snapshot json"),
            loaded_link.policy_snapshot
        );
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&workflow_execution_linkage_json)
                .expect("workflow execution linkage json"),
            loaded_link.workflow_execution_linkage
        );

        let task_links = store
            .load_recursive_topology_task_links(response.graph.id)
            .expect("load task links");
        for link in task_links {
            let (source_params_json, topology_node_snapshot_json, task_policy_snapshot_json): (
                String,
                String,
                String,
            ) = store
                .conn
                .query_row(
                    "SELECT source_params_json, topology_node_snapshot_json,
                            policy_snapshot_json
                     FROM recursive_topology_task_links
                     WHERE task_id = ?1",
                    params![link.task_id.to_string()],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .expect("raw task snapshots");
            assert_eq!(
                serde_json::from_str::<serde_json::Value>(&source_params_json)
                    .expect("source params json"),
                link.source_params
            );
            assert_eq!(
                serde_json::from_str::<serde_json::Value>(&topology_node_snapshot_json)
                    .expect("topology node snapshot json"),
                link.topology_node_snapshot
            );
            assert_eq!(
                serde_json::from_str::<serde_json::Value>(&task_policy_snapshot_json)
                    .expect("task policy snapshot json"),
                link.policy_snapshot
            );
        }

        let encoded = serde_json::to_value(&response).expect("encode response");
        let decoded: RecursiveTopologyGraphCreateResponse =
            serde_json::from_value(encoded).expect("decode response");
        assert_eq!(decoded.graph_link, response.graph_link);
        assert_eq!(decoded.task_links, response.task_links);
    }

