    #[test]
    fn recursive_dag_topology_fake_scheduler_resolver_requires_unique_fake_link() {
        let (_dir, store) = test_store();
        let topology = insert_research_implement_verify_topology(&store);
        let workflow_execution_id = Uuid::new_v4();
        let first = store
            .create_recursive_graph_from_topology_node(topology_graph_request_variant(
                topology.id,
                "verify",
                0,
                "topology-t3-resolve-one",
                workflow_execution_id,
                None,
            ))
            .expect("create first graph");
        let second = store
            .create_recursive_graph_from_topology_node(topology_graph_request_variant(
                topology.id,
                "verify",
                0,
                "topology-t3-resolve-two",
                Uuid::new_v4(),
                None,
            ))
            .expect("create second graph");

        let unique = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                topology_id: Some(topology.id),
                workflow_execution_id: Some(workflow_execution_id),
                node_id: Some("verify".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect("unique link resolves");
        assert_eq!(unique.graph.id, first.graph.id);
        assert_eq!(unique.graph_link.graph_id, first.graph.id);
        assert_eq!(unique.task_links.len(), 3);

        let ambiguous = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                topology_id: Some(topology.id),
                node_id: Some("verify".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect_err("ambiguous topology filters reject");
        assert_error_contains(ambiguous, "ambiguous recursive topology graph links");

        let explicit = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                graph_id: Some(second.graph.id),
                topology_id: Some(topology.id),
                node_id: Some("verify".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect("explicit graph id resolves");
        assert_eq!(explicit.graph.id, second.graph.id);

        let mut other_topology = topology.clone();
        other_topology.id = Uuid::new_v4();
        other_topology.name = format!("research-implement-verify-{}", other_topology.id);
        store
            .insert_topology(&other_topology)
            .expect("insert other topology");
        let wrong_topology = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                graph_id: Some(first.graph.id),
                topology_id: Some(other_topology.id),
                node_id: Some("verify".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect_err("explicit graph id from another topology rejects");
        assert_error_contains(wrong_topology, "does not match topology_id filter");

        let wrong_node = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                graph_id: Some(first.graph.id),
                topology_id: Some(topology.id),
                node_id: Some("research".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect_err("explicit graph id from another source node rejects");
        assert_error_contains(wrong_node, "does not match node_id filter");

        let unknown = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                topology_id: Some(topology.id),
                node_id: Some("missing".to_string()),
                topology_iteration: Some(0),
                execution_owner: Some(RECURSIVE_TOPOLOGY_EXECUTION_OWNER_FAKE.to_string()),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect_err("unknown node/link rejects");
        assert_error_contains(unknown, "recursive topology graph link not found");
        assert_eq!(table_count(&store, "recursive_task_graphs"), 2);
        assert_eq!(table_count(&store, "recursive_scheduler_runs"), 0);
    }

    #[test]
    fn recursive_dag_topology_fake_scheduler_resolver_rejects_non_fake_owner() {
        let (_dir, store) = test_store();
        let topology = insert_research_implement_verify_topology(&store);
        let response = store
            .create_recursive_graph_from_topology_node(topology_graph_request_variant(
                topology.id,
                "verify",
                0,
                "topology-t3-non-fake-owner",
                Uuid::new_v4(),
                None,
            ))
            .expect("create graph");
        store
            .conn
            .execute(
                "UPDATE recursive_topology_graph_links
                 SET execution_owner = 'topology_graph_runner'
                 WHERE graph_id = ?1",
                params![response.graph.id.to_string()],
            )
            .expect("simulate non-fake owner");

        let error = store
            .resolve_recursive_topology_fake_scheduler_graph(RecursiveTopologyGraphListFilter {
                graph_id: Some(response.graph.id),
                include_quarantined: true,
                ..RecursiveTopologyGraphListFilter::default()
            })
            .expect_err("non-fake owner rejects");
        assert_error_contains(error, "fake scheduler requires recursive_dag_fake");
        assert_eq!(table_count(&store, "recursive_scheduler_runs"), 0);
    }

    #[test]
    fn recursive_dag_topology_recovery_graph_target_is_idempotent_and_replays() {
        let (_dir, store) = test_store();
        let topology = insert_research_implement_verify_topology(&store);
        let response = store
            .create_recursive_graph_from_topology_node(topology_graph_request_variant(
                topology.id,
                "verify",
                0,
                "topology-t5-recovery-graph",
                Uuid::new_v4(),
                None,
            ))
            .expect("create topology graph");
        mark_topology_graph_node_running(&store, &response, "verify");

        let mut request = topology_graph_recovery_request(topology.id, "verify");
        request.graph_id = Some(response.graph.id);
        request.idempotency_key = Some("caller-t5-recovery-graph".to_string());

        let first = store
            .continue_topology_recursive_recovery(request.clone())
            .expect("topology recovery");
        assert!(!first.replayed);
        assert_eq!(first.matched_graph_count, 1);
        assert_eq!(first.eligible_count, 1);
        assert_eq!(first.checked_count, 1);
        assert_eq!(first.recovered_count, 1);
        assert_eq!(first.targets.len(), 1);
        assert_eq!(
            first.targets[0].outcome,
            TopologyRecursiveRecoveryOutcome::Recovered
        );
        let pass = first.pass.as_ref().expect("recovery pass");
        assert_eq!(pass.source, RecursiveRecoverySource::ManualRpc);
        assert!(pass.idempotency_key.is_some());
        assert!(pass.request_fingerprint.is_some());
        assert_eq!(
            pass.source_context
                .as_ref()
                .and_then(|context| context["kind"].as_str()),
            Some("topology_recursive_recovery")
        );
        assert_eq!(table_count(&store, "recursive_recovery_passes"), 1);

        let repeat = store
            .continue_topology_recursive_recovery(request.clone())
            .expect("idempotent replay");
        assert!(repeat.replayed);
        assert_eq!(
            repeat.pass.as_ref().map(|pass| pass.id),
            first.pass.as_ref().map(|pass| pass.id)
        );
        assert_eq!(table_count(&store, "recursive_recovery_passes"), 1);

        let mut conflict = request;
        conflict.max_graphs = 2;
        let error = store
            .continue_topology_recursive_recovery(conflict)
            .expect_err("fingerprint conflict rejects");
        assert_error_contains(error, "idempotency conflict");
        assert_eq!(table_count(&store, "recursive_recovery_passes"), 1);
    }

