    #[test]
    fn recursive_dag_live_output_invalid_decomposition_rolls_back_children_and_artifacts() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let mut output = live_decomposition_output(&live);
        let RecursiveLiveOutputOutcome::Decomposition(payload) = &mut output.outcome else {
            panic!("expected decomposition output");
        };
        payload.children[0].task_id = Some(live.summary.task_id);
        let validation = accepted_validation_result_for_output(
            &live,
            &output,
            RecursiveLiveOutputMappingDecision::Decomposition,
        );

        let error = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect_err("invalid decomposition must roll back");
        assert_error_contains(error, "duplicate recursive task id");
        let detail = store
            .get_recursive_task_graph(live.summary.graph_id)
            .expect("graph")
            .expect("graph");
        assert_eq!(detail.nodes.len(), 1);
        assert!(detail.injection_batches.is_empty());
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        assert_eq!(validation_count(&store, live.summary.id), 0);
        let live_after = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load live")
            .expect("live");
        assert_eq!(
            live_after.summary.status,
            RecursiveLiveAttemptStatus::Running
        );
    }

    #[test]
    fn recursive_dag_live_output_repair_persists_validation_without_repair_loop() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let mut validation =
            validate_live_output_json_for_store(&store, &live, "{ invalid json", 1);
        assert_eq!(
            validation.summary.status,
            RecursiveLiveOutputValidationStatus::Repairable
        );
        assert_eq!(
            validation.summary.mapping_decision,
            Some(RecursiveLiveOutputMappingDecision::RepairSameLiveAttempt)
        );
        validation.parser_source = Some(RecursiveLiveOutputParserSource::Inline {
            description: Some("malformed test output".to_string()),
        });
        let mut commit = commit_for_live(&live, None, validation);
        commit.produced_artifacts.clear();
        commit.test_artifacts.clear();
        commit.diff_artifacts.clear();

        let result = store
            .commit_recursive_live_output_validation(commit)
            .expect("commit repairable validation");

        assert_eq!(
            result.live_attempt.summary.status,
            RecursiveLiveAttemptStatus::Running
        );
        assert_eq!(
            result.recursive_attempt.status,
            RecursiveAttemptStatus::Running
        );
        assert_eq!(validation_count(&store, live.summary.id), 1);
        assert!(result.normalized_output_artifact.is_none());
        assert_eq!(artifact_count(&store, live.summary.graph_id), 2);

        let (
            status,
            issue_summary_json,
            parser_source_json,
            retry_decision_json,
            normalized_digest,
        ): (
            String,
            String,
            Option<String>,
            Option<String>,
            Option<String>,
        ) = store
            .conn
            .query_row(
                "SELECT status, issue_summary_json, parser_source_json,
                        retry_decision_json, normalized_digest
                 FROM recursive_live_output_validations
                 WHERE live_attempt_id = ?1",
                params![live.summary.id.to_string()],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                    ))
                },
            )
            .expect("repair validation readback");
        assert_eq!(status, "repairable");
        assert!(normalized_digest.is_none());
        let issues: serde_json::Value =
            serde_json::from_str(&issue_summary_json).expect("issue summary json");
        assert_eq!(issues[0]["severity"], "error");
        assert!(
            issues[0]["message"]
                .as_str()
                .unwrap_or_default()
                .contains("not valid JSON")
        );
        let parser_source: serde_json::Value =
            serde_json::from_str(parser_source_json.as_deref().expect("parser source json"))
                .expect("parser source");
        assert_eq!(parser_source["kind"], "inline");
        assert_eq!(parser_source["description"], "malformed test output");
        let retry_decision: serde_json::Value =
            serde_json::from_str(retry_decision_json.as_deref().expect("retry decision json"))
                .expect("retry decision");
        assert_eq!(retry_decision["decision"], "retry_same_live_attempt");
    }

    #[test]
    fn recursive_dag_live_output_validation_read_helpers_are_read_only() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let mut validation =
            validate_live_output_json_for_store(&store, &live, "{ invalid json", 1);
        validation.parser_source = Some(RecursiveLiveOutputParserSource::Inline {
            description: Some("store read helper malformed output".to_string()),
        });
        validation.validation_report = Some(serde_json::json!({"status": "repairable"}));
        validation.metadata = serde_json::json!({"store_readback": true});

        let result = store
            .commit_recursive_live_output_validation(commit_for_live(&live, None, validation))
            .expect("commit repair validation");
        let validation_id = result
            .validation_result
            .summary
            .validation_id
            .expect("validation id");
        let counts_before = (
            validation_count(&store, live.summary.id),
            artifact_count(&store, live.summary.graph_id),
        );

        let read = store
            .load_recursive_live_output_validation_result(
                validation_id,
                RecursiveLiveOutputValidationReadOptions {
                    include_issues: true,
                    include_normalized_output: false,
                    include_validation_report: true,
                },
            )
            .expect("read validation")
            .expect("validation row");
        assert_eq!(read.summary.validation_id, Some(validation_id));
        assert_eq!(read.issues.len(), 1);
        assert_eq!(
            read.issues[0].severity,
            RecursiveLiveValidationIssueSeverity::Error
        );
        assert_eq!(
            read.validation_report,
            Some(serde_json::json!({"status": "repairable"}))
        );
        assert_eq!(read.artifact_links.produced_artifact_ids.len(), 1);
        assert_eq!(read.artifact_links.test_artifact_ids.len(), 1);
        assert_eq!(read.artifact_links.diff_artifact_ids.len(), 1);

        let latest = store
            .load_latest_recursive_live_output_validation_result_for_live_attempt(
                live.summary.id,
                RecursiveLiveOutputValidationReadOptions {
                    include_issues: false,
                    include_normalized_output: false,
                    include_validation_report: false,
                },
            )
            .expect("latest validation")
            .expect("latest");
        assert_eq!(latest.summary.validation_id, Some(validation_id));
        assert!(latest.issues.is_empty());

        let list = store
            .list_recursive_live_output_validation_results(
                RecursiveLiveOutputValidationListFilter {
                    graph_id: Some(live.summary.graph_id),
                    status: Some(RecursiveLiveOutputValidationStatus::Repairable),
                    include_issues: true,
                    limit: Some(10),
                    ..RecursiveLiveOutputValidationListFilter::default()
                },
            )
            .expect("list validations");
        assert_eq!(list.len(), 1);
        assert_eq!(list[0].summary.validation_id, Some(validation_id));
        assert_eq!(list[0].issues.len(), 1);

        let issues = store
            .list_recursive_live_validation_issues(RecursiveLiveValidationIssueFilter {
                validation_id: Some(validation_id),
                severity: Some(RecursiveLiveValidationIssueSeverity::Error),
                class: Some(RecursiveLiveValidationIssueClass::Malformed),
                code: Some(RecursiveLiveValidationIssueCode::MalformedOutput),
                limit: Some(10),
                ..RecursiveLiveValidationIssueFilter::default()
            })
            .expect("list issues");
        assert_eq!(issues.len(), 1);

        let artifacts = store
            .load_recursive_live_attempt_artifacts(
                live.summary.id,
                RecursiveLiveAttemptArtifactReadOptions {
                    include_prompt: true,
                    include_raw_output: true,
                    include_normalized_output: true,
                    include_validation_report: true,
                    include_diff: true,
                    include_tests: true,
                    include_produced_artifacts: true,
                },
            )
            .expect("artifact readback")
            .expect("artifacts");
        assert_eq!(artifacts.raw_output_artifacts.len(), 1);
        assert_eq!(artifacts.validation_artifacts.len(), 1);
        assert_eq!(artifacts.produced_artifacts.len(), 1);
        assert_eq!(artifacts.test_artifacts.len(), 1);
        assert_eq!(artifacts.diff_artifacts.len(), 1);

        let counts_after = (
            validation_count(&store, live.summary.id),
            artifact_count(&store, live.summary.graph_id),
        );
        assert_eq!(counts_after, counts_before);
    }

    #[test]
    fn recursive_dag_live_output_validation_read_helpers_order_multiple_records() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);

        let mut first = validate_live_output_json_for_store(&store, &live, "{ invalid json", 2);
        first.parser_source = Some(RecursiveLiveOutputParserSource::Inline {
            description: Some("first malformed output".to_string()),
        });
        first.issues[0].message = "first validation issue".to_string();
        let first = store
            .commit_recursive_live_output_validation(commit_for_live(&live, None, first))
            .expect("commit first validation")
            .validation_result;
        let first_id = first.summary.validation_id.expect("first validation id");

        let mut second = validate_live_output_json_for_store(&store, &live, "{ invalid json", 2);
        second.parser_source = Some(RecursiveLiveOutputParserSource::Inline {
            description: Some("second malformed output".to_string()),
        });
        second.issues[0].message = "second validation issue".to_string();
        let second = store
            .commit_recursive_live_output_validation(commit_for_live(&live, None, second))
            .expect("commit second validation")
            .validation_result;
        let second_id = second.summary.validation_id.expect("second validation id");

        store
            .conn
            .execute(
                "UPDATE recursive_live_output_validations
                 SET created_at = CASE id
                     WHEN ?1 THEN '2026-05-26T10:00:00.000000000Z'
                     WHEN ?2 THEN '2026-05-26T10:01:00.000000000Z'
                     ELSE created_at
                 END
                 WHERE id IN (?1, ?2)",
                params![first_id.to_string(), second_id.to_string()],
            )
            .expect("stabilize validation timestamps");

        let latest = store
            .load_latest_recursive_live_output_validation_result_for_live_attempt(
                live.summary.id,
                RecursiveLiveOutputValidationReadOptions {
                    include_issues: true,
                    include_normalized_output: false,
                    include_validation_report: false,
                },
            )
            .expect("latest validation")
            .expect("latest validation row");
        assert_eq!(latest.summary.validation_id, Some(second_id));
        assert_eq!(latest.issues[0].message, "second validation issue");

        let list = store
            .list_recursive_live_output_validation_results(
                RecursiveLiveOutputValidationListFilter {
                    graph_id: Some(live.summary.graph_id),
                    include_issues: true,
                    limit: Some(10),
                    ..RecursiveLiveOutputValidationListFilter::default()
                },
            )
            .expect("list validations");
        let ids = list
            .iter()
            .map(|result| result.summary.validation_id.expect("validation id"))
            .collect::<Vec<_>>();
        assert_eq!(ids, vec![second_id, first_id]);
        assert_eq!(list[0].issues[0].message, "second validation issue");
        assert_eq!(list[1].issues[0].message, "first validation issue");

        let latest_issues = store
            .list_recursive_live_validation_issues(RecursiveLiveValidationIssueFilter {
                live_attempt_id: Some(live.summary.id),
                limit: Some(10),
                ..RecursiveLiveValidationIssueFilter::default()
            })
            .expect("latest validation issues");
        assert_eq!(latest_issues.len(), 1);
        assert_eq!(latest_issues[0].message, "second validation issue");

        let artifacts = store
            .load_recursive_live_attempt_artifacts(
                live.summary.id,
                RecursiveLiveAttemptArtifactReadOptions {
                    include_prompt: true,
                    include_raw_output: true,
                    include_normalized_output: true,
                    include_validation_report: true,
                    include_diff: true,
                    include_tests: true,
                    include_produced_artifacts: true,
                },
            )
            .expect("artifact readback")
            .expect("artifact readback row");
        assert_eq!(artifacts.raw_output_artifacts.len(), 2);
        assert_eq!(artifacts.validation_artifacts.len(), 2);
        assert_eq!(artifacts.produced_artifacts.len(), 2);
        assert_eq!(artifacts.test_artifacts.len(), 2);
        assert_eq!(artifacts.diff_artifacts.len(), 2);
    }

    #[test]
    fn recursive_dag_live_validation_issue_summary_malformed_json_is_clear() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let mut validation =
            validate_live_output_json_for_store(&store, &live, "{ invalid json", 1);
        validation.parser_source = Some(RecursiveLiveOutputParserSource::Inline {
            description: Some("malformed issue summary fixture".to_string()),
        });
        let result = store
            .commit_recursive_live_output_validation(commit_for_live(&live, None, validation))
            .expect("commit validation");
        let validation_id = result
            .validation_result
            .summary
            .validation_id
            .expect("validation id");

        store
            .conn
            .execute_batch("PRAGMA ignore_check_constraints = ON;")
            .expect("disable check constraints");
        store
            .conn
            .execute(
                "UPDATE recursive_live_output_validations
                 SET issue_summary_json = '{not-json'
                 WHERE id = ?1",
                params![validation_id.to_string()],
            )
            .expect("corrupt issue summary fixture");
        store
            .conn
            .execute_batch("PRAGMA ignore_check_constraints = OFF;")
            .expect("restore check constraints");

        let error = store
            .list_recursive_live_validation_issues(RecursiveLiveValidationIssueFilter {
                validation_id: Some(validation_id),
                ..RecursiveLiveValidationIssueFilter::default()
            })
            .expect_err("malformed issue JSON should error");
        assert_error_contains(
            error,
            "invalid recursive live output validation issue_summary_json",
        );
    }

