    #[test]
    fn recursive_dag_live_output_cancelled_requires_accepted_evidence() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let output = live_cancelled_output(&live, None, RecursiveCancellationScope::Run);
        let mut validation = validate_live_output_for_store(&store, &live, &output);
        assert_ne!(
            validation.summary.status,
            RecursiveLiveOutputValidationStatus::Valid
        );
        validation.summary.mapping_decision = Some(RecursiveLiveOutputMappingDecision::Cancelled);

        let error = store
            .commit_recursive_live_output_validation(commit_for_live(&live, None, validation))
            .expect_err("cancelled mapping without accepted evidence is rejected");
        assert_error_contains(error, "requires accepted validation");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);

        let live = create_attached_running_live_attempt(&store);
        let request = request_test_run_cancellation(&store, live.summary.scheduler_run_id);
        let output =
            live_cancelled_output(&live, Some(request.id), RecursiveCancellationScope::Run);
        let validation =
            validate_cancelled_live_output_for_store(&store, &live, &output, request.id);
        assert_eq!(
            validation.summary.status,
            RecursiveLiveOutputValidationStatus::Valid
        );
        let result = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect("commit accepted run cancellation");
        assert_eq!(
            result.live_attempt.summary.status,
            RecursiveLiveAttemptStatus::Interrupted
        );
        assert_eq!(
            result.recursive_attempt.status,
            RecursiveAttemptStatus::Interrupted
        );
        assert_eq!(result.task.status, RecursiveTaskLifecycleState::Ready);
    }

    #[test]
    fn recursive_dag_live_output_cancellation_wrong_graph_or_run_rejects_without_mutation() {
        let (_dir, store) = test_store();

        let live = create_attached_running_live_attempt(&store);
        let (other_graph_id, _) = create_graph(&store, 16);
        let other_run = start_test_run(&store, other_graph_id, 8);
        let wrong_graph_request = request_test_run_cancellation(&store, other_run.id);
        let output = live_cancelled_output(
            &live,
            Some(wrong_graph_request.id),
            RecursiveCancellationScope::Run,
        );
        let validation = validate_cancelled_live_output_for_store(
            &store,
            &live,
            &output,
            wrong_graph_request.id,
        );
        assert_eq!(
            validation.summary.status,
            RecursiveLiveOutputValidationStatus::Valid
        );
        let error = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect_err("wrong graph cancellation evidence rejects");
        assert_error_contains(error, "belongs to graph");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        assert_eq!(
            store
                .load_recursive_live_attempt(live.summary.id)
                .expect("load live")
                .expect("live")
                .summary
                .status,
            RecursiveLiveAttemptStatus::Running
        );

        let (graph_id, root_id) = create_graph(&store, 16);
        let original_run = start_test_run(&store, graph_id, 8);
        store
            .finish_recursive_scheduler_run(
                original_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish original run");
        let wrong_run = start_test_run(&store, graph_id, 8);
        let wrong_run_request = request_test_run_cancellation(&store, wrong_run.id);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let live = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id,
                root_id,
                original_run.id,
                attempt_id,
            ))
            .expect("create live attempt");
        let session_id = Uuid::new_v4();
        insert_session_for_live_attempt(
            &store,
            session_id,
            SessionProvider::Codex,
            Some("gpt-5-codex"),
        );
        let live = store
            .attach_recursive_live_attempt_session(live.summary.id, session_id)
            .expect("attach live session");
        let output = live_cancelled_output(
            &live,
            Some(wrong_run_request.id),
            RecursiveCancellationScope::Run,
        );
        let validation =
            validate_cancelled_live_output_for_store(&store, &live, &output, wrong_run_request.id);
        assert_eq!(
            validation.summary.status,
            RecursiveLiveOutputValidationStatus::Valid
        );
        let error = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect_err("wrong run cancellation evidence rejects");
        assert_error_contains(error, "does not target scheduler run");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        assert_eq!(
            recursive_attempt_for_live(&store, &live).status,
            RecursiveAttemptStatus::Running
        );
    }

