    #[test]
    fn recursive_dag_live_output_duplicate_commit_rejects_safely() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let output = live_success_output(&live);
        let validation = validate_live_output_for_store(&store, &live, &output);
        let commit = commit_for_live(&live, Some(output), validation);

        store
            .commit_recursive_live_output_validation(commit.clone())
            .expect("first commit");
        let artifact_count_after_first = artifact_count(&store, live.summary.graph_id);
        let error = store
            .commit_recursive_live_output_validation(commit)
            .expect_err("second commit rejects");
        assert_error_contains(error, "already committed");
        assert_eq!(
            artifact_count(&store, live.summary.graph_id),
            artifact_count_after_first
        );
        assert_eq!(validation_count(&store, live.summary.id), 1);
    }

    #[test]
    fn recursive_dag_live_output_commit_after_terminal_live_attempt_rejects_without_writes() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let output = live_success_output(&live);
        let validation = validate_live_output_for_store(&store, &live, &output);
        set_live_attempt_status_direct(
            &store,
            live.summary.id,
            RecursiveLiveAttemptStatus::Succeeded,
        );

        let error = store
            .commit_recursive_live_output_validation(commit_for_live(
                &live,
                Some(output),
                validation,
            ))
            .expect_err("terminal live attempt rejects stale commit");
        assert_error_contains(error, "is already succeeded");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        assert_eq!(
            recursive_attempt_for_live(&store, &live).status,
            RecursiveAttemptStatus::Running
        );
    }

