    #[test]
    fn recursive_dag_live_output_scheduler_event_failure_rolls_back_state_and_artifacts() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let output = live_success_output(&live);
        let validation = validate_live_output_for_store(&store, &live, &output);
        let mut commit = commit_for_live(&live, Some(output), validation);
        commit.scheduler_event = Some(RecursiveLiveOutputSchedulerEventCreate {
            event_type: " ".to_string(),
            message: Some("invalid event".to_string()),
            metadata: serde_json::json!({ "source": "test" }),
        });

        let error = store
            .commit_recursive_live_output_validation(commit)
            .expect_err("scheduler event failure rolls back");
        assert_error_contains(error, "event type must not be empty");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        assert_eq!(
            store
                .load_recursive_live_attempt(live.summary.id)
                .expect("load live")
                .expect("live")
                .summary
                .status,
            RecursiveLiveAttemptStatus::Running
        );
        assert_eq!(
            recursive_attempt_for_live(&store, &live).status,
            RecursiveAttemptStatus::Running
        );
        assert_eq!(
            scheduler_run_event_count(
                &store,
                live.summary.scheduler_run_id,
                "live_output_validation_committed",
            ),
            0
        );
    }

    #[test]
    fn recursive_dag_live_output_artifact_failure_rolls_back_partial_writes() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let output = live_success_output(&live);
        let validation = validate_live_output_for_store(&store, &live, &output);
        let mut commit = commit_for_live(&live, Some(output), validation);
        commit
            .produced_artifacts
            .push(RecursiveExecutionArtifactCreate {
                task_id: RecursiveTaskId(Uuid::new_v4()),
                attempt_id: Some(live.summary.attempt_id),
                kind: RecursiveExecutionArtifactKind::Inline,
                label: "live-produced-artifact:bad-owner".to_string(),
                content: Some("bad".to_string()),
                uri: None,
                metadata: serde_json::json!({ "test": true }),
            });

        let error = store
            .commit_recursive_live_output_validation(commit)
            .expect_err("artifact persistence failure rolls back");
        assert_error_contains(error, "recursive artifact task not found");
        assert_eq!(validation_count(&store, live.summary.id), 0);
        assert_eq!(artifact_count(&store, live.summary.graph_id), 0);
        let live_after = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load live")
            .expect("live");
        assert_eq!(
            live_after.summary.status,
            RecursiveLiveAttemptStatus::Running
        );
    }

