    #[test]
    fn recursive_dag_valid_decomposition_batch_commits() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let a = Uuid::new_v4();
        let b = Uuid::new_v4();

        let batch = store
            .insert_recursive_decomposition_batch(
                RecursiveTaskGraphId(graph_id),
                decomposition(root_id, vec![child(a, 20, vec![]), child(b, 20, vec![a])]),
            )
            .expect("decomposition commits");

        assert_eq!(batch.parent_task_id, RecursiveTaskId(root_id));
        assert_eq!(
            batch.child_task_ids,
            vec![RecursiveTaskId(a), RecursiveTaskId(b)]
        );
        assert_eq!(batch.edge_count, 3);
        let detail = store
            .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .unwrap()
            .expect("graph exists");
        assert_eq!(detail.nodes.len(), 3);
        assert_eq!(detail.edges.len(), 3);
        assert!(
            detail
                .nodes
                .iter()
                .find(|node| node.id == RecursiveTaskId(root_id))
                .expect("root")
                .decomposed_once
        );
    }

