    #[test]
    fn recursive_dag_ancestor_descendant_cap_rejects() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 2);
        let a = Uuid::new_v4();
        let b = Uuid::new_v4();
        let c = Uuid::new_v4();

        store
            .insert_recursive_decomposition_batch(
                RecursiveTaskGraphId(graph_id),
                decomposition(root_id, vec![child(a, 40, vec![]), child(b, 40, vec![])]),
            )
            .expect("root reaches cap");

        let error = store
            .insert_recursive_decomposition_batch(
                RecursiveTaskGraphId(graph_id),
                decomposition(a, vec![child(c, 10, vec![])]),
            )
            .expect_err("ancestor cap rejects");
        assert!(error.to_string().contains("descendant count"));

        let detail = store
            .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .unwrap()
            .expect("graph exists");
        assert_eq!(detail.nodes.len(), 3);
        assert!(
            !detail
                .nodes
                .iter()
                .any(|node| node.id == RecursiveTaskId(c))
        );
    }

