    #[test]
    fn recursive_dag_attempt_start_and_finish_records_correctly() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let attempt_id = RecursiveAttemptId(Uuid::new_v4());

        let started = store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Execute,
                attempt_id,
            )
            .expect("start attempt");
        assert_eq!(started.status, RecursiveAttemptStatus::Running);
        assert_eq!(started.attempt_no, 1);
        assert_eq!(started.retry_count, 0);
        assert!(started.finished_at.is_none());

        let finished = store
            .record_recursive_attempt_finish(
                RecursiveTaskGraphId(graph_id),
                attempt_id,
                RecursiveAttemptStatus::Succeeded,
                None,
                None,
                Some(RecursiveTaskLifecycleState::Succeeded),
                Some("done".to_string()),
            )
            .expect("finish attempt");
        assert_eq!(finished.status, RecursiveAttemptStatus::Succeeded);
        assert!(finished.finished_at.is_some());
        let task = store
            .load_recursive_task(RecursiveTaskGraphId(graph_id), RecursiveTaskId(root_id))
            .unwrap()
            .expect("task");
        assert_eq!(task.status, RecursiveTaskLifecycleState::Succeeded);
        assert_eq!(task.blocked_reason, None);
    }

    #[test]
    fn recursive_dag_scheduler_run_store_api_round_trips_transactionally() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);

        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");
        assert_eq!(run.status, RecursiveSchedulerRunStatus::Running);
        assert_eq!(run.step_count, 0);
        assert_eq!(run.max_steps, 8);
        assert_eq!(run.executor_mode, RecursiveExecutionMode::Fake);
        assert_eq!(run.operator.as_deref(), Some("test"));
        assert_eq!(
            run.lease_owner.as_deref(),
            Some(DEFAULT_RECURSIVE_SCHEDULER_LEASE_OWNER)
        );
        assert!(run.lease_token.is_some());
        assert!(run.lease_heartbeat_at.is_some());
        assert!(run.lease_expires_at.is_some());

        let run = store
            .update_recursive_scheduler_run_step_count(run.id, 1)
            .expect("update step count");
        assert_eq!(run.step_count, 1);

        let error = store
            .finish_recursive_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::GraphTerminal,
                1,
                Some(999_999),
            )
            .expect_err("unknown report artifact rejects");
        assert!(error.to_string().contains("report artifact not found"));
        let still_running = store
            .load_recursive_scheduler_run(run.id)
            .expect("load run")
            .expect("run exists");
        assert_eq!(still_running.status, RecursiveSchedulerRunStatus::Running);
        assert_eq!(still_running.step_count, 1);
        assert!(still_running.completed_at.is_none());

        let completed = store
            .finish_recursive_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::GraphTerminal,
                1,
                None,
            )
            .expect("finish scheduler run");
        assert_eq!(completed.status, RecursiveSchedulerRunStatus::Completed);
        assert_eq!(
            completed.stop_reason,
            Some(RecursiveSchedulerStopReason::GraphTerminal)
        );
        assert!(completed.completed_at.is_some());

        let runs = store
            .list_recursive_scheduler_runs_for_graph(RecursiveTaskGraphId(graph_id))
            .expect("list runs");
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].id, completed.id);
    }

    #[test]
    fn recursive_dag_live_scheduler_v65_schema_admits_live_modes_without_reachability() {
        let (_dir, store) = test_store();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("user_version");
        assert_eq!(version, LATEST_SCHEMA_VERSION);

        for (table, needle) in [
            (
                "recursive_task_graphs",
                "execution_mode IN ('fake', 'live_session')",
            ),
            (
                "recursive_scheduler_runs",
                "executor_mode IN ('fake', 'live_session')",
            ),
            (
                "recursive_task_attempts",
                "executor_kind IN ('fake', 'live_session')",
            ),
        ] {
            let sql: String = store
                .conn
                .query_row(
                    "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?1",
                    [table],
                    |row| row.get(0),
                )
                .expect("table sql");
            assert!(
                sql.contains(needle),
                "{table} schema should contain {needle:?}, got {sql}"
            );
        }

        let (graph_id, root_id) = create_live_graph(&store, 16);
        let graph = store
            .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .expect("load live graph")
            .expect("live graph");
        assert_eq!(
            graph.graph.execution_mode,
            RecursiveExecutionMode::LiveSession
        );

        let run = start_live_test_run(&store, graph_id, 2);
        assert_eq!(run.executor_mode, RecursiveExecutionMode::LiveSession);
        let attempt_id = create_live_running_attempt(&store, graph_id, root_id);
        let attempts = store
            .load_recursive_task_attempts(RecursiveTaskGraphId(graph_id))
            .expect("load attempts");
        assert_eq!(attempts[0].id, attempt_id);
        assert_eq!(
            attempts[0].executor_kind,
            RecursiveExecutionMode::LiveSession
        );

        let error = store
            .conn
            .execute(
                "UPDATE recursive_task_graphs SET execution_mode = 'live' WHERE id = ?1",
                [graph_id.to_string()],
            )
            .expect_err("invalid mode still rejected");
        assert!(error.to_string().contains("CHECK"));
    }

    #[test]
    fn recursive_dag_live_scheduler_store_primitives_round_trip() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_live_graph(&store, 16);
        let policy_snapshot = serde_json::json!({
            "approval_mode": "manual",
            "tool_policy": {"allowed_tools": ["read"], "denied_tools": ["write"]},
            "budgets": {"max_wall_time_ms": 60000, "token_budget": 1000}
        });
        let run = store
            .start_recursive_live_scheduler_run(RecursiveLiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 4,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("operator".to_string()),
                idempotency_key: Some("live-run-key".to_string()),
                request_fingerprint: Some("live-run-fingerprint".to_string()),
                policy_snapshot: policy_snapshot.clone(),
            })
            .expect("start live scheduler run");
        assert_eq!(run.executor_mode, RecursiveExecutionMode::LiveSession);
        assert_eq!(run.status, RecursiveSchedulerRunStatus::Running);
        let metadata = store
            .load_recursive_scheduler_run_live_metadata(run.id)
            .expect("load live run metadata")
            .expect("live run metadata");
        assert_eq!(metadata.run_id, run.id);
        assert_eq!(metadata.idempotency_key.as_deref(), Some("live-run-key"));
        assert_eq!(
            metadata.request_fingerprint.as_deref(),
            Some("live-run-fingerprint")
        );
        assert_eq!(metadata.policy_snapshot, policy_snapshot);

        let attempt_id = create_live_running_attempt(&store, graph_id, root_id);
        let mut create = live_attempt_create(graph_id, root_id, run.id, attempt_id);
        create.id = RecursiveLiveAttemptId::new();
        create.provider = Some(SessionProvider::Codex);
        create.model = Some("gpt-5-codex".to_string());
        let first = store
            .create_or_load_recursive_live_attempt(create.clone())
            .expect("create live attempt idempotently");
        assert!(first.inserted);
        assert_eq!(first.live_attempt.summary.attempt_id, attempt_id);
        assert_eq!(
            first.live_attempt.summary.execution_mode,
            RecursiveExecutionMode::LiveSession
        );
        assert_eq!(session_count(&store), 0);

        let completed = store
            .finish_recursive_live_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish live scheduler run");
        assert_eq!(completed.status, RecursiveSchedulerRunStatus::Completed);
        assert_eq!(completed.executor_mode, RecursiveExecutionMode::LiveSession);
    }

