    #[test]
    fn recursive_dag_live_scheduler_fake_terminal_apis_reject_live_runs() {
        let (_dir, store) = test_store();
        let (live_graph_id, _) = create_live_graph(&store, 16);
        let live_run = start_live_test_run(&store, live_graph_id, 8);

        let error = store
            .update_recursive_scheduler_run_step_count(live_run.id, 1)
            .expect_err("fake progress API rejects live run");
        assert_error_contains(error, "does not match expected fake");

        let error = store
            .finish_recursive_scheduler_run(
                live_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect_err("fake finish API rejects live run");
        assert_error_contains(error, "does not match expected fake");

        let error = store
            .fail_recursive_scheduler_run(live_run.id, 0, "executor failed".to_string())
            .expect_err("fake fail API rejects live run");
        assert_error_contains(error, "does not match expected fake");

        let error = store
            .cancel_recursive_scheduler_run(
                live_run.id,
                RecursiveCancellationRequestId::new(),
                0,
                None,
            )
            .expect_err("fake cancel API rejects live run before request mutation");
        assert_error_contains(error, "does not match expected fake");

        let completed = store
            .finish_recursive_live_scheduler_run(
                live_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("live finish API accepts live run");
        assert_eq!(completed.status, RecursiveSchedulerRunStatus::Completed);
        assert_eq!(completed.executor_mode, RecursiveExecutionMode::LiveSession);

        let (fake_graph_id, _) = create_graph(&store, 16);
        let fake_run = start_test_run(&store, fake_graph_id, 8);
        let error = store
            .finish_recursive_live_scheduler_run(
                fake_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect_err("live finish API rejects fake run");
        assert_error_contains(error, "does not match expected live_session");

        let completed = store
            .finish_recursive_scheduler_run(
                fake_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("fake finish API accepts fake run");
        assert_eq!(completed.executor_mode, RecursiveExecutionMode::Fake);
    }

