    #[test]
    fn recursive_dag_live_correlation_attaches_session_and_rejects_duplicate_session() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let run = start_test_run(&store, graph_id, 8);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let create = live_attempt_create(graph_id, root_id, run.id, attempt_id);
        let live = store
            .create_recursive_live_attempt_placeholder(create.clone())
            .expect("create live correlation");

        let session_id = Uuid::new_v4();
        insert_session_for_live_attempt(
            &store,
            session_id,
            SessionProvider::Harness,
            Some("claude-sonnet-5"),
        );
        let attached = store
            .attach_recursive_live_attempt_session(live.summary.id, session_id)
            .expect("attach session");
        assert_eq!(attached.summary.session_id, Some(session_id));
        assert_eq!(attached.summary.status, RecursiveLiveAttemptStatus::Running);
        assert_eq!(attached.summary.provider, Some(SessionProvider::Harness));
        assert_eq!(attached.summary.model.as_deref(), Some("claude-sonnet-5"));
        assert_eq!(
            attached.summary.sandbox_kind,
            Some(SandboxKind::GitWorktree)
        );
        assert_eq!(
            attached.summary.sandbox_root,
            Some(PathBuf::from("/tmp/rsi-live-worktree"))
        );
        assert!(attached.summary.launched_at.is_some());

        let by_session = store
            .load_recursive_live_attempt_by_session_id(session_id)
            .expect("load by session")
            .expect("live attempt by session");
        assert_eq!(by_session.summary.id, live.summary.id);

        let second_attempt_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Integrate,
                second_attempt_id,
            )
            .expect("start second attempt");
        let mut second = live_attempt_create(graph_id, root_id, run.id, second_attempt_id);
        second.id = RecursiveLiveAttemptId(Uuid::new_v4());
        let second = store
            .create_recursive_live_attempt_placeholder(second)
            .expect("create second live correlation");
        let error = store
            .attach_recursive_live_attempt_session(second.summary.id, session_id)
            .expect_err("duplicate session rejected");
        assert_error_contains(error, "already linked");
    }

