    #[test]
    fn recursive_dag_live_status_round_trips_and_invalid_strings_reject() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let run = start_test_run(&store, graph_id, 8);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let create = live_attempt_create(graph_id, root_id, run.id, attempt_id);
        let live = store
            .create_recursive_live_attempt_placeholder(create)
            .expect("create live correlation");

        for status in [
            RecursiveLiveAttemptStatus::Created,
            RecursiveLiveAttemptStatus::Launching,
            RecursiveLiveAttemptStatus::Running,
            RecursiveLiveAttemptStatus::WaitingApproval,
            RecursiveLiveAttemptStatus::Succeeded,
            RecursiveLiveAttemptStatus::Decomposed,
            RecursiveLiveAttemptStatus::Failed,
            RecursiveLiveAttemptStatus::Blocked,
            RecursiveLiveAttemptStatus::Cancelled,
            RecursiveLiveAttemptStatus::Interrupted,
            RecursiveLiveAttemptStatus::Lost,
            RecursiveLiveAttemptStatus::RecoveryPending,
        ] {
            assert_eq!(
                parse_live_attempt_status(live_attempt_status_to_str(status)).unwrap(),
                status
            );
        }
        assert!(parse_live_attempt_status("invalid").is_err());
        for status in [
            RecursiveLiveInterruptStatus::Requested,
            RecursiveLiveInterruptStatus::Sent,
            RecursiveLiveInterruptStatus::Interrupted,
            RecursiveLiveInterruptStatus::Failed,
            RecursiveLiveInterruptStatus::Rejected,
            RecursiveLiveInterruptStatus::Ignored,
        ] {
            assert_eq!(
                parse_live_interrupt_status(live_interrupt_status_to_str(status)).unwrap(),
                status
            );
        }
        assert!(parse_live_interrupt_status("invalid").is_err());
        assert_eq!(
            parse_execution_mode(execution_mode_to_str(RecursiveExecutionMode::LiveSession))
                .unwrap(),
            RecursiveExecutionMode::LiveSession
        );

        let pending = store
            .update_recursive_live_attempt_status(
                live.summary.id,
                RecursiveLiveAttemptStatusUpdate {
                    status: RecursiveLiveAttemptStatus::RecoveryPending,
                    failure_reason: None,
                    interruption_reason: None,
                    cancellation_reason: None,
                    recovery_reason: Some("daemon restart".to_string()),
                    error: None,
                },
            )
            .expect("mark recovery pending");
        assert_eq!(
            pending.summary.status,
            RecursiveLiveAttemptStatus::RecoveryPending
        );
        assert_eq!(
            pending.summary.recovery_status,
            RecursiveLiveRecoveryStatus::Pending
        );
        assert!(pending.recovery_checked_at.is_some());

        let failed = store
            .update_recursive_live_attempt_status(
                live.summary.id,
                RecursiveLiveAttemptStatusUpdate {
                    status: RecursiveLiveAttemptStatus::Failed,
                    failure_reason: Some("output contract missing".to_string()),
                    interruption_reason: None,
                    cancellation_reason: None,
                    recovery_reason: None,
                    error: Some("validation failed".to_string()),
                },
            )
            .expect("mark failed");
        assert_eq!(failed.summary.status, RecursiveLiveAttemptStatus::Failed);
        assert!(failed.summary.completed_at.is_some());
        assert_eq!(
            failed.failure_reason.as_deref(),
            Some("output contract missing")
        );
        assert_eq!(failed.error.as_deref(), Some("validation failed"));

        let error = store
            .conn
            .execute(
                "UPDATE recursive_live_attempts SET status = 'bogus' WHERE id = ?1",
                params![live.summary.id.to_string()],
            )
            .expect_err("invalid status rejected by schema");
        assert!(error.to_string().contains("CHECK"));
    }

