    #[test]
    fn recursive_dag_live_interrupt_duplicate_after_failed_returns_existing_result() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let run = start_test_run(&store, graph_id, 8);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let live = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id, root_id, run.id, attempt_id,
            ))
            .expect("create live attempt");
        let session_id = Uuid::new_v4();
        insert_session_for_live_attempt(
            &store,
            session_id,
            SessionProvider::Codex,
            Some("gpt-5-codex"),
        );
        let live = store
            .attach_recursive_live_attempt_session(live.summary.id, session_id)
            .expect("attach live session");
        let cancellation = request_test_run_cancellation(&store, run.id);
        let interrupt_id = RecursiveLiveInterruptId(Uuid::new_v4());
        store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: interrupt_id,
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(cancellation.id),
                reason: "operator interrupted live attempt".to_string(),
            })
            .expect("request interrupt");
        store
            .mark_recursive_live_interrupt_sent(interrupt_id)
            .expect("mark sent");
        let failed = store
            .mark_recursive_live_interrupt_failed(
                interrupt_id,
                "interrupt boundary failed".to_string(),
            )
            .expect("mark failed");

        let duplicate = store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: RecursiveLiveInterruptId(Uuid::new_v4()),
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(cancellation.id),
                reason: "duplicate interrupt".to_string(),
            })
            .expect("duplicate after failure");
        let failed_again = store
            .mark_recursive_live_interrupt_failed(
                interrupt_id,
                "second failure should not overwrite".to_string(),
            )
            .expect("failed terminal state is idempotent");

        assert!(!duplicate.inserted);
        assert_eq!(duplicate.interrupt, failed);
        assert_eq!(failed_again, failed);
        assert_eq!(
            failed_again.failure_reason.as_deref(),
            Some("interrupt boundary failed")
        );
        let live = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load live")
            .expect("live attempt");
        assert_eq!(live.summary.status, RecursiveLiveAttemptStatus::Running);
    }

    #[test]
    fn recursive_dag_live_interrupt_rejects_invalid_cancellation_links() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let run = start_test_run(&store, graph_id, 8);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let live = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id, root_id, run.id, attempt_id,
            ))
            .expect("create live attempt");
        let session_id = Uuid::new_v4();
        insert_session_for_live_attempt(
            &store,
            session_id,
            SessionProvider::Codex,
            Some("gpt-5-codex"),
        );
        let live = store
            .attach_recursive_live_attempt_session(live.summary.id, session_id)
            .expect("attach live session");

        let (other_graph_id, _) = create_graph(&store, 16);
        let other_run = start_test_run(&store, other_graph_id, 8);
        let wrong_graph_cancellation = request_test_run_cancellation(&store, other_run.id);
        let error = store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: RecursiveLiveInterruptId(Uuid::new_v4()),
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(wrong_graph_cancellation.id),
                reason: "wrong graph cancellation".to_string(),
            })
            .expect_err("wrong graph cancellation rejects");
        assert_error_contains(error, "belongs to graph");

        store
            .finish_recursive_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish original run");
        let wrong_run = start_test_run(&store, graph_id, 8);
        let wrong_run_cancellation = request_test_run_cancellation(&store, wrong_run.id);
        let error = store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: RecursiveLiveInterruptId(Uuid::new_v4()),
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(wrong_run_cancellation.id),
                reason: "wrong run cancellation".to_string(),
            })
            .expect_err("wrong run cancellation rejects");
        assert_error_contains(error, "does not target scheduler run");

        let task_cancellation = store
            .request_recursive_task_cancellation(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveCancellationRequestCreate {
                    reason: "task-scoped cancellation".to_string(),
                    requested_by: Some("test".to_string()),
                    source: RecursiveCancellationRequestSource::TestHarness,
                },
            )
            .expect("request task cancellation");
        let error = store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: RecursiveLiveInterruptId(Uuid::new_v4()),
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(task_cancellation.id),
                reason: "task cancellation must not execute".to_string(),
            })
            .expect_err("task-scoped cancellation rejects");
        assert_error_contains(error, "task-scoped cancellation");

        assert!(
            store
                .list_recursive_live_interrupts_for_live_attempt(live.summary.id)
                .expect("list interrupts")
                .is_empty()
        );
        let task_cancellation = store
            .load_recursive_cancellation_request(task_cancellation.id)
            .expect("load task cancellation")
            .expect("task cancellation");
        assert_eq!(
            task_cancellation.status,
            RecursiveCancellationRequestStatus::Requested
        );
    }

