        assert_eq!(loaded.live_attempt_id, live_attempt_id);
        assert_eq!(loaded.heartbeat_owner.as_deref(), Some(owner.as_str()));
        assert_eq!(loaded.heartbeat_token.as_deref(), Some(token.as_str()));
