    #[test]
    fn recursive_dag_live_recovery_terminal_attempt_is_idempotent() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let session_id = live.summary.session_id.expect("attached session");
        set_session_status_for_live_attempt(&store, session_id, SessionStatus::Completed);
        store
            .recover_recursive_live_attempt(live.summary.id)
            .expect("first recovery");
        let after_first = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load first")
            .expect("first");

        let second = store
            .recover_recursive_live_attempt(live.summary.id)
            .expect("second recovery");
        let after_second = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load second")
            .expect("second");

        assert_eq!(second.status, RecursiveLiveAttemptRecoveryStatus::Unchanged);
        assert_eq!(after_first.summary.status, after_second.summary.status);
        assert_eq!(
            after_first.summary.completed_at,
            after_second.summary.completed_at
        );
        assert_eq!(
            after_first.recovery_checked_at,
            after_second.recovery_checked_at
        );
        assert_eq!(after_first.recovered_at, after_second.recovered_at);
    }

    #[test]
