    #[test]
    fn recursive_dag_live_recovery_malformed_attempt_correlation_is_visible() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let child_id = Uuid::new_v4();
        store
            .insert_recursive_decomposition_batch(
                RecursiveTaskGraphId(graph_id),
                decomposition(root_id, vec![child(child_id, 8, vec![])]),
            )
            .expect("add child task");
        let run = start_test_run(&store, graph_id, 8);
        let attempt_id = create_running_attempt(&store, graph_id, root_id);
        let live = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id, root_id, run.id, attempt_id,
            ))
            .expect("create live attempt");
        store
            .conn
            .execute(
                "UPDATE recursive_live_attempts
                 SET task_id = ?1, updated_at = ?2
                 WHERE id = ?3",
                params![child_id.to_string(), now(), live.summary.id.to_string()],
            )
            .expect("corrupt live attempt task correlation");

        let result = store
            .recover_recursive_live_attempt(live.summary.id)
            .expect("recover malformed live attempt");

        assert_eq!(
            result.status,
            RecursiveLiveAttemptRecoveryStatus::MalformedInconsistent
        );
        assert!(
            result
                .reason
                .as_deref()
                .unwrap_or_default()
                .contains("does not match recursive attempt")
        );
        let recovered = store
            .load_recursive_live_attempt(live.summary.id)
            .expect("load recovered live")
            .expect("recovered live");
        assert_eq!(recovered.summary.status, RecursiveLiveAttemptStatus::Failed);
        assert_eq!(
            recovered.summary.recovery_status,
            RecursiveLiveRecoveryStatus::Quarantined
        );
        assert!(
            recovered
                .error
                .as_deref()
                .unwrap_or_default()
                .contains("does not match recursive attempt")
        );
    }

    #[test]
    fn recursive_dag_live_recovery_multiple_attempts_are_deterministic() {
        let (_dir, store) = test_store();
        let first = create_launching_live_attempt(&store);
        let second = create_launching_live_attempt(&store);
        let third = create_launching_live_attempt(&store);
        for (live, created_at) in [
            (&first, "2000-01-01T00:00:03.000000000Z"),
            (&second, "2000-01-01T00:00:01.000000000Z"),
            (&third, "2000-01-01T00:00:02.000000000Z"),
        ] {
            store
                .conn
                .execute(
                    "UPDATE recursive_live_attempts
                     SET created_at = ?1, updated_at = ?1
                     WHERE id = ?2",
                    params![created_at, live.summary.id.to_string()],
                )
                .expect("set deterministic created_at");
        }

        let report = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(10))
            .expect("recover attempts");

        let ids = report
            .results
            .iter()
            .map(|result| result.live_attempt_id)
            .collect::<Vec<_>>();
        assert_eq!(
            ids,
            vec![second.summary.id, third.summary.id, first.summary.id]
        );
        assert_eq!(report.checked, 3);
        assert_eq!(report.lost, 3);
        assert_eq!(report.deferred, 0);
    }

    #[test]
    fn recursive_dag_live_recovery_budget_resume_is_deterministic() {
        let (_dir, store) = test_store();
        let first = create_launching_live_attempt(&store);
        let second = create_launching_live_attempt(&store);
        let third = create_launching_live_attempt(&store);
        for (live, created_at) in [
            (&first, "2000-01-01T00:00:01.000000000Z"),
            (&second, "2000-01-01T00:00:02.000000000Z"),
            (&third, "2000-01-01T00:00:03.000000000Z"),
        ] {
            store
                .conn
                .execute(
                    "UPDATE recursive_live_attempts
                     SET created_at = ?1, updated_at = ?1
                     WHERE id = ?2",
                    params![created_at, live.summary.id.to_string()],
                )
                .expect("set deterministic created_at");
        }

        let first_pass = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(1))
            .expect("first pass");
        let second_pass = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(1))
            .expect("second pass");
        let third_pass = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(1))
            .expect("third pass");

        assert_eq!(first_pass.results[0].live_attempt_id, first.summary.id);
        assert_eq!(second_pass.results[0].live_attempt_id, second.summary.id);
        assert_eq!(third_pass.results[0].live_attempt_id, third.summary.id);
        assert_eq!(first_pass.deferred, 2);
        assert_eq!(second_pass.deferred, 1);
        assert_eq!(third_pass.deferred, 0);
        assert_eq!(first_pass.lost, 1);
        assert_eq!(second_pass.lost, 1);
        assert_eq!(third_pass.lost, 1);
        let final_pass = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(10))
            .expect("final empty pass");
        assert_eq!(final_pass.checked, 0);
        assert!(final_pass.results.is_empty());
    }

    #[test]
    fn recursive_dag_live_recovery_budget_defers_without_mutating_beyond_budget() {
        let (_dir, store) = test_store();
        let first = create_launching_live_attempt(&store);
        let second = create_launching_live_attempt(&store);

        let report = store
            .recover_recursive_live_attempts_with_budget(live_recovery_budget(1))
            .expect("budgeted recovery");

        assert_eq!(report.checked, 1);
        assert_eq!(report.deferred, 1);
        assert_eq!(
            report.stop_reason,
            Some(RecursiveRecoveryStopReason::MaxGraphs)
        );
        let first_after = store
            .load_recursive_live_attempt(first.summary.id)
            .expect("load first")
            .expect("first");
        let second_after = store
            .load_recursive_live_attempt(second.summary.id)
            .expect("load second")
            .expect("second");
        assert_eq!(first_after.summary.status, RecursiveLiveAttemptStatus::Lost);
        assert_eq!(
            second_after.summary.status,
            RecursiveLiveAttemptStatus::Launching
        );
    }

    #[test]
    fn recursive_dag_live_recovery_source_has_no_launch_interrupt_or_model_calls() {
        let source = include_str!("recursive_dag.rs");
        let start = source
            .find("fn recover_recursive_live_attempt_tx")
            .expect("recovery function");
        let end = source[start..]
            .find("fn load_recursive_live_interrupt_tx")
            .map(|offset| start + offset)
            .expect("live interrupt loader follows recovery");
        let recovery_source = &source[start..end];
        for forbidden in [
            "launch_session",
            "interrupt_session",
            "launch_recursive_dag_session",
            "interrupt_recursive_dag_session",
            "OpenAiClient",
            "ClaudeClient",
            "CodexClient",
            "AgyClient",
            "Command::new",
            "tokio::process",
            "std::process",
        ] {
            assert!(
                !recovery_source.contains(forbidden),
                "live recovery must not reference {forbidden}"
            );
        }
    }

