    #[test]
    fn recursive_dag_live_interrupt_pending_can_heartbeat_and_interrupted_rejects() {
        let (_dir, store) = test_store();
        let live = create_attached_running_live_attempt(&store);
        let acquired = start_live_attempt_heartbeat(&store, live.summary.id);
        let token = acquired.heartbeat_token.clone().expect("heartbeat token");
        let cancellation = request_test_run_cancellation(&store, live.summary.scheduler_run_id);

        let requested = store
            .request_recursive_live_interrupt(RecursiveLiveInterruptCreate {
                id: RecursiveLiveInterruptId::new(),
                live_attempt_id: live.summary.id,
                cancellation_request_id: Some(cancellation.id),
                reason: "operator requested stop".to_string(),
            })
            .expect("request live interrupt");
        assert!(requested.inserted);
        assert_eq!(
            requested.interrupt.status,
            RecursiveLiveInterruptStatus::Requested
        );

        let renewed = store
            .heartbeat_recursive_live_attempt(RecursiveLiveAttemptHeartbeatRenew {
                live_attempt_id: live.summary.id,
                heartbeat_token: token.clone(),
                heartbeat_ttl_seconds: 60,
            })
            .expect("heartbeat while interrupt is pending");
        assert_eq!(
            renewed.heartbeat_status,
            RecursiveLiveAttemptHeartbeatStatus::Active
        );

        let sent = store
            .mark_recursive_live_interrupt_sent(requested.interrupt.id)
            .expect("mark interrupt sent");
        assert_eq!(sent.status, RecursiveLiveInterruptStatus::Sent);

        store
            .mark_recursive_live_interrupt_interrupted(sent.id)
            .expect("mark interrupted");
        let error = store
            .heartbeat_recursive_live_attempt(RecursiveLiveAttemptHeartbeatRenew {
                live_attempt_id: live.summary.id,
                heartbeat_token: token,
                heartbeat_ttl_seconds: 60,
            })
            .expect_err("interrupted heartbeat rejects");

        assert_error_contains(error, "terminal recursive live attempt");
        let state = store
            .load_recursive_live_attempt_heartbeat(live.summary.id)
            .expect("load heartbeat")
            .expect("heartbeat state");
        assert_eq!(
            state.live_attempt_status,
            RecursiveLiveAttemptStatus::Interrupted
        );
        assert_eq!(
            state.heartbeat_status,
            RecursiveLiveAttemptHeartbeatStatus::Released
        );
    }

    #[test]
    fn recursive_dag_live_list_by_graph_includes_mixed_statuses() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let child_id = Uuid::new_v4();
        store
            .insert_recursive_decomposition_batch(
                RecursiveTaskGraphId(graph_id),
                decomposition(root_id, vec![child(child_id, 20, vec![])]),
            )
            .expect("add child task");
        let run = start_test_run(&store, graph_id, 8);

        let root_execute_id = create_running_attempt(&store, graph_id, root_id);
        let root_execute = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id,
                root_id,
                run.id,
                root_execute_id,
            ))
            .expect("create root execute live attempt");
        let root_integrate_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Integrate,
                root_integrate_id,
            )
            .expect("start root integrate attempt");
        let root_integrate = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id,
                root_id,
                run.id,
                root_integrate_id,
            ))
            .expect("create root integrate live attempt");
        let child_execute_id = create_running_attempt(&store, graph_id, child_id);
        let child_execute = store
            .create_recursive_live_attempt_placeholder(live_attempt_create(
                graph_id,
                child_id,
                run.id,
                child_execute_id,
            ))
            .expect("create child execute live attempt");

        store
            .update_recursive_live_attempt_status(
                root_execute.summary.id,
                RecursiveLiveAttemptStatusUpdate {
                    status: RecursiveLiveAttemptStatus::Running,
                    failure_reason: None,
                    interruption_reason: None,
                    cancellation_reason: None,
                    recovery_reason: None,
                    error: None,
                },
            )
            .expect("mark running");
        store
            .update_recursive_live_attempt_status(
                root_integrate.summary.id,
                RecursiveLiveAttemptStatusUpdate {
                    status: RecursiveLiveAttemptStatus::RecoveryPending,
                    failure_reason: None,
                    interruption_reason: None,
                    cancellation_reason: None,
                    recovery_reason: Some("daemon restart".to_string()),
                    error: None,
                },
            )
            .expect("mark recovery pending");
        store
            .update_recursive_live_attempt_status(
                child_execute.summary.id,
                RecursiveLiveAttemptStatusUpdate {
                    status: RecursiveLiveAttemptStatus::Failed,
                    failure_reason: Some("tests failed".to_string()),
                    interruption_reason: None,
                    cancellation_reason: None,
                    recovery_reason: None,
                    error: None,
                },
            )
            .expect("mark failed");

        let attempts = store
            .list_recursive_live_attempts_for_graph(RecursiveTaskGraphId(graph_id))
            .expect("list live attempts");
        assert_eq!(attempts.len(), 3);
        assert!(
            attempts
                .iter()
                .any(|attempt| attempt.summary.status == RecursiveLiveAttemptStatus::Running)
        );
        assert!(
            attempts.iter().any(
                |attempt| attempt.summary.status == RecursiveLiveAttemptStatus::RecoveryPending
            )
        );
        assert!(
            attempts
                .iter()
                .any(|attempt| attempt.summary.status == RecursiveLiveAttemptStatus::Failed)
        );
    }

