    #[test]
    fn recursive_dag_live_migration_reopens_existing_recursive_rows_idempotently() {
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("test.db");
        let (graph_id, root_id, run_id, attempt_id) = {
            let store = Store::open(&db_path).expect("open store");
            let (graph_id, root_id) = create_graph(&store, 16);
            let run = start_test_run(&store, graph_id, 8);
            let attempt_id = create_running_attempt(&store, graph_id, root_id);
            // Preserve V91's exact-predecessor guarantee: cross its guarded
            // V90 boundary before constructing the intentionally older schema.
            crate::store::tests::h1_restore_v90_fixture(&store.conn);
            store
                .conn
                .execute("DROP TABLE recursive_live_attempts", [])
                .expect("drop V55 table");
            // Rewind version AND schema together (issue #26).
            crate::store::tests::rewind_store_to_schema_version(&store.conn, 54);
            (graph_id, root_id, run.id, attempt_id)
        };

        {
            let migrated = Store::open(&db_path).expect("migrate to latest");
            let version: i32 = migrated
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get(0))
                .expect("user_version");
            assert_eq!(version, LATEST_SCHEMA_VERSION);
            crate::store::tests::assert_post_v77_chain_replayed(&migrated.conn);
            migrated
                .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
                .expect("load graph")
                .expect("graph exists");
            migrated
                .load_recursive_scheduler_run(run_id)
                .expect("load run")
                .expect("run exists");
            let detail = migrated
                .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
                .expect("load graph")
                .expect("graph exists");
            assert!(
                detail
                    .nodes
                    .iter()
                    .any(|node| node.id == RecursiveTaskId(root_id))
            );
            assert!(
                detail
                    .attempts
                    .iter()
                    .any(|attempt| attempt.id == attempt_id)
            );
            assert!(
                migrated
                    .list_recursive_live_attempts_for_graph(RecursiveTaskGraphId(graph_id))
                    .expect("list live attempts")
                    .is_empty()
            );
        }

        let reopened = Store::open(&db_path).expect("reopen migrated store");
        let version: i32 = reopened
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("user_version");
        assert_eq!(version, LATEST_SCHEMA_VERSION);
        assert!(
            reopened
                .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
                .expect("load graph")
                .is_some()
        );
    }

