    #[test]
    fn recursive_dag_scheduler_lease_rejects_active_run_for_same_graph() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");

        let error = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect_err("same-graph active scheduler run should reject");
        assert_error_contains(error, "already has active scheduler run");

        store
            .finish_recursive_scheduler_run(
                run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish first run");
        store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("terminal prior run does not hold lease");
    }

    #[test]
    fn recursive_dag_scheduler_stale_lease_reclaim_allows_new_run() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");

        expire_scheduler_run_lease_direct(&store, run.id);

        let reclaimed = store
            .reclaim_expired_recursive_scheduler_runs()
            .expect("reclaim expired leases");
        assert_eq!(reclaimed.len(), 1);
        assert_eq!(reclaimed[0].id, run.id);
        assert_eq!(
            reclaimed[0].status,
            RecursiveSchedulerRunStatus::LeaseExpired
        );
        assert_eq!(
            reclaimed[0].stop_reason,
            Some(RecursiveSchedulerStopReason::LeaseExpired)
        );
        assert!(reclaimed[0].completed_at.is_some());
        assert_eq!(
            scheduler_run_event_count(&store, run.id, "lease_expired"),
            1
        );

        let next = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("reclaimed run releases graph lease");
        assert_ne!(next.id, run.id);
    }

