    #[test]
    fn recursive_dag_scheduler_terminal_run_paths_release_graph_lease() {
        let (_dir, store) = test_store();
        let (finish_graph_id, _) = create_graph(&store, 16);
        let finish_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(finish_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start finish run");
        store
            .finish_recursive_scheduler_run(
                finish_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish run");
        let replacement_finish_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(finish_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("finished run releases graph lease");
        store
            .finish_recursive_scheduler_run(
                replacement_finish_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish replacement run");

        let (fail_graph_id, _) = create_graph(&store, 16);
        let fail_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(fail_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start fail run");
        store
            .fail_recursive_scheduler_run(fail_run.id, 0, "executor failed".to_string())
            .expect("fail run");
        let replacement_fail_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(fail_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("failed run releases graph lease");
        store
            .finish_recursive_scheduler_run(
                replacement_fail_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish replacement run");

        let (cancel_graph_id, _) = create_graph(&store, 16);
        let cancel_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(cancel_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start cancel run");
        let cancel_request = store
            .request_recursive_scheduler_run_cancellation(
                cancel_run.id,
                RecursiveCancellationRequestCreate {
                    reason: "operator cancelled".to_string(),
                    requested_by: Some("test".to_string()),
                    source: RecursiveCancellationRequestSource::TestHarness,
                },
            )
            .expect("request run cancellation");
        store
            .cancel_recursive_scheduler_run(cancel_run.id, cancel_request.id, 0, None)
            .expect("cancel run");
        let replacement_cancel_run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(cancel_graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("cancelled run releases graph lease");
        store
            .finish_recursive_scheduler_run(
                replacement_cancel_run.id,
                RecursiveSchedulerStopReason::IdleNoRunnable,
                0,
                None,
            )
            .expect("finish replacement run");
    }

