    #[test]
    fn recursive_dag_scheduler_lease_heartbeat_updates_and_checks_token() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");
        let lease_token = run.lease_token.clone().expect("lease token");

        let error = store
            .heartbeat_recursive_scheduler_run_lease(run.id, "wrong-token", 60)
            .expect_err("bad lease token rejects");
        assert_error_contains(error, "lease token mismatch");

        let refreshed = store
            .heartbeat_recursive_scheduler_run_lease(run.id, &lease_token, 60)
            .expect("heartbeat lease");
        assert_eq!(refreshed.id, run.id);
        assert_eq!(refreshed.lease_token.as_deref(), Some(lease_token.as_str()));
        let original_heartbeat = run.lease_heartbeat_at.expect("original lease heartbeat");
        let refreshed_heartbeat = refreshed
            .lease_heartbeat_at
            .expect("refreshed lease heartbeat");
        let refreshed_expires = refreshed.lease_expires_at.expect("lease expires");
        assert!(refreshed_heartbeat >= original_heartbeat);
        assert!(refreshed_expires > refreshed_heartbeat);
    }

