    #[test]
    fn recursive_dag_scheduler_wrong_token_heartbeat_cannot_release_expired_run() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");
        let lease_token = run.lease_token.clone().expect("lease token");
        expire_scheduler_run_lease_direct(&store, run.id);

        let error = store
            .heartbeat_recursive_scheduler_run_lease(run.id, "wrong-token", 60)
            .expect_err("wrong token heartbeat rejects without reclaiming");
        assert_error_contains(error, "lease token mismatch");
        let still_running = store
            .load_recursive_scheduler_run(run.id)
            .expect("load run")
            .expect("run exists");
        assert_eq!(still_running.status, RecursiveSchedulerRunStatus::Running);
        assert_eq!(
            scheduler_run_event_count(&store, run.id, "lease_expired"),
            0
        );

        let error = store
            .heartbeat_recursive_scheduler_run_lease(run.id, &lease_token, 60)
            .expect_err("correct token after expiry rejects and terminalizes");
        assert_error_contains(error, "lease expired");
        let expired = store
            .load_recursive_scheduler_run(run.id)
            .expect("load run")
            .expect("run exists");
        assert_eq!(expired.status, RecursiveSchedulerRunStatus::LeaseExpired);
        assert_eq!(
            scheduler_run_event_count(&store, run.id, "lease_expired"),
            1
        );
    }

