    #[test]
    fn recursive_dag_cancellation_requests_round_trip_and_observe_idempotently() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_id),
                max_steps: 8,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start scheduler run");

        let request = store
            .request_recursive_scheduler_run_cancellation(
                run.id,
                RecursiveCancellationRequestCreate {
                    reason: "operator stop".to_string(),
                    requested_by: Some("test".to_string()),
                    source: RecursiveCancellationRequestSource::TestHarness,
                },
            )
            .expect("request run cancellation");
        assert_eq!(request.scope, RecursiveCancellationScope::Run);
        assert_eq!(
            request.status,
            RecursiveCancellationRequestStatus::Requested
        );
        assert_eq!(request.run_id, Some(run.id));

        let pending = store
            .list_pending_recursive_cancellation_requests_for_run(run.id)
            .expect("list pending run cancellations");
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].id, request.id);

        let observed = store
            .observe_recursive_cancellation_request(request.id, Some(run.id))
            .expect("observe cancellation");
        assert_eq!(
            observed.status,
            RecursiveCancellationRequestStatus::Observed
        );
        assert!(observed.observed_at.is_some());
        let observed_again = store
            .observe_recursive_cancellation_request(request.id, Some(run.id))
            .expect("observe cancellation again");
        assert_eq!(
            observed_again.status,
            RecursiveCancellationRequestStatus::Observed
        );
        assert_eq!(observed_again.observed_at, observed.observed_at);

        let task_request = store
            .request_recursive_task_cancellation(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveCancellationRequestCreate {
                    reason: "task repair later".to_string(),
                    requested_by: None,
                    source: RecursiveCancellationRequestSource::TestHarness,
                },
            )
            .expect("request task cancellation");
        assert_eq!(task_request.scope, RecursiveCancellationScope::Task);
        assert_eq!(
            task_request.status,
            RecursiveCancellationRequestStatus::Requested
        );
        let graph_pending = store
            .list_pending_recursive_cancellation_requests_for_graph(RecursiveTaskGraphId(graph_id))
            .expect("list graph pending cancellations");
        assert!(
            graph_pending
                .iter()
                .any(|request| request.id == task_request.id)
        );
    }

