    #[test]
    fn recursive_dag_lifecycle_transition_records_event_atomically() {
        let (_dir, store) = test_store();
        let (graph_id, root_id) = create_graph(&store, 16);
        let attempt_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Execute,
                attempt_id,
            )
            .expect("start attempt");

        store
            .transition_recursive_task_state(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveTaskLifecycleState::Running,
                Some("started".to_string()),
            )
            .expect("running transition");
        let events = store
            .load_recursive_task_lifecycle_events(RecursiveTaskGraphId(graph_id))
            .unwrap();
        assert_eq!(events.len(), 1);
        assert_eq!(events[0].from_status, RecursiveTaskLifecycleState::Pending);
        assert_eq!(events[0].to_status, RecursiveTaskLifecycleState::Running);

        let error = store
            .transition_recursive_task_state(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(Uuid::new_v4()),
                RecursiveTaskLifecycleState::Succeeded,
                Some("missing".to_string()),
            )
            .expect_err("missing task rejects");
        assert!(error.to_string().contains("not found"));
        let events_after = store
            .load_recursive_task_lifecycle_events(RecursiveTaskGraphId(graph_id))
            .unwrap();
        assert_eq!(events_after.len(), 1);
    }

    #[test]
    fn recursive_dag_failed_blocked_cancelled_state_writes_are_durable() {
        for (target, reason) in [
            (RecursiveTaskLifecycleState::Failed, "failed"),
            (RecursiveTaskLifecycleState::Blocked, "blocked"),
            (RecursiveTaskLifecycleState::Cancelled, "cancelled"),
        ] {
            let (_dir, store) = test_store();
            let (graph_id, root_id) = create_graph(&store, 16);
            match target {
                RecursiveTaskLifecycleState::Failed => {
                    store
                        .mark_recursive_task_failed(
                            RecursiveTaskGraphId(graph_id),
                            RecursiveTaskId(root_id),
                            reason.to_string(),
                        )
                        .expect("mark failed");
                }
                RecursiveTaskLifecycleState::Blocked => {
                    store
                        .mark_recursive_task_blocked(
                            RecursiveTaskGraphId(graph_id),
                            RecursiveTaskId(root_id),
                            reason.to_string(),
                        )
                        .expect("mark blocked");
                }
                RecursiveTaskLifecycleState::Cancelled => {
                    store
                        .mark_recursive_task_cancelled(
                            RecursiveTaskGraphId(graph_id),
                            RecursiveTaskId(root_id),
                            reason.to_string(),
                        )
                        .expect("mark cancelled");
                }
                _ => unreachable!(),
            }
            let task = store
                .load_recursive_task(RecursiveTaskGraphId(graph_id), RecursiveTaskId(root_id))
                .unwrap()
                .expect("task");
            assert_eq!(task.status, target);
            if target == RecursiveTaskLifecycleState::Cancelled {
                assert_eq!(task.blocked_reason, None);
            } else {
                assert_eq!(task.blocked_reason.as_deref(), Some(reason));
            }
            store
                .validate_recursive_task_graph_integrity(RecursiveTaskGraphId(graph_id))
                .expect("terminal graph remains valid");
        }
    }

