    #[test]
    fn recursive_dag_startup_recovery_quarantines_malformed_and_recovers_others() {
        let (_dir, store) = test_store();
        let (valid_graph_id, root_id) = create_graph(&store, 16);
        let attempt_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(valid_graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Execute,
                attempt_id,
            )
            .expect("start attempt");
        store
            .transition_recursive_task_state(
                RecursiveTaskGraphId(valid_graph_id),
                RecursiveTaskId(root_id),
                RecursiveTaskLifecycleState::Running,
                Some("started".to_string()),
            )
            .expect("running");

        let malformed_graph_id = Uuid::new_v4();
        let malformed_root_id = Uuid::new_v4();
        insert_graph(&store, malformed_graph_id, malformed_root_id);

        let report = store
            .recover_recursive_task_graphs_after_restart()
            .expect("startup recovery should not fail on malformed graph");

        assert_eq!(report.checked, 2);
        assert_eq!(report.recovered, 1);
        assert_eq!(report.quarantined, 1);
        let valid_detail = store
            .get_recursive_task_graph(RecursiveTaskGraphId(valid_graph_id))
            .unwrap()
            .unwrap();
        assert_eq!(
            valid_detail.attempts[0].status,
            RecursiveAttemptStatus::Interrupted
        );
        let malformed_detail = store
            .get_recursive_task_graph(RecursiveTaskGraphId(malformed_graph_id))
            .unwrap()
            .unwrap();
        assert_eq!(
            malformed_detail.graph.status,
            RecursiveGraphStatus::Malformed
        );
        assert!(malformed_detail.graph.quarantined_at.is_some());
    }

    fn recovery_budget(max_graphs: u32, time_budget_ms: Option<u64>) -> RecursiveRecoveryBudget {
        RecursiveRecoveryBudget {
            max_graphs,
            time_budget_ms,
            source: RecursiveRecoverySource::TestHarness,
        }
    }

    fn create_running_recovery_graph(
        store: &Store,
        graph_id: Uuid,
        root_id: Uuid,
    ) -> RecursiveAttemptId {
        store
            .create_recursive_task_graph(graph_create(graph_id, root_id, 16))
            .expect("create recovery graph");
        let attempt_id = RecursiveAttemptId(Uuid::new_v4());
        store
            .record_recursive_attempt_start(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveAttemptPhase::Execute,
                attempt_id,
            )
            .expect("start recovery attempt");
        store
            .transition_recursive_task_state(
                RecursiveTaskGraphId(graph_id),
                RecursiveTaskId(root_id),
                RecursiveTaskLifecycleState::Running,
                Some("started".to_string()),
            )
            .expect("mark running");
        attempt_id
    }

