    #[test]
    fn recursive_dag_budgeted_recovery_max_graphs_defers_remaining() {
        let (_dir, store) = test_store();
        let graph_1 = Uuid::from_u128(1);
        let graph_2 = Uuid::from_u128(2);
        let graph_3 = Uuid::from_u128(3);
        let root_1 = Uuid::from_u128(101);
        let root_2 = Uuid::from_u128(102);
        let root_3 = Uuid::from_u128(103);
        create_running_recovery_graph(&store, graph_1, root_1);
        create_running_recovery_graph(&store, graph_2, root_2);
        create_running_recovery_graph(&store, graph_3, root_3);

        let pass = store
            .recover_recursive_task_graphs_after_restart_with_budget(recovery_budget(1, None))
            .expect("budgeted recovery");

        assert_eq!(pass.status, RecursiveRecoveryPassStatus::Deferred);
        assert_eq!(
            pass.stop_reason,
            Some(RecursiveRecoveryStopReason::MaxGraphs)
        );
        assert_eq!(pass.checked, 1);
        assert_eq!(pass.recovered, 1);
        assert_eq!(pass.deferred, 2);

        let first_attempt = store
            .load_recursive_task_attempts(RecursiveTaskGraphId(graph_1))
            .unwrap()
            .pop()
            .unwrap();
        assert_eq!(first_attempt.status, RecursiveAttemptStatus::Interrupted);
        let second_attempt = store
            .load_recursive_task_attempts(RecursiveTaskGraphId(graph_2))
            .unwrap()
            .pop()
            .unwrap();
        assert_eq!(second_attempt.status, RecursiveAttemptStatus::Running);

        let deferred = store.list_deferred_recursive_recovery_graphs().unwrap();
        assert_eq!(deferred.len(), 2);
        assert_eq!(deferred[0].graph_id, Some(RecursiveTaskGraphId(graph_2)));
        assert_eq!(deferred[1].graph_id, Some(RecursiveTaskGraphId(graph_3)));
        assert!(deferred.iter().all(|graph| {
            graph.state == RecursiveGraphRecoveryState::Deferred
                && graph.reason == "max_graphs"
                && graph.last_attempted_at.is_none()
        }));
    }

