    #[test]
    fn recursive_dag_deferred_recovery_continuation_preserves_active_lease_and_cancellation() {
        let (_dir, store) = test_store();
        let graph_1 = Uuid::from_u128(91);
        let graph_2 = Uuid::from_u128(92);
        create_running_recovery_graph(&store, graph_1, Uuid::from_u128(191));
        create_running_recovery_graph(&store, graph_2, Uuid::from_u128(192));
        store
            .recover_recursive_task_graphs_after_restart_with_budget(recovery_budget(1, None))
            .expect("initial budgeted recovery");
        let run = store
            .start_recursive_scheduler_run(RecursiveSchedulerRunStart {
                graph_id: RecursiveTaskGraphId(graph_2),
                max_steps: 10,
                source: RecursiveSchedulerRunSource::TestHarness,
                operator: Some("test".to_string()),
                executor_mode: RecursiveExecutionMode::Fake,
            })
            .expect("start leased run");
        let request = store
            .request_recursive_scheduler_run_cancellation(
                run.id,
                RecursiveCancellationRequestCreate {
                    reason: "operator requested cancellation".to_string(),
                    requested_by: Some("test".to_string()),
                    source: RecursiveCancellationRequestSource::TestHarness,
                },
            )
            .expect("request cancellation");

        let pass = store
            .continue_deferred_recursive_recovery(recovery_budget(10, None))
            .expect("continue deferred recovery");

        assert_eq!(pass.status, RecursiveRecoveryPassStatus::Completed);
        assert_eq!(pass.checked, 1);
        assert_eq!(pass.recovered, 1);
        assert!(
            store
                .list_deferred_recursive_recovery_graphs()
                .unwrap()
                .is_empty()
        );
        let after = store.load_recursive_scheduler_run(run.id).unwrap().unwrap();
        assert_eq!(after.status, RecursiveSchedulerRunStatus::Cancelling);
        assert_eq!(after.lease_owner, run.lease_owner);
        assert_eq!(after.lease_token, run.lease_token);
        assert_eq!(after.lease_expires_at, run.lease_expires_at);
        assert_eq!(after.cancellation_request_id, Some(request.id));
        let loaded_request = store
            .load_recursive_cancellation_request(request.id)
            .unwrap()
            .unwrap();
        assert_eq!(
            loaded_request.status,
            RecursiveCancellationRequestStatus::Requested
        );
    }

