    #[test]
    fn recursive_dag_failed_recovery_pass_is_persisted_and_latest() {
        let (_dir, store) = test_store();
        store
            .conn
            .execute_batch("DROP TABLE recursive_recovery_graph_states")
            .expect("drop graph states table");

        let error = store
            .recover_recursive_task_graphs_after_restart_with_budget(recovery_budget(10, None))
            .expect_err("candidate load should fail");

        assert_error_contains(error, "recursive_recovery_graph_states");
        let latest = store
            .load_latest_recursive_recovery_pass()
            .expect("load latest pass")
            .expect("failed pass persisted");
        assert_eq!(latest.status, RecursiveRecoveryPassStatus::Failed);
        assert_eq!(
            latest.stop_reason,
            Some(RecursiveRecoveryStopReason::StoreError)
        );
        assert_eq!(latest.errors, 1);
        assert!(latest.completed_at.is_some());
        assert!(
            latest
                .error
                .as_deref()
                .unwrap_or_default()
                .contains("recursive_recovery_graph_states")
        );
    }

    #[test]
    fn recursive_dag_recovery_does_not_mutate_already_quarantined_graph() {
        let (_dir, store) = test_store();
        let (graph_id, _) = create_graph(&store, 16);
        store
            .quarantine_recursive_task_graph(
                RecursiveTaskGraphId(graph_id),
                "test quarantine".to_string(),
            )
            .expect("quarantine");
        let before = store
            .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .unwrap()
            .unwrap();
        let events_before = before.lifecycle_events.len();

        let result = store
            .recover_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .expect("recovery");

        assert!(!result.recovered);
        assert!(result.quarantined);
        let after = store
            .get_recursive_task_graph(RecursiveTaskGraphId(graph_id))
            .unwrap()
            .unwrap();
        assert_eq!(after.graph.updated_at, before.graph.updated_at);
        assert_eq!(after.graph.quarantined_at, before.graph.quarantined_at);
        assert_eq!(
            after.graph.quarantine_reason,
            before.graph.quarantine_reason
        );
        assert_eq!(after.lifecycle_events.len(), events_before);
    }

